	LOC_BGD_CHAT_RELINK_DETECTED = { en_US = "{1} and {2} are linked through the host (0 ms). Trying to connect them directly during the turn change.", fr_FR = "{1} et {2} passent par l'hôte (0 ms). Tentative de lien direct pendant le changement de tour.", de_DE = "{1} und {2} sind über den Host verbunden (0 ms). Direkte Verbindung wird beim Rundenwechsel versucht.", es_ES = "{1} y {2} están conectados a través del anfitrión (0 ms). Intentando conectarlos directamente durante el cambio de turno.", it_IT = "{1} e {2} sono collegati tramite l'host (0 ms). Tentativo di collegamento diretto durante il cambio di turno.", ja_JP = "{1}と{2}はホスト経由で接続されています（0 ms）。ターン切り替え中に直接接続を試みます。", ko_KR = "{1}와(과) {2}이(가) 호스트를 통해 연결되어 있습니다(0 ms). 턴 전환 중에 직접 연결을 시도합니다.", pl_PL = "{1} i {2} są połączeni przez hosta (0 ms). Próba bezpośredniego połączenia podczas zmiany tury.", pt_BR = "{1} e {2} estão conectados pelo anfitrião (0 ms). Tentando conectá-los diretamente durante a troca de turno.", ru_RU = "{1} и {2} соединены через хоста (0 мс). Попытка прямого соединения во время смены хода.", zh_Hans_CN = "{1} 和 {2} 通过主机连接（0 ms）。将在回合切换时尝试直接连接。" },
