	LOC_BGD_OPT_CHOIX_OUI = { en_US = "Yes", fr_FR = "Oui", de_DE = "Ja", es_ES = "Sí", it_IT = "Sì", ja_JP = "はい", ko_KR = "예", pl_PL = "Tak", pt_BR = "Sim", ru_RU = "Да", zh_Hans_CN = "是" },
