	LOC_BGD_OPT_CHOIX_VERIFICATION = { en_US = "Verification (diagnostic, slower)", fr_FR = "Vérification (diagnostic, plus lent)", de_DE = "Überprüfung (Diagnose, langsamer)", es_ES = "Verificación (diagnóstico, más lento)", it_IT = "Verifica (diagnostica, più lenta)", ja_JP = "検証 (診断、低速)", ko_KR = "검증 (진단, 느림)", pl_PL = "Weryfikacja (diagnostyka, wolniej)", pt_BR = "Verificação (diagnóstico, mais lento)", ru_RU = "Проверка (диагностика, медленнее)", zh_Hans_CN = "校验（诊断，较慢）" },
	LOC_BGD_OPT_CONFIG_GARDEE_AIDE = { en_US = "On a reload, the game rebuilds its configuration database and reverts its texts even when nothing changed since the last load. Both are kept when unchanged; the game rules are still reloaded as usual (about 3 s per reload). Takes effect at the next game launch.", fr_FR = "À un rechargement, le jeu reconstruit sa base de configuration et rétablit ses textes même si rien n'a changé depuis le dernier chargement. Les deux sont gardés s'ils n'ont pas changé ; les règles du jeu sont rechargées comme d'habitude (environ 3 s par rechargement). Prend effet au prochain lancement du jeu.", de_DE = "Beim Neuladen baut das Spiel seine Konfigurationsdatenbank neu auf und setzt seine Texte zurück, auch wenn sich seit dem letzten Laden nichts geändert hat. Beides wird behalten, wenn es unverändert ist; die Spielregeln werden wie gewohnt neu geladen (etwa 3 s pro Neuladen). Wirkt ab dem nächsten Spielstart.", es_ES = "Al recargar, el juego reconstruye su base de datos de configuración y restablece sus textos aunque nada haya cambiado desde la última carga. Ambos se conservan si no cambiaron; las reglas del juego se recargan como siempre (unos 3 s por recarga). Se aplica en el próximo inicio del juego.", it_IT = "A ogni ricaricamento, il gioco ricostruisce il database di configurazione e ripristina i suoi testi anche se nulla è cambiato dall'ultimo caricamento. Entrambi vengono mantenuti se invariati; le regole di gioco vengono ricaricate come sempre (circa 3 s per ricaricamento). Ha effetto al prossimo avvio del gioco.", ja_JP = "再読み込みのたびに、前回のロードから何も変わっていなくても、ゲームは構成データベースを作り直し、テキストを元に戻します。変更がなければ両方を保持します。ゲームのルールは通常どおり読み込み直されます（再読み込み1回あたり約3秒）。次回のゲーム起動時に有効になります。", ko_KR = "다시 불러올 때 게임은 마지막 로딩 이후 바뀐 것이 없어도 구성 데이터베이스를 다시 만들고 텍스트를 되돌립니다. 바뀐 것이 없으면 둘 다 유지하며, 게임 규칙은 평소처럼 다시 불러옵니다(다시 불러오기당 약 3초). 다음 게임 실행 시 적용됩니다.", pl_PL = "Przy ponownym wczytaniu gra odbudowuje bazę konfiguracji i przywraca swoje teksty, nawet jeśli od ostatniego wczytania nic się nie zmieniło. Jeśli się nie zmieniły, oba są zachowywane; zasady gry są wczytywane ponownie jak zwykle (około 3 s na ponowne wczytanie). Działa od następnego uruchomienia gry.", pt_BR = "Ao recarregar, o jogo reconstrói seu banco de dados de configuração e restaura seus textos mesmo que nada tenha mudado desde o último carregamento. Ambos são mantidos quando não mudaram; as regras do jogo são recarregadas normalmente (cerca de 3 s por recarga). Entra em vigor no próximo início do jogo.", ru_RU = "При перезагрузке игра заново строит базу конфигурации и откатывает свои тексты, даже если с последней загрузки ничего не изменилось. Если они не изменились, оба сохраняются; правила игры перезагружаются как обычно (около 3 с на перезагрузку). Вступает в силу при следующем запуске игры.", zh_Hans_CN = "重新加载时，即使自上次加载以来没有任何变化，游戏也会重建其配置数据库并还原其文本。两者未变化时将予以保留；游戏规则仍照常重新加载（每次重新加载约 3 秒）。下次启动游戏时生效。" },
	LOC_BGD_OPT_CONFIG_GARDEE_NOM = { en_US = "Keep the unchanged configuration on reloads", fr_FR = "Garder la configuration inchangée aux rechargements", de_DE = "Unveränderte Konfiguration beim Neuladen behalten", es_ES = "Conservar la configuración sin cambios al recargar", it_IT = "Mantenere la configurazione invariata ai ricaricamenti", ja_JP = "再読み込み時に変更のない構成を保持", ko_KR = "다시 불러올 때 변경 없는 구성 유지", pl_PL = "Zachowaj niezmienioną konfigurację przy ponownym wczytaniu", pt_BR = "Manter a configuração inalterada ao recarregar", ru_RU = "Сохранять неизменённую конфигурацию при перезагрузке", zh_Hans_CN = "重新加载时保留未更改的配置" },
	LOC_BGD_OPT_CREDITS_AUTEURS_BRS = { en_US = "{1}; original Units and Deals tabs: {2}; thanks: {3}", fr_FR = "{1} ; onglets Unités et Accords d'origine : {2} ; remerciements : {3}", de_DE = "{1}; ursprüngliche Reiter Einheiten und Abkommen: {2}; Dank an: {3}", es_ES = "{1}; pestañas originales Unidades y Acuerdos: {2}; agradecimientos: {3}", it_IT = "{1}; schede originali Unità e Accordi: {2}; ringraziamenti: {3}", ja_JP = "{1}、元のユニット・取引タブ: {2}、謝辞: {3}", ko_KR = "{1}; 원래 유닛·거래 탭: {2}; 감사: {3}", pl_PL = "{1}; oryginalne karty Jednostki i Umowy: {2}; podziękowania: {3}", pt_BR = "{1}; abas originais Unidades e Acordos: {2}; agradecimentos: {3}", ru_RU = "{1}; исходные вкладки «Отряды» и «Сделки»: {2}; благодарности: {3}", zh_Hans_CN = "{1}；原始单位和交易标签页：{2}；鸣谢：{3}" },
	LOC_BGD_OPT_CREDITS_AUTEURS_MERCI = { en_US = "{1}; thanks: {2}", fr_FR = "{1} ; remerciements : {2}", de_DE = "{1}; Dank an: {2}", es_ES = "{1}; agradecimientos: {2}", it_IT = "{1}; ringraziamenti: {2}", ja_JP = "{1}、謝辞: {2}", ko_KR = "{1}; 감사: {2}", pl_PL = "{1}; podziękowania: {2}", pt_BR = "{1}; agradecimentos: {2}", ru_RU = "{1}; благодарности: {2}", zh_Hans_CN = "{1}；鸣谢：{2}" },
	LOC_BGD_OPT_CREDITS_INTRO = { en_US = "The built-in interface mods build on their authors' work, with BetterGameExperience' thanks:", fr_FR = "Les mods d'interface intégrés reprennent le travail de leurs auteurs, que BetterGameExperience remercie :", de_DE = "Die integrierten Oberflächen-Mods bauen auf der Arbeit ihrer Autoren auf, denen BetterGameExperience dankt:", es_ES = "Los mods de interfaz integrados se basan en el trabajo de sus autores, a quienes BetterGameExperience da las gracias:", it_IT = "Le mod dell'interfaccia integrate riprendono il lavoro dei loro autori, che BetterGameExperience ringrazia:", ja_JP = "組み込みインターフェースMODは作者の成果に基づいています。BetterGameExperience より感謝します:", ko_KR = "내장 인터페이스 모드는 원작자들의 작업을 바탕으로 합니다. BetterGameExperience가 감사드립니다:", pl_PL = "Wbudowane mody interfejsu opierają się na pracy ich autorów, którym BetterGameExperience dziękuje:", pt_BR = "Os mods de interface integrados se baseiam no trabalho dos seus autores, a quem o BetterGameExperience agradece:", ru_RU = "Встроенные моды интерфейса основаны на работе их авторов, которых BetterGameExperience благодарит:", zh_Hans_CN = "内置界面模组基于其作者的成果，BetterGameExperience 在此致谢：" },
	LOC_BGD_OPT_CREDITS_LIGNE = { en_US = "{1} (Workshop {2}): {3}.", fr_FR = "{1} (Workshop {2}) : {3}.", de_DE = "{1} (Workshop {2}): {3}.", es_ES = "{1} (Workshop {2}): {3}.", it_IT = "{1} (Workshop {2}): {3}.", ja_JP = "{1} (Workshop {2}): {3}。", ko_KR = "{1} (Workshop {2}): {3}.", pl_PL = "{1} (Workshop {2}): {3}.", pt_BR = "{1} (Workshop {2}): {3}.", ru_RU = "{1} (Workshop {2}): {3}.", zh_Hans_CN = "{1}（Workshop {2}）：{3}。" },
	LOC_BGD_OPT_DELAUNAY_RAPIDE_AIDE = { en_US = "Map generation: the triangulation used to find choke points is computed by a faster equivalent, with exactly the same result (about 2 s per generated map). Verification: computes both, keeps the game's result and logs any difference.", fr_FR = "Génération de la carte : la triangulation qui sert à trouver les goulets est calculée par un équivalent plus rapide, au résultat identique (environ 2 s par carte générée). Vérification : calcule les deux, garde le résultat du jeu et note toute différence.", de_DE = "Kartenerzeugung: Die Triangulation zum Finden der Engpässe wird von einem schnelleren Äquivalent mit exakt demselben Ergebnis berechnet (etwa 2 s pro erzeugter Karte). Überprüfung: berechnet beides, behält das Ergebnis des Spiels und protokolliert jeden Unterschied.", es_ES = "Generación del mapa: la triangulación que sirve para encontrar los cuellos de botella se calcula con un equivalente más rápido, con exactamente el mismo resultado (unos 2 s por mapa generado). Verificación: calcula ambos, conserva el resultado del juego y registra cualquier diferencia.", it_IT = "Generazione della mappa: la triangolazione usata per trovare i colli di bottiglia viene calcolata da un equivalente più rapido, con esattamente lo stesso risultato (circa 2 s per mappa generata). Verifica: calcola entrambi, mantiene il risultato del gioco e registra ogni differenza.", ja_JP = "マップ生成：隘路を見つけるための三角形分割を、まったく同じ結果になる高速な同等処理で計算します（生成マップごとに約2秒）。検証：両方を計算し、ゲームの結果を使い、違いがあれば記録します。", ko_KR = "지도 생성: 병목 지점을 찾는 데 쓰는 삼각분할을 결과가 완전히 같은 더 빠른 방식으로 계산합니다(생성된 지도마다 약 2초). 검증: 둘 다 계산하고 게임의 결과를 유지하며 차이가 있으면 기록합니다.", pl_PL = "Generowanie mapy: triangulacja służąca do znajdowania przewężeń jest liczona szybszym odpowiednikiem o dokładnie tym samym wyniku (około 2 s na wygenerowaną mapę). Weryfikacja: liczy oba, zachowuje wynik gry i zapisuje każdą różnicę.", pt_BR = "Geração do mapa: a triangulação usada para encontrar os gargalos é calculada por um equivalente mais rápido, com exatamente o mesmo resultado (cerca de 2 s por mapa gerado). Verificação: calcula ambos, mantém o resultado do jogo e registra qualquer diferença.", ru_RU = "Генерация карты: триангуляция для поиска узких мест вычисляется более быстрым эквивалентом с точно таким же результатом (около 2 с на сгенерированную карту). Проверка: вычисляет оба варианта, оставляет результат игры и записывает любое расхождение.", zh_Hans_CN = "地图生成：用于寻找咽喉要道的三角剖分改用更快的等效算法计算，结果完全相同（每张生成的地图约 2 秒）。验证：两者都计算，保留游戏的结果并记录任何差异。" },
	LOC_BGD_OPT_DELAUNAY_RAPIDE_NOM = { en_US = "Fast choke point analysis", fr_FR = "Analyse des goulets rapide", de_DE = "Schnelle Engpassanalyse", es_ES = "Análisis rápido de cuellos de botella", it_IT = "Analisi rapida dei colli di bottiglia", ja_JP = "隘路分析の高速化", ko_KR = "빠른 병목 지점 분석", pl_PL = "Szybka analiza przewężeń", pt_BR = "Análise rápida de gargalos", ru_RU = "Быстрый анализ узких мест", zh_Hans_CN = "快速咽喉要道分析" },
	LOC_BGD_OPT_DEPART_SIGNAUX_AIDE = { en_US = "With the \"No First/Last moves (BGE)\" game option, machines exchange hidden chat messages (.bgd_pret, .bgd_depart, .bgd_fin). When on, they stay visible in your chat, with a line when the host ends the turn, to follow each turn start and end. Display only, on this machine.", fr_FR = "Avec l'option de partie « No First/Last moves (BGE) », les machines s'échangent des messages de chat cachés (.bgd_pret, .bgd_depart, .bgd_fin). Activé, ils restent visibles dans votre chat, avec une ligne quand l'hôte termine le tour, pour suivre le départ et la fin de chaque tour. Affichage seulement, sur cette machine.", de_DE = "Mit der Spieloption „No First/Last moves (BGE)“ tauschen die Rechner versteckte Chatnachrichten aus (.bgd_pret, .bgd_depart, .bgd_fin). Wenn aktiviert, bleiben sie in Ihrem Chat sichtbar, mit einer Zeile, wenn der Host die Runde beendet, um Beginn und Ende jeder Runde zu verfolgen. Nur Anzeige, auf diesem Rechner.", es_ES = "Con la opción de partida «No First/Last moves (BGE)», los equipos intercambian mensajes de chat ocultos (.bgd_pret, .bgd_depart, .bgd_fin). Si se activa, quedan visibles en tu chat, con una línea cuando el anfitrión termina el turno, para seguir el inicio y el final de cada turno. Solo visualización, en este equipo.", it_IT = "Con l'opzione di partita \"No First/Last moves (BGE)\", i computer si scambiano messaggi di chat nascosti (.bgd_pret, .bgd_depart, .bgd_fin). Se attivato, restano visibili nella tua chat, con una riga quando l'host termina il turno, per seguire l'inizio e la fine di ogni turno. Solo visualizzazione, su questo computer.", ja_JP = "ゲームオプション「No First/Last moves (BGE)」では、各PCが非表示のチャットメッセージ (.bgd_pret、.bgd_depart、.bgd_fin) をやり取りします。有効にすると、それらがチャットに表示されたままになり、ホストがターンを終えたときにも1行表示されるので、各ターンの開始と終了を追えます。このPCでの表示のみ。", ko_KR = "게임 옵션 \"No First/Last moves (BGE)\"를 쓰면 각 컴퓨터가 숨겨진 채팅 메시지(.bgd_pret, .bgd_depart, .bgd_fin)를 주고받습니다. 켜면 이 메시지가 채팅에 그대로 보이고, 호스트가 턴을 끝낼 때도 한 줄이 표시되어 각 턴의 시작과 끝을 따라갈 수 있습니다. 이 컴퓨터에서의 표시만 바뀝니다.", pl_PL = "Z opcją gry „No First/Last moves (BGE)” komputery wymieniają ukryte wiadomości czatu (.bgd_pret, .bgd_depart, .bgd_fin). Po włączeniu pozostają widoczne w twoim czacie, z wierszem, gdy host kończy turę, aby śledzić początek i koniec każdej tury. Tylko wyświetlanie, na tym komputerze.", pt_BR = "Com a opção de partida \"No First/Last moves (BGE)\", os computadores trocam mensagens de chat ocultas (.bgd_pret, .bgd_depart, .bgd_fin). Quando ativado, elas ficam visíveis no seu chat, com uma linha quando o anfitrião termina o turno, para acompanhar o início e o fim de cada turno. Apenas exibição, neste computador.", ru_RU = "С параметром партии «No First/Last moves (BGE)» компьютеры обмениваются скрытыми сообщениями чата (.bgd_pret, .bgd_depart, .bgd_fin). Если включено, они остаются видимыми в вашем чате, со строкой, когда хост завершает ход, чтобы следить за началом и концом каждого хода. Только отображение, на этом компьютере.", zh_Hans_CN = "使用游戏选项“No First/Last moves (BGE)”时，各台电脑会互发隐藏的聊天消息（.bgd_pret、.bgd_depart、.bgd_fin）。开启后，这些消息会留在你的聊天中，主机结束回合时还会显示一行，便于跟踪每回合的开始和结束。仅影响本机显示。" },
	LOC_BGD_OPT_DEPART_SIGNAUX_NOM = { en_US = "Show simultaneous turn start and end signals", fr_FR = "Afficher les signaux du départ et de la fin simultanés", de_DE = "Signale des gleichzeitigen Rundenbeginns und -endes anzeigen", es_ES = "Mostrar las señales del inicio y del final simultáneos", it_IT = "Mostra i segnali dell'inizio e della fine simultanei", ja_JP = "同時開始・同時終了の信号を表示", ko_KR = "동시 시작·종료 신호 표시", pl_PL = "Pokazuj sygnały jednoczesnego początku i końca tury", pt_BR = "Mostrar os sinais do início e do fim simultâneos", ru_RU = "Показывать сигналы одновременного начала и конца хода", zh_Hans_CN = "显示同时开始与结束回合的信号" },
	LOC_BGD_OPT_DIAG_PRODUCTION_AIDE = { en_US = "Writes to the proxy log how the production kept in reserve (overflow) is read for each city, and to Lua.log how the district discount badge is computed, to analyze reports BGE-E6DF54 and BGE-36E0D7.", fr_FR = "Écrit dans le journal du proxy comment la production en réserve (débordement) est lue pour chaque ville, et dans Lua.log comment le badge des quartiers en réduction est calculé, pour analyser les rapports BGE-E6DF54 et BGE-36E0D7.", de_DE = "Schreibt ins Proxy-Protokoll, wie die zurückgehaltene Produktion (Überschuss) für jede Stadt gelesen wird, und in Lua.log, wie das Abzeichen der vergünstigten Bezirke berechnet wird, um die Berichte BGE-E6DF54 und BGE-36E0D7 zu analysieren.", es_ES = "Escribe en el registro del proxy cómo se lee la producción en reserva (excedente) de cada ciudad, y en Lua.log cómo se calcula la insignia de los distritos con descuento, para analizar los informes BGE-E6DF54 y BGE-36E0D7.", it_IT = "Scrive nel registro del proxy come viene letta la produzione in riserva (eccedenza) di ogni città, e in Lua.log come viene calcolato il badge dei distretti scontati, per analizzare le segnalazioni BGE-E6DF54 e BGE-36E0D7.", ja_JP = "各都市の繰越生産力（オーバーフロー）の読み取りをプロキシのログに、割引区域バッジの計算をLua.logに書き込み、報告 BGE-E6DF54 と BGE-36E0D7 を分析します。", ko_KR = "각 도시의 이월 생산력(오버플로)을 읽는 과정을 프록시 로그에, 할인 구역 배지 계산을 Lua.log에 기록하여 보고서 BGE-E6DF54와 BGE-36E0D7을 분석합니다.", pl_PL = "Zapisuje w dzienniku proxy, jak odczytywana jest produkcja w rezerwie (nadwyżka) każdego miasta, a w Lua.log, jak obliczana jest odznaka dzielnic ze zniżką, aby przeanalizować zgłoszenia BGE-E6DF54 i BGE-36E0D7.", pt_BR = "Escreve no registro do proxy como a produção em reserva (excedente) de cada cidade é lida, e no Lua.log como o selo dos distritos com desconto é calculado, para analisar os relatórios BGE-E6DF54 e BGE-36E0D7.", ru_RU = "Записывает в журнал прокси, как считывается производство в резерве (избыток) каждого города, а в Lua.log — как вычисляется значок районов со скидкой, для анализа отчётов BGE-E6DF54 и BGE-36E0D7.", zh_Hans_CN = "将各城市储备生产力（溢出）的读取过程写入代理日志，将折扣区域徽章的计算过程写入 Lua.log，用于分析报告 BGE-E6DF54 和 BGE-36E0D7。" },
	LOC_BGD_OPT_DIAG_PRODUCTION_NOM = { en_US = "Production overflow and district discount diagnostics", fr_FR = "Diagnostic de la réserve de production et des quartiers en réduction", de_DE = "Diagnose der Produktionsreserve und der vergünstigten Bezirke", es_ES = "Diagnóstico de la producción en reserva y los distritos con descuento", it_IT = "Diagnostica della produzione in riserva e dei distretti scontati", ja_JP = "生産の繰越と割引区域の診断", ko_KR = "생산력 이월 및 할인 구역 진단", pl_PL = "Diagnostyka produkcji w rezerwie i dzielnic ze zniżką", pt_BR = "Diagnóstico da produção em reserva e dos distritos com desconto", ru_RU = "Диагностика резерва производства и районов со скидкой", zh_Hans_CN = "生产储备与折扣区域诊断" },
	LOC_BGD_OPT_GARDE_MESSAGES_AIDE = { en_US = "Replaces impossible counts in network messages with 0 (the freeze when a player disconnects). Test: injects the freeze count once into a real message, to watch the guard act in a game played alone; that message is then lost. Diagnostic only: the release always has the guard. Takes effect at the next game launch.", fr_FR = "Remplace par 0 les comptes impossibles des messages réseau (le gel à la déconnexion d'un joueur). Test : injecte une fois le compte du gel dans un vrai message, pour voir la garde agir dans une partie jouée seul ; ce message est alors perdu. Diagnostic seulement : la release a toujours la garde. Prend effet au prochain lancement du jeu.", de_DE = "Ersetzt unmögliche Zähler in Netzwerknachrichten durch 0 (das Einfrieren, wenn ein Spieler die Verbindung trennt). Test: fügt einmal den Zähler des Einfrierens in eine echte Nachricht ein, um den Schutz in einer allein gespielten Partie wirken zu sehen; diese Nachricht geht dann verloren. Nur Diagnose: die Release hat den Schutz immer. Wirkt ab dem nächsten Spielstart.", es_ES = "Sustituye por 0 los recuentos imposibles de los mensajes de red (el bloqueo cuando un jugador se desconecta). Prueba: inyecta una vez el recuento del bloqueo en un mensaje real, para ver actuar la protección en una partida jugada solo; ese mensaje se pierde. Solo diagnóstico: la versión publicada siempre tiene la protección. Se aplica en el próximo inicio del juego.", it_IT = "Sostituisce con 0 i conteggi impossibili dei messaggi di rete (il blocco quando un giocatore si disconnette). Test: inietta una volta il conteggio del blocco in un messaggio reale, per vedere agire la protezione in una partita giocata da soli; quel messaggio va perso. Solo diagnostica: la release ha sempre la protezione. Effettivo dal prossimo avvio del gioco.", ja_JP = "ネットワークメッセージ内のありえない件数を0に置き換えます（プレイヤー切断時のフリーズ対策）。テスト：フリーズの件数を一度だけ実際のメッセージに注入し、一人でプレイするゲームで保護の動作を確認します。そのメッセージは失われます。診断専用：リリース版では常に保護が有効です。次回のゲーム起動時に反映されます。", ko_KR = "네트워크 메시지의 불가능한 개수를 0으로 바꿉니다(플레이어 연결 끊김 시 멈춤 대책). 테스트: 멈춤의 개수를 실제 메시지에 한 번 주입하여 혼자 하는 게임에서 보호가 작동하는지 확인합니다. 그 메시지는 손실됩니다. 진단 전용: 릴리스에는 항상 보호가 있습니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Zastępuje zerem niemożliwe liczniki w wiadomościach sieciowych (zawieszenie przy rozłączeniu gracza). Test: raz wstrzykuje licznik zawieszenia do prawdziwej wiadomości, aby zobaczyć działanie ochrony w grze rozgrywanej samemu; ta wiadomość przepada. Tylko diagnostyka: wydanie zawsze ma ochronę. Działa od następnego uruchomienia gry.", pt_BR = "Substitui por 0 as contagens impossíveis das mensagens de rede (o congelamento quando um jogador se desconecta). Teste: injeta uma vez a contagem do congelamento em uma mensagem real, para ver a proteção agir em uma partida jogada sozinho; essa mensagem é perdida. Apenas diagnóstico: a versão publicada sempre tem a proteção. Vale a partir da próxima abertura do jogo.", ru_RU = "Заменяет нулём невозможные счётчики в сетевых сообщениях (зависание при отключении игрока). Тест: один раз подставляет счётчик зависания в настоящее сообщение, чтобы увидеть работу защиты в игре в одиночку; это сообщение теряется. Только диагностика: в релизе защита всегда включена. Действует со следующего запуска игры.", zh_Hans_CN = "将网络消息中不可能的计数替换为 0（玩家断开连接时的卡死）。测试：向一条真实消息注入一次卡死计数，以便在单人游戏中观察保护生效；该消息随之丢失。仅限诊断：发布版始终启用保护。下次启动游戏时生效。" },
	LOC_BGD_OPT_GARDE_MESSAGES_NOM = { en_US = "Network message guard", fr_FR = "Garde des messages réseau", de_DE = "Schutz der Netzwerknachrichten", es_ES = "Protección de los mensajes de red", it_IT = "Protezione dei messaggi di rete", ja_JP = "ネットワークメッセージの保護", ko_KR = "네트워크 메시지 보호", pl_PL = "Ochrona wiadomości sieciowych", pt_BR = "Proteção das mensagens de rede", ru_RU = "Защита сетевых сообщений", zh_Hans_CN = "网络消息保护" },
	LOC_BGD_OPT_GC_EN_LOT_AIDE = { en_US = "When the game closes its interface (leaving a game, Multiplayer Helper remap), it runs a full Lua garbage collection for every released script function. A single one is run at the end instead. Saves about 2 s before a remap. Interface only, no effect on the game. Takes effect at the next game launch.", fr_FR = "Quand le jeu ferme son interface (sortie de partie, remap de Multiplayer Helper), il fait un ramasse-miettes Lua complet pour chaque fonction de script libérée. Un seul est fait à la fin. Fait gagner environ 2 s avant un remap. Interface seulement, sans effet sur la partie. Prend effet au prochain lancement du jeu.", de_DE = "Wenn das Spiel seine Oberfläche schließt (Verlassen einer Partie, Remap von Multiplayer Helper), führt es für jede freigegebene Skriptfunktion eine vollständige Lua-Speicherbereinigung aus. Stattdessen wird am Ende eine einzige ausgeführt. Spart etwa 2 s vor einem Remap. Nur Oberfläche, ohne Auswirkung auf die Partie. Wirkt ab dem nächsten Spielstart.", es_ES = "Cuando el juego cierra su interfaz (salir de una partida, remap de Multiplayer Helper), ejecuta una recolección de basura de Lua completa por cada función de script liberada. En su lugar se ejecuta una sola al final. Ahorra unos 2 s antes de un remap. Solo interfaz, sin efecto en la partida. Se aplica en el próximo inicio del juego.", it_IT = "Quando il gioco chiude la sua interfaccia (uscita da una partita, remap di Multiplayer Helper), esegue una garbage collection Lua completa per ogni funzione di script rilasciata. Ne viene eseguita una sola alla fine. Fa risparmiare circa 2 s prima di un remap. Solo interfaccia, nessun effetto sulla partita. Ha effetto al prossimo avvio del gioco.", ja_JP = "ゲームがUIを閉じるとき（ゲームの終了、Multiplayer Helperのリマップ）、解放されるスクリプト関数ごとにLuaの完全なガベージコレクションを実行します。代わりに最後に1回だけ実行します。リマップ前に約2秒短縮されます。UIのみで、ゲームには影響しません。次回のゲーム起動時に有効になります。", ko_KR = "게임이 인터페이스를 닫을 때(게임 나가기, Multiplayer Helper 리맵) 해제되는 스크립트 함수마다 Lua 전체 가비지 컬렉션을 실행합니다. 대신 마지막에 한 번만 실행합니다. 리맵 전에 약 2초를 줄여 줍니다. 인터페이스 전용이며 게임에는 영향이 없습니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Gdy gra zamyka swój interfejs (wyjście z gry, remap Multiplayer Helper), wykonuje pełne odśmiecanie Lua dla każdej zwalnianej funkcji skryptu. Zamiast tego na końcu wykonywane jest jedno. Oszczędza około 2 s przed remapem. Tylko interfejs, bez wpływu na grę. Działa od następnego uruchomienia gry.", pt_BR = "Quando o jogo fecha sua interface (sair de uma partida, remap do Multiplayer Helper), ele executa uma coleta de lixo Lua completa para cada função de script liberada. Em vez disso, uma única é executada no final. Economiza cerca de 2 s antes de um remap. Apenas interface, sem efeito na partida. Entra em vigor no próximo início do jogo.", ru_RU = "Когда игра закрывает интерфейс (выход из партии, ремап Multiplayer Helper), она выполняет полную сборку мусора Lua для каждой освобождаемой функции скрипта. Вместо этого выполняется одна в конце. Экономит около 2 с перед ремапом. Только интерфейс, без влияния на партию. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "游戏关闭界面时（退出游戏、Multiplayer Helper 重新生成地图），会为每个释放的脚本函数执行一次完整的 Lua 垃圾回收。改为在最后只执行一次。重新生成地图前可节省约 2 秒。仅限界面，不影响游戏。下次启动游戏时生效。" },
	LOC_BGD_OPT_GC_EN_LOT_NOM = { en_US = "One Lua cleanup when closing the interface", fr_FR = "Un seul nettoyage Lua à la fermeture de l'interface", de_DE = "Eine Lua-Bereinigung beim Schließen der Oberfläche", es_ES = "Una sola limpieza de Lua al cerrar la interfaz", it_IT = "Una sola pulizia Lua alla chiusura dell'interfaccia", ja_JP = "UI終了時のLuaクリーンアップを1回に", ko_KR = "인터페이스 종료 시 Lua 정리 한 번만", pl_PL = "Jedno czyszczenie Lua przy zamykaniu interfejsu", pt_BR = "Uma única limpeza de Lua ao fechar a interface", ru_RU = "Одна очистка Lua при закрытии интерфейса", zh_Hans_CN = "关闭界面时只清理一次 Lua" },
	LOC_BGD_OPT_INSTALLE = { en_US = "GameCore proxy installed.", fr_FR = "Proxy de GameCore installé.", de_DE = "GameCore-Proxy installiert.", es_ES = "Proxy de GameCore instalado.", it_IT = "Proxy di GameCore installato.", ja_JP = "GameCore プロキシはインストール済みです。", ko_KR = "GameCore 프록시가 설치되어 있습니다.", pl_PL = "Proxy GameCore jest zainstalowane.", pt_BR = "Proxy do GameCore instalado.", ru_RU = "Прокси GameCore установлен.", zh_Hans_CN = "GameCore 代理已安装。" },
	LOC_BGD_OPT_JOURNAL_CHOKEPOINTS_AIDE = { en_US = "When a map is generated, the game writes its whole choke point graph to AI_ChokePoint.csv (about 12 MB, 0.35 s). Off: the file is not written. No effect on the map or the game.", fr_FR = "À la génération d'une carte, le jeu écrit tout son graphe de goulets dans AI_ChokePoint.csv (environ 12 Mo, 0,35 s). Désactivé : le fichier n'est pas écrit. Sans effet sur la carte ni sur la partie.", de_DE = "Beim Erzeugen einer Karte schreibt das Spiel seinen gesamten Engpassgraphen in AI_ChokePoint.csv (etwa 12 MB, 0,35 s). Aus: Die Datei wird nicht geschrieben. Ohne Auswirkung auf die Karte oder die Partie.", es_ES = "Al generar un mapa, el juego escribe todo su grafo de cuellos de botella en AI_ChokePoint.csv (unos 12 MB, 0,35 s). Desactivado: el archivo no se escribe. Sin efecto en el mapa ni en la partida.", it_IT = "Alla generazione di una mappa, il gioco scrive l'intero grafo dei colli di bottiglia in AI_ChokePoint.csv (circa 12 MB, 0,35 s). Disattivato: il file non viene scritto. Nessun effetto sulla mappa o sulla partita.", ja_JP = "マップ生成時、ゲームは隘路グラフ全体を AI_ChokePoint.csv に書き込みます（約12 MB、0.35秒）。オフ：ファイルを書き込みません。マップやゲームには影響しません。", ko_KR = "지도를 생성할 때 게임은 병목 지점 그래프 전체를 AI_ChokePoint.csv에 씁니다(약 12MB, 0.35초). 끔: 파일을 쓰지 않습니다. 지도나 게임에는 영향이 없습니다.", pl_PL = "Podczas generowania mapy gra zapisuje cały graf przewężeń do AI_ChokePoint.csv (około 12 MB, 0,35 s). Wyłączone: plik nie jest zapisywany. Bez wpływu na mapę i grę.", pt_BR = "Ao gerar um mapa, o jogo grava todo o seu grafo de gargalos em AI_ChokePoint.csv (cerca de 12 MB, 0,35 s). Desativado: o arquivo não é gravado. Sem efeito no mapa ou na partida.", ru_RU = "При генерации карты игра записывает весь граф узких мест в AI_ChokePoint.csv (около 12 МБ, 0,35 с). Выкл.: файл не записывается. Без влияния на карту и партию.", zh_Hans_CN = "生成地图时，游戏会把整个咽喉要道图写入 AI_ChokePoint.csv（约 12 MB，0.35 秒）。关闭：不写入该文件。不影响地图和游戏。" },
	LOC_BGD_OPT_JOURNAL_CHOKEPOINTS_NOM = { en_US = "Write the AI choke point log", fr_FR = "Écrire le journal des goulets de l'IA", de_DE = "KI-Engpassprotokoll schreiben", es_ES = "Escribir el registro de cuellos de botella de la IA", it_IT = "Scrivi il registro dei colli di bottiglia dell'IA", ja_JP = "AIの隘路ログを書き込む", ko_KR = "AI 병목 지점 로그 쓰기", pl_PL = "Zapisuj dziennik przewężeń SI", pt_BR = "Gravar o registro de gargalos da IA", ru_RU = "Записывать журнал узких мест ИИ", zh_Hans_CN = "写入 AI 咽喉要道日志" },
	LOC_BGD_OPT_LECTURE_IMPOSSIBLE = { en_US = "Cannot read the settings: {1}", fr_FR = "Lecture des réglages impossible : {1}", de_DE = "Einstellungen können nicht gelesen werden: {1}", es_ES = "No se pueden leer los ajustes: {1}", it_IT = "Impossibile leggere le impostazioni: {1}", ja_JP = "設定を読み込めません: {1}", ko_KR = "설정을 읽을 수 없습니다: {1}", pl_PL = "Nie można odczytać ustawień: {1}", pt_BR = "Não foi possível ler as configurações: {1}", ru_RU = "Не удалось прочитать настройки: {1}", zh_Hans_CN = "无法读取设置：{1}" },
	LOC_BGD_OPT_MASQUER_AVANCEES = { en_US = "Hide advanced options", fr_FR = "Masquer les options avancées", de_DE = "Erweiterte Optionen ausblenden", es_ES = "Ocultar las opciones avanzadas", it_IT = "Nascondi le opzioni avanzate", ja_JP = "詳細オプションを隠す", ko_KR = "고급 옵션 숨기기", pl_PL = "Ukryj opcje zaawansowane", pt_BR = "Ocultar as opções avançadas", ru_RU = "Скрыть дополнительные настройки", zh_Hans_CN = "隐藏高级选项" },
	LOC_BGD_OPT_MODE_AIDE = { en_US = "During a cascade of war declarations, city and diplomacy data are refreshed only once, at the end: over 2 s saved on a heavy turn. Does not change the game: safe in multiplayer, even against players without the proxy.", fr_FR = "Pendant une cascade de déclarations de guerre, les données de villes et de diplomatie ne sont rafraîchies qu'une fois, à la fin : plus de 2 s gagnées sur un gros passage de tour. Ne change rien à la partie : sans risque en multijoueur, même face à des joueurs sans proxy.", de_DE = "Während einer Kaskade von Kriegserklärungen werden Stadt- und Diplomatiedaten nur einmal am Ende aktualisiert: über 2 s Ersparnis bei einer schweren Runde. Ändert nichts am Spiel: sicher im Mehrspielermodus, auch gegen Spieler ohne Proxy.", es_ES = "Durante una cascada de declaraciones de guerra, los datos de ciudades y de diplomacia solo se actualizan una vez, al final: más de 2 s ahorrados en un turno pesado. No cambia nada de la partida: seguro en multijugador, incluso contra jugadores sin el proxy.", it_IT = "Durante una cascata di dichiarazioni di guerra, i dati delle città e della diplomazia vengono aggiornati una sola volta, alla fine: oltre 2 s risparmiati in un turno pesante. Non cambia nulla della partita: sicuro in multigiocatore, anche contro giocatori senza il proxy.", ja_JP = "宣戦布告が連鎖する間、都市と外交のデータは最後に一度だけ更新されます。重いターンで2秒以上短縮されます。ゲーム内容は変わらないため、プロキシを持たないプレイヤーとのマルチプレイでも安全です。", ko_KR = "연쇄 선전포고가 일어나는 동안 도시와 외교 데이터를 마지막에 한 번만 갱신합니다. 무거운 턴에서 2초 이상 단축됩니다. 게임 내용은 바뀌지 않으므로, 프록시가 없는 플레이어와의 멀티플레이에서도 안전합니다.", pl_PL = "Podczas kaskady wypowiedzeń wojny dane miast i dyplomacji są odświeżane tylko raz, na końcu: ponad 2 s oszczędności w ciężkiej turze. Nie zmienia niczego w rozgrywce: bezpieczne w trybie wieloosobowym, także z graczami bez proxy.", pt_BR = "Durante uma cascata de declarações de guerra, os dados de cidades e de diplomacia são atualizados só uma vez, no final: mais de 2 s economizados num turno pesado. Não muda nada na partida: seguro no multijogador, mesmo contra jogadores sem o proxy.", ru_RU = "Во время каскада объявлений войны данные городов и дипломатии обновляются только один раз, в конце: более 2 с экономии на тяжёлом ходу. Ничего не меняет в партии: безопасно в сетевой игре, даже с игроками без прокси.", zh_Hans_CN = "在连锁宣战期间，城市和外交数据只在最后刷新一次：繁重的回合可节省 2 秒以上。不改变游戏内容：在多人游戏中安全，即使对方没有代理。" },
	LOC_BGD_OPT_MODE_NOM = { en_US = "Batched city updates", fr_FR = "Regroupement des mises à jour de villes", de_DE = "Gebündelte Stadt-Aktualisierungen", es_ES = "Actualizaciones de ciudades agrupadas", it_IT = "Aggiornamenti delle città raggruppati", ja_JP = "都市の更新をまとめる", ko_KR = "도시 갱신 묶기", pl_PL = "Zgrupowane aktualizacje miast", pt_BR = "Atualizações de cidades agrupadas", ru_RU = "Объединённые обновления городов", zh_Hans_CN = "合并城市更新" },
	LOC_BGD_OPT_MORCEAUX_RESEAU_AIDE = { en_US = "Size of the pieces large network messages are cut into, 1166 bytes in the game. Test between two machines only: every machine of the game must have the same value, otherwise the game is corrupted. Game version 1.0.12.58 only. Takes effect at the next game launch.", fr_FR = "Taille des morceaux en lesquels les gros messages réseau sont découpés, 1166 octets dans le jeu. Essai entre deux machines seulement : toutes les machines de la partie doivent avoir la même valeur, sinon la partie se corrompt. Version 1.0.12.58 du jeu seulement. Prend effet au prochain lancement du jeu.", de_DE = "Größe der Stücke, in die große Netzwerknachrichten zerlegt werden, im Spiel 1166 Bytes. Nur für einen Test zwischen zwei Rechnern: Alle Rechner der Partie müssen denselben Wert haben, sonst wird die Partie beschädigt. Nur Spielversion 1.0.12.58. Wirkt beim nächsten Spielstart.", es_ES = "Tamaño de los fragmentos en que se dividen los mensajes de red grandes, 1166 bytes en el juego. Solo para una prueba entre dos equipos: todos los equipos de la partida deben tener el mismo valor, si no la partida se corrompe. Solo versión 1.0.12.58 del juego. Se aplica en el próximo inicio del juego.", it_IT = "Dimensione dei pezzi in cui vengono divisi i grandi messaggi di rete, 1166 byte nel gioco. Solo per una prova tra due computer: tutti i computer della partita devono avere lo stesso valore, altrimenti la partita si corrompe. Solo versione 1.0.12.58 del gioco. Ha effetto al prossimo avvio del gioco.", ja_JP = "大きなネットワークメッセージを分割する単位のサイズで、ゲームでは1166バイトです。2台のマシン間のテスト専用：ゲームのすべてのマシンで同じ値にする必要があり、そうでないとゲームが壊れます。ゲームのバージョン1.0.12.58のみ。次回のゲーム起動時に有効になります。", ko_KR = "큰 네트워크 메시지를 나누는 조각의 크기로, 게임에서는 1166바이트입니다. 두 컴퓨터 간 테스트 전용: 게임의 모든 컴퓨터가 같은 값을 가져야 하며, 그렇지 않으면 게임이 손상됩니다. 게임 버전 1.0.12.58 전용. 다음 게임 실행 시 적용됩니다.", pl_PL = "Rozmiar fragmentów, na które dzielone są duże wiadomości sieciowe, w grze 1166 bajtów. Tylko do testu między dwoma komputerami: wszystkie komputery w rozgrywce muszą mieć tę samą wartość, inaczej rozgrywka zostanie uszkodzona. Tylko wersja gry 1.0.12.58. Działa od następnego uruchomienia gry.", pt_BR = "Tamanho dos pedaços em que as mensagens de rede grandes são divididas, 1166 bytes no jogo. Apenas para um teste entre duas máquinas: todas as máquinas da partida devem ter o mesmo valor, senão a partida é corrompida. Apenas a versão 1.0.12.58 do jogo. Entra em vigor na próxima vez que o jogo for iniciado.", ru_RU = "Размер фрагментов, на которые делятся большие сетевые сообщения, в игре 1166 байт. Только для теста между двумя компьютерами: у всех компьютеров партии должно быть одинаковое значение, иначе партия будет повреждена. Только версия игры 1.0.12.58. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "大型网络消息被切分成的块的大小，游戏中为 1166 字节。仅用于两台电脑之间的测试：游戏中的所有电脑必须使用相同的值，否则游戏会损坏。仅限游戏版本 1.0.12.58。下次启动游戏时生效。" },
	LOC_BGD_OPT_MORCEAUX_RESEAU_NOM = { en_US = "Network chunk size (test)", fr_FR = "Taille des morceaux réseau (essai)", de_DE = "Größe der Netzwerkstücke (Test)", es_ES = "Tamaño de los fragmentos de red (prueba)", it_IT = "Dimensione dei pezzi di rete (prova)", ja_JP = "ネットワーク分割サイズ（テスト）", ko_KR = "네트워크 조각 크기(테스트)", pl_PL = "Rozmiar fragmentów sieciowych (test)", pt_BR = "Tamanho dos pedaços de rede (teste)", ru_RU = "Размер сетевых фрагментов (тест)", zh_Hans_CN = "网络分块大小（测试）" },
	LOC_BGD_OPT_NON_ENREGISTRES = { en_US = "Settings not saved: {1}", fr_FR = "Réglages non enregistrés : {1}", de_DE = "Einstellungen nicht gespeichert: {1}", es_ES = "Ajustes no guardados: {1}", it_IT = "Impostazioni non salvate: {1}", ja_JP = "設定を保存できませんでした: {1}", ko_KR = "설정을 저장하지 못했습니다: {1}", pl_PL = "Ustawienia nie zostały zapisane: {1}", pt_BR = "Configurações não salvas: {1}", ru_RU = "Настройки не сохранены: {1}", zh_Hans_CN = "设置未保存：{1}" },
	LOC_BGD_OPT_NON_INSTALLE = { en_US = "GameCore proxy not installed: these settings will only take effect once it is installed.", fr_FR = "Proxy de GameCore non installé : ces réglages n'auront d'effet qu'une fois installé.", de_DE = "GameCore-Proxy nicht installiert: Diese Einstellungen wirken erst, wenn er installiert ist.", es_ES = "Proxy de GameCore no instalado: estos ajustes solo surtirán efecto una vez instalado.", it_IT = "Proxy di GameCore non installato: queste impostazioni avranno effetto solo una volta installato.", ja_JP = "GameCore プロキシがインストールされていません。これらの設定はインストール後に有効になります。", ko_KR = "GameCore 프록시가 설치되어 있지 않습니다. 이 설정은 설치한 뒤에 적용됩니다.", pl_PL = "Proxy GameCore nie jest zainstalowane: te ustawienia zaczną działać dopiero po jego instalacji.", pt_BR = "Proxy do GameCore não instalado: estas configurações só terão efeito depois que ele for instalado.", ru_RU = "Прокси GameCore не установлен: эти настройки вступят в силу только после его установки.", zh_Hans_CN = "GameCore 代理未安装：这些设置要在安装后才会生效。" },
	LOC_BGD_OPT_PAUSE_FIN_CHARGEMENT_AIDE = { en_US = "At the end of a load, the game prepares the 3D terrain a few tiles at a time and pauses between steps (LoadGameTickIntervalInMS, 16 ms by default). The pause is lifted during that last phase only (about 1.5 s per load). Takes effect at the next game launch.", fr_FR = "À la fin d'un chargement, le jeu prépare le terrain 3D quelques cases à la fois et fait une pause entre chaque étape (LoadGameTickIntervalInMS, 16 ms par défaut). La pause est levée pendant cette dernière phase seulement (environ 1,5 s par chargement). Prend effet au prochain lancement du jeu.", de_DE = "Am Ende eines Ladevorgangs bereitet das Spiel das 3D-Gelände wenige Felder auf einmal vor und pausiert zwischen den Schritten (LoadGameTickIntervalInMS, standardmäßig 16 ms). Die Pause wird nur in dieser letzten Phase aufgehoben (etwa 1,5 s pro Ladevorgang). Wirkt ab dem nächsten Spielstart.", es_ES = "Al final de una carga, el juego prepara el terreno 3D unas pocas casillas a la vez y hace una pausa entre cada paso (LoadGameTickIntervalInMS, 16 ms por defecto). La pausa se elimina solo durante esa última fase (unos 1,5 s por carga). Se aplica en el próximo inicio del juego.", it_IT = "Alla fine di un caricamento, il gioco prepara il terreno 3D poche caselle alla volta e fa una pausa tra un passo e l'altro (LoadGameTickIntervalInMS, 16 ms di default). La pausa viene tolta solo durante quest'ultima fase (circa 1,5 s per caricamento). Ha effetto al prossimo avvio del gioco.", ja_JP = "ロードの最後に、ゲームは3D地形を数タイルずつ準備し、各ステップの間で待機します（LoadGameTickIntervalInMS、既定値16ミリ秒）。この最後の段階の間だけ待機をなくします（ロード1回あたり約1.5秒）。次回のゲーム起動時に有効になります。", ko_KR = "로딩 마지막에 게임은 3D 지형을 몇 타일씩 준비하며 단계마다 대기합니다(LoadGameTickIntervalInMS, 기본값 16ms). 이 마지막 단계에서만 대기를 없앱니다(로딩당 약 1.5초). 다음 게임 실행 시 적용됩니다.", pl_PL = "Na końcu wczytywania gra przygotowuje teren 3D po kilka pól naraz i robi przerwę między krokami (LoadGameTickIntervalInMS, domyślnie 16 ms). Przerwa jest usuwana tylko w tej ostatniej fazie (około 1,5 s na wczytanie). Działa od następnego uruchomienia gry.", pt_BR = "No fim de um carregamento, o jogo prepara o terreno 3D poucos hexágonos por vez e faz uma pausa entre cada etapa (LoadGameTickIntervalInMS, 16 ms por padrão). A pausa é removida apenas nessa última fase (cerca de 1,5 s por carregamento). Entra em vigor no próximo início do jogo.", ru_RU = "В конце загрузки игра готовит 3D-ландшафт по нескольку клеток за раз и делает паузу между шагами (LoadGameTickIntervalInMS, по умолчанию 16 мс). Пауза снимается только на этом последнем этапе (около 1,5 с на загрузку). Вступает в силу при следующем запуске игры.", zh_Hans_CN = "加载末尾，游戏每次只准备几个单元格的 3D 地形，并在每步之间暂停（LoadGameTickIntervalInMS，默认 16 毫秒）。仅在这最后阶段取消暂停（每次加载约 1.5 秒）。下次启动游戏时生效。" },
	LOC_BGD_OPT_PAUSE_FIN_CHARGEMENT_NOM = { en_US = "No pause at the end of a load", fr_FR = "Pas de pause à la fin d'un chargement", de_DE = "Keine Pause am Ende eines Ladevorgangs", es_ES = "Sin pausa al final de una carga", it_IT = "Nessuna pausa alla fine di un caricamento", ja_JP = "ロードの最後に待機しない", ko_KR = "로딩 마지막 단계에서 대기 없음", pl_PL = "Bez przerw na końcu wczytywania", pt_BR = "Sem pausa no fim de um carregamento", ru_RU = "Без пауз в конце загрузки", zh_Hans_CN = "加载末尾不暂停" },
	LOC_BGD_OPT_POOL_ATTENTE_FIN_AIDE = { en_US = "The thread that waits for a batch of jobs to end spins on the processor until the last job thread leaves, about 1 s of processor per load. It sleeps instead after a short wait, and is woken when a job thread leaves. Takes effect at the next game launch.", fr_FR = "Le thread qui attend la fin d'un lot de tâches tourne sur le processeur jusqu'à ce que le dernier thread de tâches en sorte, environ 1 s de processeur par chargement. Il dort à la place après une courte attente, et il est réveillé quand un thread de tâches sort. Prend effet au prochain lancement du jeu.", de_DE = "Der Thread, der auf das Ende eines Job-Stapels wartet, kreist auf dem Prozessor, bis der letzte Job-Thread fertig ist, etwa 1 s Prozessorzeit pro Ladevorgang. Stattdessen schläft er nach kurzem Warten und wird geweckt, wenn ein Job-Thread fertig ist. Wirkt ab dem nächsten Spielstart.", es_ES = "El hilo que espera el final de un lote de tareas gira en el procesador hasta que el último hilo de tareas termina, cerca de 1 s de procesador por carga. En su lugar duerme tras una breve espera y se despierta cuando un hilo de tareas termina. Se aplica en el próximo inicio del juego.", it_IT = "Il thread che attende la fine di un gruppo di compiti gira sul processore finché l'ultimo thread di lavoro non esce, circa 1 s di processore per caricamento. Al suo posto dorme dopo una breve attesa e viene svegliato quando un thread di lavoro esce. Ha effetto al prossimo avvio del gioco.", ja_JP = "ジョブのまとまりの完了を待つスレッドは、最後のジョブスレッドが抜けるまでプロセッサ上で回り続け、ロード1回あたり約1秒のプロセッサ時間を使います。代わりに短い待機の後スリープし、ジョブスレッドが抜けると起こされます。次回のゲーム起動時に有効になります。", ko_KR = "작업 묶음이 끝나기를 기다리는 스레드는 마지막 작업 스레드가 빠질 때까지 프로세서에서 계속 돌며, 로딩당 약 1초의 프로세서 시간을 씁니다. 대신 짧게 기다린 뒤 잠들고, 작업 스레드가 빠지면 깨어납니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Wątek czekający na koniec partii zadań kręci się na procesorze, aż ostatni wątek zadań skończy, około 1 s procesora na wczytanie. Zamiast tego po krótkim czekaniu zasypia i jest budzony, gdy wątek zadań kończy. Działa od następnego uruchomienia gry.", pt_BR = "A thread que espera o fim de um lote de tarefas gira no processador até a última thread de tarefas sair, cerca de 1 s de processador por carregamento. Em vez disso, ela dorme após uma espera curta e é acordada quando uma thread de tarefas sai. Entra em vigor no próximo início do jogo.", ru_RU = "Поток, ожидающий конца пакета задач, крутится на процессоре, пока последний поток задач не выйдет, около 1 с процессора на загрузку. Вместо этого после короткого ожидания он засыпает и просыпается, когда поток задач выходит. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "等待一批任务结束的线程会在处理器上空转，直到最后一个任务线程退出，每次加载约耗费 1 秒处理器时间。改为短暂等待后休眠，并在任务线程退出时被唤醒。下次启动游戏时生效。" },
	LOC_BGD_OPT_POOL_ATTENTE_FIN_NOM = { en_US = "Sleep while waiting for the job threads", fr_FR = "Dormir en attendant les threads de tâches", de_DE = "Beim Warten auf Job-Threads schlafen", es_ES = "Dormir mientras se espera a los hilos de tareas", it_IT = "Dormire in attesa dei thread di lavoro", ja_JP = "ジョブスレッドの完了待ちでスリープ", ko_KR = "작업 스레드를 기다리는 동안 대기", pl_PL = "Uśpienie podczas czekania na wątki zadań", pt_BR = "Dormir enquanto espera as threads de tarefas", ru_RU = "Сон при ожидании потоков задач", zh_Hans_CN = "等待任务线程时休眠" },
	LOC_BGD_OPT_POOL_CESSIONS_AIDE = { en_US = "A job thread without work yields its processor 100 times before going to sleep, hundreds of times per second during the end of turn. Fewer yields: less processor time wasted waiting, the same work done. Disabled = 100, as in the game. Takes effect at the next game launch.", fr_FR = "Un thread de tâches sans travail cède son processeur 100 fois avant de s'endormir, des centaines de fois par seconde pendant le passage de tour. Moins de cessions : moins de processeur perdu à attendre, le même travail fait. Désactivé = 100, comme le jeu. Prend effet au prochain lancement du jeu.", de_DE = "Ein Job-Thread ohne Arbeit gibt seinen Prozessor 100-mal ab, bevor er schläft, hunderte Male pro Sekunde während des Rundenwechsels. Weniger Abgaben: weniger Prozessorzeit mit Warten verschwendet, dieselbe Arbeit. Deaktiviert = 100, wie im Spiel. Wirkt ab dem nächsten Spielstart.", es_ES = "Un hilo de tareas sin trabajo cede su procesador 100 veces antes de dormirse, cientos de veces por segundo durante el paso de turno. Menos cesiones: menos procesador perdido esperando, el mismo trabajo hecho. Desactivado = 100, como el juego. Se aplica en el próximo inicio del juego.", it_IT = "Un thread di lavoro senza compiti cede il processore 100 volte prima di addormentarsi, centinaia di volte al secondo durante il passaggio di turno. Meno cessioni: meno processore sprecato in attesa, lo stesso lavoro svolto. Disattivato = 100, come il gioco. Ha effetto al prossimo avvio del gioco.", ja_JP = "仕事のないジョブスレッドは、スリープする前にプロセッサを100回譲ります。ターン終了処理中は毎秒数百回起こります。回数を減らすと、待機で無駄になるプロセッサ時間が減り、処理内容は同じです。無効 = ゲームと同じ100。次回のゲーム起動時に有効になります。", ko_KR = "할 일이 없는 작업 스레드는 잠들기 전에 프로세서를 100번 양보하며, 턴 넘김 중에는 초당 수백 번 반복됩니다. 양보를 줄이면 대기로 낭비되는 프로세서 시간이 줄고 처리하는 일은 같습니다. 끔 = 게임과 같은 100. 다음 게임 실행 시 적용됩니다.", pl_PL = "Wątek zadań bez pracy oddaje procesor 100 razy, zanim zaśnie, setki razy na sekundę podczas zmiany tury. Mniej oddań: mniej czasu procesora traconego na czekanie, ta sama praca. Wyłączone = 100, jak w grze. Działa od następnego uruchomienia gry.", pt_BR = "Uma thread de tarefas sem trabalho cede o processador 100 vezes antes de dormir, centenas de vezes por segundo durante a passagem de turno. Menos cessões: menos processador desperdiçado esperando, o mesmo trabalho feito. Desativado = 100, como no jogo. Entra em vigor no próximo início do jogo.", ru_RU = "Поток задач без работы уступает процессор 100 раз, прежде чем уснуть, и это происходит сотни раз в секунду во время смены хода. Меньше уступок: меньше процессорного времени уходит на ожидание, работа та же. Выключено = 100, как в игре. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "没有任务的任务线程在休眠前会让出处理器 100 次，回合结算时每秒发生数百次。减少让出次数：等待浪费的处理器时间更少，完成的工作不变。关闭 = 100，与游戏相同。下次启动游戏时生效。" },
	LOC_BGD_OPT_POOL_CESSIONS_NOM = { en_US = "Idle job threads: yields before sleeping", fr_FR = "Threads de tâches inactifs : cessions avant le sommeil", de_DE = "Untätige Job-Threads: Abgaben vor dem Schlafen", es_ES = "Hilos de tareas inactivos: cesiones antes de dormir", it_IT = "Thread di lavoro inattivi: cessioni prima del sonno", ja_JP = "待機中のジョブスレッド：スリープ前の譲渡回数", ko_KR = "유휴 작업 스레드: 대기 전 양보 횟수", pl_PL = "Bezczynne wątki zadań: oddania przed uśpieniem", pt_BR = "Threads de tarefas ociosas: cessões antes de dormir", ru_RU = "Простаивающие потоки задач: уступки перед сном", zh_Hans_CN = "空闲任务线程：休眠前的让出次数" },
	LOC_BGD_OPT_POOL_PAUSES_AIDE = { en_US = "A job thread without work retries 2 × (threads + 1) times, spinning in place, before yielding its processor. A smaller fixed value shortens this busy wait, especially with many threads. Disabled = as in the game. Takes effect at the next game launch.", fr_FR = "Un thread de tâches sans travail réessaie 2 × (threads + 1) fois en patientant sur place avant de céder son processeur. Une valeur fixe et plus petite raccourcit cette attente active, surtout avec beaucoup de threads. Désactivé = comme le jeu. Prend effet au prochain lancement du jeu.", de_DE = "Ein Job-Thread ohne Arbeit versucht es 2 × (Threads + 1) Mal und wartet dabei aktiv, bevor er seinen Prozessor abgibt. Ein kleinerer fester Wert verkürzt dieses aktive Warten, besonders bei vielen Threads. Deaktiviert = wie im Spiel. Wirkt ab dem nächsten Spielstart.", es_ES = "Un hilo de tareas sin trabajo reintenta 2 × (hilos + 1) veces, esperando activamente, antes de ceder su procesador. Un valor fijo más pequeño acorta esta espera activa, sobre todo con muchos hilos. Desactivado = como el juego. Se aplica en el próximo inicio del juego.", it_IT = "Un thread di lavoro senza compiti riprova 2 × (thread + 1) volte, in attesa attiva, prima di cedere il processore. Un valore fisso più piccolo accorcia questa attesa attiva, soprattutto con molti thread. Disattivato = come il gioco. Ha effetto al prossimo avvio del gioco.", ja_JP = "仕事のないジョブスレッドは、プロセッサを譲る前にその場で待ちながら 2 × (スレッド数 + 1) 回再試行します。小さい固定値にすると、特にスレッドが多いときにこのビジーウェイトが短くなります。無効 = ゲームと同じ。次回のゲーム起動時に有効になります。", ko_KR = "할 일이 없는 작업 스레드는 프로세서를 양보하기 전에 제자리에서 기다리며 2 × (스레드 수 + 1)번 다시 시도합니다. 더 작은 고정값을 쓰면 특히 스레드가 많을 때 이 바쁜 대기가 짧아집니다. 끔 = 게임과 같음. 다음 게임 실행 시 적용됩니다.", pl_PL = "Wątek zadań bez pracy ponawia próbę 2 × (wątki + 1) razy, czekając aktywnie, zanim odda procesor. Mniejsza stała wartość skraca to aktywne czekanie, zwłaszcza przy wielu wątkach. Wyłączone = jak w grze. Działa od następnego uruchomienia gry.", pt_BR = "Uma thread de tarefas sem trabalho tenta de novo 2 × (threads + 1) vezes, em espera ativa, antes de ceder o processador. Um valor fixo menor encurta essa espera ativa, principalmente com muitas threads. Desativado = como no jogo. Entra em vigor no próximo início do jogo.", ru_RU = "Поток задач без работы повторяет попытку 2 × (потоки + 1) раз, ожидая на месте, прежде чем уступить процессор. Меньшее фиксированное значение сокращает это активное ожидание, особенно при большом числе потоков. Выключено = как в игре. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "没有任务的任务线程在让出处理器之前，会原地等待并重试 2 × (线程数 + 1) 次。较小的固定值可缩短这种忙等待，线程多时尤其明显。关闭 = 与游戏相同。下次启动游戏时生效。" },
	LOC_BGD_OPT_POOL_PAUSES_NOM = { en_US = "Idle job threads: tries before the first yield", fr_FR = "Threads de tâches inactifs : tentatives avant la première cession", de_DE = "Untätige Job-Threads: Versuche vor der ersten Abgabe", es_ES = "Hilos de tareas inactivos: intentos antes de la primera cesión", it_IT = "Thread di lavoro inattivi: tentativi prima della prima cessione", ja_JP = "待機中のジョブスレッド：最初の譲渡までの試行回数", ko_KR = "유휴 작업 스레드: 첫 양보 전 시도 횟수", pl_PL = "Bezczynne wątki zadań: próby przed pierwszym oddaniem", pt_BR = "Threads de tarefas ociosas: tentativas antes da primeira cessão", ru_RU = "Простаивающие потоки задач: попытки до первой уступки", zh_Hans_CN = "空闲任务线程：首次让出前的尝试次数" },
	LOC_BGD_OPT_PORTEE_AIDE = { en_US = "\"Every game message\" also batches refreshes outside of wars (governors, resources, deals). The interface may then show city data a moment late.", fr_FR = "« Chaque message du jeu » regroupe aussi les rafraîchissements hors guerre (gouverneurs, ressources, accords). L'interface peut alors montrer une donnée de ville en retard d'un instant.", de_DE = "„Jede Spielnachricht“ bündelt auch Aktualisierungen außerhalb von Kriegen (Gouverneure, Ressourcen, Abkommen). Die Oberfläche kann Stadtdaten dann einen Moment verzögert anzeigen.", es_ES = "«Cada mensaje del juego» agrupa también las actualizaciones fuera de las guerras (gobernadores, recursos, acuerdos). La interfaz puede mostrar entonces un dato de ciudad con un instante de retraso.", it_IT = "\"Ogni messaggio del gioco\" raggruppa anche gli aggiornamenti fuori dalle guerre (governatori, risorse, accordi). L'interfaccia può allora mostrare un dato di città con un attimo di ritardo.", ja_JP = "「ゲームのすべてのメッセージ」を選ぶと、戦争以外の更新 (総督、資源、取引) もまとめます。その場合、インターフェースの都市データが一瞬遅れて表示されることがあります。", ko_KR = "\"게임의 모든 메시지\"는 전쟁 외의 갱신(총독, 자원, 거래)도 묶습니다. 이 경우 인터페이스의 도시 정보가 잠시 늦게 표시될 수 있습니다.", pl_PL = "„Każdy komunikat gry” grupuje także odświeżenia poza wojnami (gubernatorzy, zasoby, umowy). Interfejs może wtedy pokazać dane miasta z chwilowym opóźnieniem.", pt_BR = "\"Cada mensagem do jogo\" agrupa também as atualizações fora das guerras (governadores, recursos, acordos). A interface pode então mostrar um dado de cidade com um instante de atraso.", ru_RU = "«Каждое сообщение игры» объединяет и обновления вне войн (губернаторы, ресурсы, сделки). Тогда интерфейс может показывать данные города с небольшой задержкой.", zh_Hans_CN = "“每条游戏消息”也会合并战争以外的刷新（总督、资源、交易）。此时界面显示的城市数据可能会稍有延迟。" },
	LOC_BGD_OPT_PORTEE_NOM = { en_US = "Batching scope", fr_FR = "Portée du regroupement", de_DE = "Umfang der Bündelung", es_ES = "Alcance de la agrupación", it_IT = "Portata del raggruppamento", ja_JP = "まとめる範囲", ko_KR = "묶는 범위", pl_PL = "Zakres grupowania", pt_BR = "Alcance do agrupamento", ru_RU = "Охват объединения", zh_Hans_CN = "合并范围" },
	LOC_BGD_OPT_PROFIL_ZONES_AIDE = { en_US = "Records the duration of every zone the game times (frame, interface, scripts, events) to %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, for performance analysis. About 1 MB per second of play. Takes effect the next time the game starts.", fr_FR = "Note la durée de chaque zone chronométrée par le jeu (image, interface, scripts, événements) dans %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, pour l'analyse des performances. Environ 1 Mo par seconde de jeu. Prend effet au prochain lancement du jeu.", de_DE = "Zeichnet die Dauer jeder vom Spiel gemessenen Zone (Bild, Oberfläche, Skripte, Ereignisse) in %LOCALAPPDATA%\\Civ6RolloverProxy\\zones auf, für die Leistungsanalyse. Etwa 1 MB pro Sekunde Spielzeit. Wirkt beim nächsten Spielstart.", es_ES = "Registra la duración de cada zona que cronometra el juego (imagen, interfaz, scripts, eventos) en %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, para el análisis de rendimiento. Unos 1 MB por segundo de juego. Surte efecto la próxima vez que se inicie el juego.", it_IT = "Registra la durata di ogni zona cronometrata dal gioco (immagine, interfaccia, script, eventi) in %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, per l'analisi delle prestazioni. Circa 1 MB per secondo di gioco. Ha effetto al prossimo avvio del gioco.", ja_JP = "ゲームが計測する各区間 (フレーム、インターフェース、スクリプト、イベント) の所要時間を、パフォーマンス分析のため %LOCALAPPDATA%\\Civ6RolloverProxy\\zones に記録します。プレイ1秒あたり約1MB。次回のゲーム起動時から有効です。", ko_KR = "게임이 측정하는 각 구간(프레임, 인터페이스, 스크립트, 이벤트)의 시간을 성능 분석을 위해 %LOCALAPPDATA%\\Civ6RolloverProxy\\zones에 기록합니다. 플레이 1초당 약 1MB입니다. 다음에 게임을 시작할 때부터 적용됩니다.", pl_PL = "Zapisuje czas trwania każdej strefy mierzonej przez grę (klatka, interfejs, skrypty, zdarzenia) w %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, do analizy wydajności. Około 1 MB na sekundę gry. Działa od następnego uruchomienia gry.", pt_BR = "Registra a duração de cada zona cronometrada pelo jogo (quadro, interface, scripts, eventos) em %LOCALAPPDATA%\\Civ6RolloverProxy\\zones, para a análise de desempenho. Cerca de 1 MB por segundo de jogo. Vale a partir da próxima vez que o jogo for iniciado.", ru_RU = "Записывает длительность каждой зоны, которую замеряет игра (кадр, интерфейс, скрипты, события), в %LOCALAPPDATA%\\Civ6RolloverProxy\\zones для анализа производительности. Около 1 МБ на секунду игры. Действует со следующего запуска игры.", zh_Hans_CN = "将游戏计时的每个区段（帧、界面、脚本、事件）的耗时记录到 %LOCALAPPDATA%\\Civ6RolloverProxy\\zones，用于性能分析。每秒游戏约 1 MB。下次启动游戏时生效。" },
	LOC_BGD_OPT_PROFIL_ZONES_NOM = { en_US = "Profile the game's timed zones", fr_FR = "Profil des zones de l'exe", de_DE = "Zeitzonen des Spiels aufzeichnen", es_ES = "Perfil de las zonas cronometradas del juego", it_IT = "Profilo delle zone cronometrate del gioco", ja_JP = "ゲームの計測区間のプロファイル", ko_KR = "게임 측정 구간 프로필", pl_PL = "Profil mierzonych stref gry", pt_BR = "Perfil das zonas cronometradas do jogo", ru_RU = "Профиль замеряемых зон игры", zh_Hans_CN = "游戏计时区段分析" },
	LOC_BGD_OPT_REINIT_AIDE = { en_US = "Restores every BetterGameExperience setting to its default value.", fr_FR = "Remet tous les réglages de BetterGameExperience à leur valeur par défaut.", de_DE = "Setzt alle Einstellungen von BetterGameExperience auf ihren Standardwert zurück.", es_ES = "Devuelve todos los ajustes de BetterGameExperience a su valor predeterminado.", it_IT = "Riporta tutte le impostazioni di BetterGameExperience al loro valore predefinito.", ja_JP = "BetterGameExperience のすべての設定を既定値に戻します。", ko_KR = "BetterGameExperience의 모든 설정을 기본값으로 되돌립니다.", pl_PL = "Przywraca wszystkie ustawienia BetterGameExperience do wartości domyślnych.", pt_BR = "Restaura todos os ajustes do BetterGameExperience para o valor padrão.", ru_RU = "Возвращает все настройки BetterGameExperience к значениям по умолчанию.", zh_Hans_CN = "将 BetterGameExperience 的所有设置恢复为默认值。" },
	LOC_BGD_OPT_REINIT_BOUTON = { en_US = "Reset BGE", fr_FR = "Réinitialiser BGE", de_DE = "BGE zurücksetzen", es_ES = "Restablecer BGE", it_IT = "Ripristina BGE", ja_JP = "BGE をリセット", ko_KR = "BGE 초기화", pl_PL = "Zresetuj BGE", pt_BR = "Redefinir BGE", ru_RU = "Сбросить BGE", zh_Hans_CN = "重置 BGE" },
	LOC_BGD_OPT_REINIT_FAIT = { en_US = "Settings reset to their default values.", fr_FR = "Réglages réinitialisés à leur valeur par défaut.", de_DE = "Einstellungen auf ihre Standardwerte zurückgesetzt.", es_ES = "Ajustes restablecidos a sus valores predeterminados.", it_IT = "Impostazioni ripristinate ai valori predefiniti.", ja_JP = "設定を既定値に戻しました。", ko_KR = "설정을 기본값으로 되돌렸습니다.", pl_PL = "Ustawienia przywrócone do wartości domyślnych.", pt_BR = "Ajustes restaurados para os valores padrão.", ru_RU = "Настройки возвращены к значениям по умолчанию.", zh_Hans_CN = "设置已恢复为默认值。" },
	LOC_BGD_OPT_REINIT_TEXTE = { en_US = "Reset all BetterGameExperience settings to their default values?", fr_FR = "Réinitialiser tous les réglages de BetterGameExperience à leur valeur par défaut ?", de_DE = "Alle Einstellungen von BetterGameExperience auf ihre Standardwerte zurücksetzen?", es_ES = "¿Restablecer todos los ajustes de BetterGameExperience a sus valores predeterminados?", it_IT = "Ripristinare tutte le impostazioni di BetterGameExperience ai valori predefiniti?", ja_JP = "BetterGameExperience のすべての設定を既定値に戻しますか?", ko_KR = "BetterGameExperience의 모든 설정을 기본값으로 되돌리시겠습니까?", pl_PL = "Przywrócić wszystkie ustawienia BetterGameExperience do wartości domyślnych?", pt_BR = "Restaurar todos os ajustes do BetterGameExperience para os valores padrão?", ru_RU = "Вернуть все настройки BetterGameExperience к значениям по умолчанию?", zh_Hans_CN = "要将 BetterGameExperience 的所有设置恢复为默认值吗？" },
	LOC_BGD_OPT_RELECTURE_FIDELE_AIDE = { en_US = "When the host resends data that went out of sync, the game reads it back exactly as the host wrote it: unit operations and the boosts the AI tracks are no longer doubled, World Congress analyses keep their values, AI behavior trees stay linked, and data that already matches the host's is left untouched (fewer desyncs that end in a full reload). Works even if other players don't have this version.", fr_FR = "Quand l'hôte renvoie des données désynchronisées, le jeu les relit exactement comme l'hôte les a écrites : les opérations des unités et les boosts suivis par l'IA ne sont plus doublés, les analyses du Congrès mondial gardent leurs valeurs, les arbres de comportement de l'IA restent liés et les données déjà identiques à celles de l'hôte ne sont pas touchées (moins de désynchronisations qui finissent en rechargement complet). Fonctionne même si les autres joueurs n'ont pas cette version.", de_DE = "Wenn der Host nicht synchrone Daten erneut sendet, liest das Spiel sie genau so, wie der Host sie geschrieben hat: Einheitenoperationen und von der KI verfolgte Boosts werden nicht mehr verdoppelt, Analysen des Weltkongresses behalten ihre Werte, die Verhaltensbäume der KI bleiben verknüpft und Daten, die bereits denen des Hosts entsprechen, bleiben unverändert (weniger Desynchronisationen, die mit einem vollständigen Neuladen enden). Funktioniert auch, wenn andere Spieler diese Version nicht haben.", es_ES = "Cuando el anfitrión reenvía datos desincronizados, el juego los vuelve a leer exactamente como el anfitrión los escribió: las operaciones de unidades y los impulsos que sigue la IA ya no se duplican, los análisis del Congreso Mundial conservan sus valores, los árboles de comportamiento de la IA siguen enlazados y los datos que ya coinciden con los del anfitrión no se tocan (menos desincronizaciones que acaban en una recarga completa). Funciona aunque los demás jugadores no tengan esta versión.", it_IT = "Quando l'host reinvia dati desincronizzati, il gioco li rilegge esattamente come l'host li ha scritti: le operazioni delle unità e i potenziamenti seguiti dall'IA non vengono più raddoppiati, le analisi del Congresso Mondiale conservano i loro valori, gli alberi di comportamento dell'IA restano collegati e i dati già uguali a quelli dell'host restano intatti (meno desincronizzazioni che finiscono con un ricaricamento completo). Funziona anche se gli altri giocatori non hanno questa versione.", ja_JP = "ホストが同期ずれしたデータを再送したとき、ゲームはホストが書いたとおりに正確に読み直します。ユニットの作戦やAIが追跡するブーストが二重にならず、世界会議の分析は値を保ち、AIの行動ツリーはリンクされたままで、すでにホストと同じデータには手を加えません（完全な再読み込みに至る同期ずれが減ります）。他のプレイヤーがこのバージョンでなくても機能します。", ko_KR = "호스트가 동기화가 어긋난 데이터를 다시 보내면, 게임은 호스트가 기록한 그대로 다시 읽습니다. 유닛 작전과 AI가 추적하는 부스트가 더 이상 두 배가 되지 않고, 세계 의회 분석은 값을 유지하며, AI 행동 트리는 연결된 상태로 남고, 이미 호스트와 같은 데이터는 건드리지 않습니다(전체 다시 불러오기로 끝나는 동기화 오류 감소). 다른 플레이어가 이 버전이 아니어도 작동합니다.", pl_PL = "Gdy host ponownie wysyła zdesynchronizowane dane, gra wczytuje je dokładnie tak, jak zapisał je host: operacje jednostek i bonusy śledzone przez SI nie są już podwajane, analizy Kongresu Światowego zachowują swoje wartości, drzewa zachowań SI pozostają połączone, a dane zgodne już z danymi hosta pozostają nietknięte (mniej desynchronizacji kończących się pełnym ponownym wczytaniem). Działa nawet wtedy, gdy inni gracze nie mają tej wersji.", pt_BR = "Quando o anfitrião reenvia dados dessincronizados, o jogo os relê exatamente como o anfitrião os escreveu: as operações das unidades e os impulsos acompanhados pela IA não são mais duplicados, as análises do Congresso Mundial mantêm seus valores, as árvores de comportamento da IA continuam vinculadas e os dados que já coincidem com os do anfitrião não são alterados (menos dessincronizações que terminam em um recarregamento completo). Funciona mesmo que os outros jogadores não tenham esta versão.", ru_RU = "Когда хост повторно отправляет рассинхронизированные данные, игра читает их точно так, как их записал хост: операции отрядов и отслеживаемые ИИ озарения больше не удваиваются, анализы Всемирного конгресса сохраняют свои значения, деревья поведения ИИ остаются связанными, а данные, уже совпадающие с данными хоста, не затрагиваются (меньше рассинхронизаций, заканчивающихся полной перезагрузкой). Работает, даже если у других игроков нет этой версии.", zh_Hans_CN = "当主机重新发送不同步的数据时，游戏会完全按照主机写入的内容重新读取：单位行动和 AI 追踪的加速不再重复，世界议会分析保留其数值，AI 行为树保持链接，已与主机一致的数据保持不变（减少以完全重新载入告终的不同步）。即使其他玩家没有此版本也有效。" },
	LOC_BGD_OPT_RELECTURE_FIDELE_NOM = { en_US = "Repaired data read back exactly", fr_FR = "Données réparées relues à l'identique", de_DE = "Reparierte Daten exakt zurücklesen", es_ES = "Datos reparados releídos tal cual", it_IT = "Dati riparati riletti fedelmente", ja_JP = "修復データを正確に再読み込み", ko_KR = "복구된 데이터를 그대로 다시 읽기", pl_PL = "Naprawione dane wczytywane dokładnie", pt_BR = "Dados reparados relidos com exatidão", ru_RU = "Точное повторное чтение исправленных данных", zh_Hans_CN = "按原样重读修复的数据" },
	LOC_BGD_OPT_REMAP_LEGER_AIDE = { en_US = "At a Multiplayer Helper remap, the host loads the new game, then reloads it at once from its own save. The first load skips the 3D terrain, which would be thrown away (about 10 s). The game, the interface and the clients are unchanged. Takes effect at the next game launch.", fr_FR = "Au remap de Multiplayer Helper, l'hôte charge la nouvelle partie, puis la recharge aussitôt depuis sa propre sauvegarde. Le premier chargement saute le terrain 3D, qui serait jeté (environ 10 s). La partie, l'interface et les clients ne changent pas. Prend effet au prochain lancement du jeu.", de_DE = "Beim Remap von Multiplayer Helper lädt der Host die neue Partie und lädt sie sofort aus seinem eigenen Spielstand neu. Der erste Ladevorgang überspringt das 3D-Gelände, das verworfen würde (etwa 10 s). Partie, Oberfläche und Clients bleiben unverändert. Wirkt ab dem nächsten Spielstart.", es_ES = "En el remap de Multiplayer Helper, el anfitrión carga la nueva partida y la vuelve a cargar enseguida desde su propio guardado. La primera carga omite el terreno 3D, que se descartaría (unos 10 s). La partida, la interfaz y los clientes no cambian. Se aplica en el próximo inicio del juego.", it_IT = "Al remap di Multiplayer Helper, l'host carica la nuova partita e poi la ricarica subito dal proprio salvataggio. Il primo caricamento salta il terreno 3D, che verrebbe scartato (circa 10 s). Partita, interfaccia e client non cambiano. Ha effetto al prossimo avvio del gioco.", ja_JP = "Multiplayer Helperのリマップでは、ホストが新しいゲームをロードし、すぐに自分のセーブから再ロードします。最初のロードでは、破棄されるだけの3D地形の作成を省きます（約10秒）。ゲーム、UI、クライアントは変わりません。次回のゲーム起動時に有効になります。", ko_KR = "Multiplayer Helper 리맵에서 호스트는 새 게임을 로드한 뒤 곧바로 자신의 저장에서 다시 로드합니다. 첫 로딩은 버려질 3D 지형을 건너뜁니다(약 10초). 게임, 인터페이스, 클라이언트는 그대로입니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Przy remapie Multiplayer Helper host wczytuje nową grę, a potem od razu wczytuje ją ponownie z własnego zapisu. Pierwsze wczytanie pomija teren 3D, który i tak zostałby odrzucony (około 10 s). Gra, interfejs i klienci się nie zmieniają. Działa od następnego uruchomienia gry.", pt_BR = "No remap do Multiplayer Helper, o anfitrião carrega a nova partida e logo a recarrega do próprio salvamento. O primeiro carregamento pula o terreno 3D, que seria descartado (cerca de 10 s). A partida, a interface e os clientes não mudam. Entra em vigor no próximo início do jogo.", ru_RU = "При ремапе Multiplayer Helper хост загружает новую партию, а затем сразу перезагружает её из своего сохранения. Первая загрузка пропускает 3D-ландшафт, который всё равно был бы выброшен (около 10 с). Партия, интерфейс и клиенты не меняются. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "使用 Multiplayer Helper 重新生成地图时，主机先加载新游戏，随后立即从自己的存档重新加载。首次加载跳过本会被丢弃的 3D 地形（约 10 秒）。游戏、界面和客户端均不变。下次启动游戏时生效。" },
	LOC_BGD_OPT_REMAP_LEGER_NOM = { en_US = "Host's first remap load without terrain", fr_FR = "Premier chargement du remap de l'hôte sans terrain", de_DE = "Erster Remap-Ladevorgang des Hosts ohne Gelände", es_ES = "Primera carga del remap del anfitrión sin terreno", it_IT = "Primo caricamento del remap dell'host senza terreno", ja_JP = "リマップ時のホストの初回ロードで地形を省略", ko_KR = "리맵 시 호스트의 첫 로딩에서 지형 생략", pl_PL = "Pierwsze wczytanie remapu hosta bez terenu", pt_BR = "Primeiro carregamento do remap do anfitrião sem terreno", ru_RU = "Первая загрузка ремапа у хоста без ландшафта", zh_Hans_CN = "重新生成地图时主机首次加载跳过地形" },
	LOC_BGD_OPT_RENDEMENTS_AIDE = { en_US = "Remembers tile yields during the AI's parallel computations, while the map cannot change.", fr_FR = "Mémorise le rendement des cases pendant les calculs parallèles de l'IA, où la carte ne peut pas changer.", de_DE = "Merkt sich die Erträge der Felder während der parallelen Berechnungen der KI, in denen sich die Karte nicht ändern kann.", es_ES = "Memoriza el rendimiento de las casillas durante los cálculos paralelos de la IA, mientras el mapa no puede cambiar.", it_IT = "Memorizza la resa delle caselle durante i calcoli paralleli dell'IA, mentre la mappa non può cambiare.", ja_JP = "マップが変化しない AI の並列計算の間、タイルの産出量を記憶します。", ko_KR = "지도가 바뀔 수 없는 AI의 병렬 계산 동안 타일 산출량을 기억합니다.", pl_PL = "Zapamiętuje plony pól podczas równoległych obliczeń SI, gdy mapa nie może się zmienić.", pt_BR = "Memoriza o rendimento dos hexágonos durante os cálculos paralelos da IA, enquanto o mapa não pode mudar.", ru_RU = "Запоминает доход клеток во время параллельных расчётов ИИ, пока карта не может измениться.", zh_Hans_CN = "在 AI 并行计算期间（地图不会变化）记住单元格的产出。" },
	LOC_BGD_OPT_RENDEMENTS_NOM = { en_US = "Tile yield memory for the AI", fr_FR = "Mémoire des rendements de cases pour l'IA", de_DE = "Gespeicherte Feld-Erträge für die KI", es_ES = "Memoria de rendimientos de casillas para la IA", it_IT = "Memoria delle rese delle caselle per l'IA", ja_JP = "AI 用のタイル産出量の記憶", ko_KR = "AI용 타일 산출량 기억", pl_PL = "Zapamiętywanie plonów pól dla SI", pt_BR = "Memória dos rendimentos dos hexágonos para a IA", ru_RU = "Запоминание доходов клеток для ИИ", zh_Hans_CN = "为 AI 记忆单元格产出" },
	LOC_BGD_OPT_SANS_NATIVES = { en_US = "Startup proxy functions missing: settings can be neither read nor saved.", fr_FR = "Fonctions du proxy de démarrage absentes : les réglages ne peuvent être ni lus ni enregistrés.", de_DE = "Funktionen des Start-Proxys fehlen: Die Einstellungen können weder gelesen noch gespeichert werden.", es_ES = "Faltan las funciones del proxy de inicio: los ajustes no se pueden leer ni guardar.", it_IT = "Funzioni del proxy di avvio mancanti: le impostazioni non possono essere né lette né salvate.", ja_JP = "起動プロキシの機能が見つかりません。設定を読み込むことも保存することもできません。", ko_KR = "시작 프록시의 기능이 없습니다. 설정을 읽거나 저장할 수 없습니다.", pl_PL = "Brak funkcji proxy startowego: ustawień nie można ani odczytać, ani zapisać.", pt_BR = "Funções do proxy de inicialização ausentes: as configurações não podem ser lidas nem salvas.", ru_RU = "Нет функций прокси запуска: настройки нельзя ни прочитать, ни сохранить.", zh_Hans_CN = "缺少启动代理的功能：无法读取或保存设置。" },
	LOC_BGD_OPT_TEXTES_GARDES_AIDE = { en_US = "The in-game texts of the mods are recorded at the first load, then written back from memory at the next ones when the mods are the same, instead of being read again from their files (about 1.5 s per load). Takes effect at the next game launch.", fr_FR = "Les textes en jeu des mods sont relevés au premier chargement, puis réécrits depuis la mémoire aux suivants quand les mods sont les mêmes, au lieu d'être relus dans leurs fichiers (environ 1,5 s par chargement). Prend effet au prochain lancement du jeu.", de_DE = "Die Spieltexte der Mods werden beim ersten Laden erfasst und bei den nächsten Ladevorgängen mit denselben Mods aus dem Speicher zurückgeschrieben, statt erneut aus ihren Dateien gelesen zu werden (etwa 1,5 s pro Ladevorgang). Wirkt ab dem nächsten Spielstart.", es_ES = "Los textos de juego de los mods se registran en la primera carga y luego se reescriben desde la memoria en las siguientes cuando los mods son los mismos, en lugar de volver a leerse de sus archivos (unos 1,5 s por carga). Se aplica en el próximo inicio del juego.", it_IT = "I testi di gioco dei mod vengono registrati al primo caricamento, poi riscritti dalla memoria in quelli successivi quando i mod sono gli stessi, invece di essere riletti dai loro file (circa 1,5 s per caricamento). Ha effetto al prossimo avvio del gioco.", ja_JP = "MODのゲーム内テキストを最初の読み込みで記録し、MODが同じなら以降の読み込みではファイルから読み直さずにメモリから書き戻します（読み込みごとに約1.5秒）。次回のゲーム起動時に有効になります。", ko_KR = "모드의 게임 내 텍스트를 처음 불러올 때 기록하고, 모드가 같으면 이후 불러오기에서는 파일에서 다시 읽지 않고 메모리에서 다시 씁니다(불러오기마다 약 1.5초). 다음 게임 실행 시 적용됩니다.", pl_PL = "Teksty modów w grze są zapisywane przy pierwszym wczytaniu, a przy kolejnych, gdy mody są te same, odtwarzane z pamięci zamiast ponownego odczytu z ich plików (około 1,5 s na wczytanie). Działa od następnego uruchomienia gry.", pt_BR = "Os textos de jogo dos mods são registrados no primeiro carregamento e depois reescritos a partir da memória nos seguintes quando os mods são os mesmos, em vez de serem lidos novamente de seus arquivos (cerca de 1,5 s por carregamento). Entra em vigor no próximo início do jogo.", ru_RU = "Внутриигровые тексты модов записываются при первой загрузке, а при следующих, если моды те же, восстанавливаются из памяти вместо повторного чтения из файлов (около 1,5 с на загрузку). Вступает в силу при следующем запуске игры.", zh_Hans_CN = "首次加载时记录模组的游戏内文本，之后模组相同时直接从内存写回，而不是重新从文件读取（每次加载约 1.5 秒）。下次启动游戏时生效。" },
	LOC_BGD_OPT_TEXTES_GARDES_NOM = { en_US = "Keep the mods' in-game texts between loads", fr_FR = "Garder les textes des mods d'un chargement à l'autre", de_DE = "Spieltexte der Mods zwischen Ladevorgängen behalten", es_ES = "Conservar los textos de juego de los mods entre cargas", it_IT = "Mantieni i testi di gioco dei mod tra un caricamento e l'altro", ja_JP = "MODのゲーム内テキストを読み込み間で保持", ko_KR = "불러오기 사이에 모드의 게임 내 텍스트 유지", pl_PL = "Zachowaj teksty modów w grze między wczytaniami", pt_BR = "Manter os textos de jogo dos mods entre carregamentos", ru_RU = "Сохранять внутриигровые тексты модов между загрузками", zh_Hans_CN = "在两次加载之间保留模组的游戏内文本" },
	LOC_BGD_OPT_TITRE_CORRECTIFS = { en_US = "Fixes", fr_FR = "Correctifs", de_DE = "Fehlerbehebungen", es_ES = "Correcciones", it_IT = "Correzioni", ja_JP = "修正", ko_KR = "수정 사항", pl_PL = "Poprawki", pt_BR = "Correções", ru_RU = "Исправления", zh_Hans_CN = "修正" },
	LOC_BGD_OPT_TITRE_CREDITS = { en_US = "Credits", fr_FR = "Crédits", de_DE = "Danksagungen", es_ES = "Créditos", it_IT = "Riconoscimenti", ja_JP = "クレジット", ko_KR = "제작진", pl_PL = "Podziękowania", pt_BR = "Créditos", ru_RU = "Благодарности", zh_Hans_CN = "致谢" },
	LOC_BGD_OPT_TITRE_DIAGNOSTIC = { en_US = "Diagnostics", fr_FR = "Diagnostic", de_DE = "Diagnose", es_ES = "Diagnóstico", it_IT = "Diagnostica", ja_JP = "診断", ko_KR = "진단", pl_PL = "Diagnostyka", pt_BR = "Diagnóstico", ru_RU = "Диагностика", zh_Hans_CN = "诊断" },
	LOC_BGD_OPT_TITRE_GENERAL = { en_US = "General", fr_FR = "Général", de_DE = "Allgemein", es_ES = "General", it_IT = "Generale", ja_JP = "全般", ko_KR = "일반", pl_PL = "Ogólne", pt_BR = "Geral", ru_RU = "Общие", zh_Hans_CN = "常规" },
	LOC_BGD_OPT_TITRE_INTERFACE = { en_US = "Interface", fr_FR = "Interface", de_DE = "Benutzeroberfläche", es_ES = "Interfaz", it_IT = "Interfaccia", ja_JP = "インターフェース", ko_KR = "인터페이스", pl_PL = "Interfejs", pt_BR = "Interface", ru_RU = "Интерфейс", zh_Hans_CN = "界面" },
	LOC_BGD_OPT_TITRE_MODS = { en_US = "Built-in interface mods", fr_FR = "Mods d'interface intégrés", de_DE = "Integrierte Oberflächen-Mods", es_ES = "Mods de interfaz integrados", it_IT = "Mod dell'interfaccia integrate", ja_JP = "組み込みインターフェースMOD", ko_KR = "내장 인터페이스 모드", pl_PL = "Wbudowane mody interfejsu", pt_BR = "Mods de interface integrados", ru_RU = "Встроенные моды интерфейса", zh_Hans_CN = "内置界面模组" },
	LOC_BGD_OPT_TITRE_PERFORMANCES = { en_US = "Turn processing performance", fr_FR = "Performances du passage de tour", de_DE = "Leistung der Rundenberechnung", es_ES = "Rendimiento del cambio de turno", it_IT = "Prestazioni del cambio di turno", ja_JP = "ターン処理のパフォーマンス", ko_KR = "턴 처리 성능", pl_PL = "Wydajność przetwarzania tury", pt_BR = "Desempenho da passagem de turno", ru_RU = "Скорость смены хода", zh_Hans_CN = "回合处理性能" },
	LOC_BGD_OPT_TOURS_PRODUCTION_AIDE = { en_US = "The displayed number of turns includes government bonuses (Fascism, Autocracy, Merchant Republic), like the actual production. Display only.", fr_FR = "Le nombre de tours affiché tient compte des bonus de gouvernement (fascisme, autocratie, république maritime), comme la production réelle. Affichage seulement.", de_DE = "Die angezeigte Rundenzahl berücksichtigt die Regierungsboni (Faschismus, Autokratie, Handelsrepublik), wie die tatsächliche Produktion. Nur Anzeige.", es_ES = "El número de turnos mostrado tiene en cuenta las bonificaciones de gobierno (fascismo, autocracia, república mercantil), como la producción real. Solo visualización.", it_IT = "Il numero di turni mostrato tiene conto dei bonus di governo (fascismo, autocrazia, repubblica mercantile), come la produzione reale. Solo visualizzazione.", ja_JP = "表示されるターン数に、実際の生産と同じく政府のボーナス (ファシズム、独裁政治、商業共和制) を反映します。表示のみ。", ko_KR = "표시되는 턴 수에 실제 생산처럼 정부 보너스(파시즘, 전제정치, 상인 공화제)를 반영합니다. 표시만 바뀝니다.", pl_PL = "Wyświetlana liczba tur uwzględnia premie ustroju (faszyzm, autokracja, republika kupiecka), tak jak rzeczywista produkcja. Tylko wyświetlanie.", pt_BR = "O número de turnos exibido leva em conta os bônus de governo (fascismo, autocracia, república mercante), como a produção real. Apenas exibição.", ru_RU = "Показанное число ходов учитывает бонусы формы правления (фашизм, автократия, торговая республика), как и реальное производство. Только отображение.", zh_Hans_CN = "显示的回合数会像实际生产一样计入政体加成（法西斯主义、独裁统治、商人共和国）。仅影响显示。" },
	LOC_BGD_OPT_TOURS_PRODUCTION_NOM = { en_US = "Fixed production turn counter", fr_FR = "Compteur de tours de production corrigé", de_DE = "Korrigierter Produktions-Rundenzähler", es_ES = "Contador de turnos de producción corregido", it_IT = "Contatore dei turni di produzione corretto", ja_JP = "生産ターン数の表示を修正", ko_KR = "생산 턴 수 표시 수정", pl_PL = "Poprawiony licznik tur produkcji", pt_BR = "Contador de turnos de produção corrigido", ru_RU = "Исправленный счётчик ходов производства", zh_Hans_CN = "修正生产回合数" },
	LOC_BGD_OPT_TRACE_STEAM_AIDE = { en_US = "Every 500 ms, writes the packets and bytes sent to and received from each player through Steam, the sends Steam refuses, and Steam's send queue (bytes, packets, relay or direct) to %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. To measure the network throughput between players. Takes effect at the next game launch.", fr_FR = "Toutes les 500 ms, écrit les paquets et octets envoyés à chaque joueur et reçus de lui par Steam, les envois que Steam refuse, et la file d'envoi de Steam (octets, paquets, relais ou direct) dans %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Pour mesurer le débit réseau entre joueurs. Prend effet au prochain lancement du jeu.", de_DE = "Schreibt alle 500 ms die über Steam an jeden Spieler gesendeten und von ihm empfangenen Pakete und Bytes, die von Steam abgelehnten Sendungen und die Sendewarteschlange von Steam (Bytes, Pakete, Relay oder direkt) in %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Zum Messen des Netzwerkdurchsatzes zwischen Spielern. Wirkt beim nächsten Spielstart.", es_ES = "Cada 500 ms, escribe los paquetes y bytes enviados a cada jugador y recibidos de él a través de Steam, los envíos que Steam rechaza y la cola de envío de Steam (bytes, paquetes, retransmisión o directo) en %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Para medir el caudal de red entre jugadores. Se aplica en el próximo inicio del juego.", it_IT = "Ogni 500 ms scrive i pacchetti e i byte inviati a ogni giocatore e ricevuti da lui tramite Steam, gli invii rifiutati da Steam e la coda di invio di Steam (byte, pacchetti, relay o diretto) in %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Per misurare il flusso di rete tra i giocatori. Ha effetto al prossimo avvio del gioco.", ja_JP = "500ミリ秒ごとに、Steam経由で各プレイヤーに送信・受信したパケットとバイト数、Steamが拒否した送信、Steamの送信キュー（バイト、パケット、リレーまたは直接）を%LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.logに書き込みます。プレイヤー間のネットワーク速度を測るためのものです。次回のゲーム起動時に有効になります。", ko_KR = "500ms마다 Steam을 통해 각 플레이어에게 보내고 받은 패킷과 바이트, Steam이 거부한 전송, Steam의 전송 대기열(바이트, 패킷, 릴레이 또는 직접)을 %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log에 기록합니다. 플레이어 간 네트워크 속도를 측정하기 위한 것입니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Co 500 ms zapisuje pakiety i bajty wysłane do każdego gracza i odebrane od niego przez Steam, wysyłki odrzucone przez Steam oraz kolejkę wysyłania Steam (bajty, pakiety, przekaźnik lub bezpośrednio) w %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Do pomiaru przepustowości sieci między graczami. Działa od następnego uruchomienia gry.", pt_BR = "A cada 500 ms, grava os pacotes e bytes enviados a cada jogador e recebidos dele pelo Steam, os envios que o Steam recusa e a fila de envio do Steam (bytes, pacotes, retransmissão ou direto) em %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Para medir a vazão de rede entre os jogadores. Entra em vigor na próxima vez que o jogo for iniciado.", ru_RU = "Каждые 500 мс записывает пакеты и байты, отправленные каждому игроку и полученные от него через Steam, отправки, отклонённые Steam, и очередь отправки Steam (байты, пакеты, ретранслятор или напрямую) в %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log. Для измерения скорости сети между игроками. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "每 500 毫秒将通过 Steam 发送给每位玩家和从其接收的数据包与字节、被 Steam 拒绝的发送，以及 Steam 的发送队列（字节、数据包、中继或直连）写入 %LOCALAPPDATA%\\Civ6RolloverProxy\\steam_debit-<pid>.log。用于测量玩家之间的网络速度。下次启动游戏时生效。" },
	LOC_BGD_OPT_TRACE_STEAM_NOM = { en_US = "Steam network trace", fr_FR = "Trace réseau Steam", de_DE = "Steam-Netzwerkprotokoll", es_ES = "Registro de red de Steam", it_IT = "Traccia di rete Steam", ja_JP = "Steamネットワークのトレース", ko_KR = "Steam 네트워크 추적", pl_PL = "Śledzenie sieci Steam", pt_BR = "Rastreamento de rede Steam", ru_RU = "Трассировка сети Steam", zh_Hans_CN = "Steam 网络追踪" },
	LOC_BGD_OPT_UI_ACCORD_QUANTITES_AIDE = { en_US = "In the deal screen, on an available resource, gold, gold per turn or Diplomatic Favor, Shift+click puts as much in the deal as the deal accepts, and Ctrl+click adds ten times a normal click: 10 of a resource, 1000 gold, 100 gold per turn, 10 Diplomatic Favor. Without this option, a larger amount has to be typed in the amount box. Local only: no effect on other players.", fr_FR = "Dans l'écran d'accord, sur une ressource, l'or, l'or par tour ou la faveur diplomatique disponibles, Maj+clic en met autant que l'accord en accepte, et Ctrl+clic ajoute dix fois un clic normal : 10 d'une ressource, 1000 d'or, 100 d'or par tour, 10 de faveur diplomatique. Sans cette option, une quantité plus grande doit être saisie dans la zone de quantité. Purement local : sans effet sur les autres joueurs.", de_DE = "Im Abkommensbildschirm fügt Umschalt+Klick auf eine verfügbare Ressource, Gold, Gold pro Runde oder Diplomatische Gunst so viel hinzu, wie das Abkommen zulässt, und Strg+Klick das Zehnfache eines normalen Klicks: 10 einer Ressource, 1000 Gold, 100 Gold pro Runde, 10 Diplomatische Gunst. Ohne diese Option muss eine größere Menge im Mengenfeld eingegeben werden. Rein lokal: keine Auswirkung auf andere Spieler.", es_ES = "En la pantalla de acuerdo, sobre un recurso, el oro, el oro por turno o el favor diplomático disponibles, Mayús+clic añade tanto como el acuerdo admite, y Ctrl+clic añade diez veces un clic normal: 10 de un recurso, 1000 de oro, 100 de oro por turno, 10 de favor diplomático. Sin esta opción, una cantidad mayor hay que escribirla en el campo de cantidad. Solo local: sin efecto sobre los demás jugadores.", it_IT = "Nella schermata degli accordi, su una risorsa, sull'oro, sull'oro per turno o sul supporto diplomatico disponibili, Maiusc+clic ne aggiunge quanto l'accordo ne accetta, e Ctrl+clic aggiunge dieci volte un clic normale: 10 di una risorsa, 1000 oro, 100 oro per turno, 10 di supporto diplomatico. Senza questa opzione, una quantità maggiore va digitata nel campo della quantità. Solo locale: nessun effetto sugli altri giocatori.", ja_JP = "取引画面で、提供可能な資源、ゴールド、ターン毎のゴールド、外交的支持を Shift+クリックすると取引に入れられる上限まで、Ctrl+クリックすると通常のクリックの 10 倍 (資源 10、ゴールド 1000、ターン毎のゴールド 100、外交的支持 10) を追加します。このオプションがない場合、それより多い数量は数量欄に入力する必要があります。ローカルのみ：他のプレイヤーには影響しません。", ko_KR = "거래 화면에서 제공 가능한 자원, 금, 턴당 금, 외교적 환심을 Shift+클릭하면 거래에 넣을 수 있는 최대 수량을, Ctrl+클릭하면 일반 클릭의 10배(자원 10, 금 1000, 턴당 금 100, 외교적 환심 10)를 추가합니다. 이 옵션이 없으면 더 많은 수량은 수량 입력란에 직접 입력해야 합니다. 로컬 전용: 다른 플레이어에게 영향이 없습니다.", pl_PL = "Na ekranie umowy Shift+klik na dostępnym zasobie, złocie, złocie na turę lub dyplomatycznych względach dodaje tyle, ile umowa przyjmie, a Ctrl+klik dodaje dziesięć razy więcej niż zwykły klik: 10 sztuk zasobu, 1000 złota, 100 złota na turę, 10 dyplomatycznych względów. Bez tej opcji większą ilość trzeba wpisać w polu ilości. Działa tylko lokalnie: bez wpływu na innych graczy.", pt_BR = "Na tela de acordo, em um recurso, ouro, ouro por turno ou Favorecimento Diplomático disponível, Shift+clique adiciona tanto quanto o acordo aceita, e Ctrl+clique adiciona dez vezes um clique normal: 10 de um recurso, 1000 de ouro, 100 de ouro por turno, 10 de Favorecimento Diplomático. Sem esta opção, uma quantidade maior precisa ser digitada no campo de quantidade. Apenas local: sem efeito sobre os outros jogadores.", ru_RU = "На экране сделки Shift+щелчок по доступному ресурсу, золоту, золоту за ход или мировому влиянию добавляет столько, сколько допускает сделка, а Ctrl+щелчок добавляет в десять раз больше обычного щелчка: 10 единиц ресурса, 1000 золота, 100 золота за ход, 10 мирового влияния. Без этой настройки большее количество приходится вводить в поле количества. Только локально: не влияет на других игроков.", zh_Hans_CN = "在交易界面中，对可用的资源、金币、每回合金币或外交支持，按住 Shift 单击会加入交易所能接受的最大数量，按住 Ctrl 单击则加入普通单击的 10 倍：10 个资源、1000 金币、每回合 100 金币、10 点外交支持。没有此选项时，更大的数量需要在数量框中输入。仅限本地：不影响其他玩家。" },
	LOC_BGD_OPT_UI_ACCORD_QUANTITES_NOM = { en_US = "Shift+click and Ctrl+click in the deal screen", fr_FR = "Maj+clic et Ctrl+clic dans l'écran d'accord", de_DE = "Umschalt+Klick und Strg+Klick im Abkommensbildschirm", es_ES = "Mayús+clic y Ctrl+clic en la pantalla de acuerdo", it_IT = "Maiusc+clic e Ctrl+clic nella schermata degli accordi", ja_JP = "取引画面の Shift+クリックと Ctrl+クリック", ko_KR = "거래 화면의 Shift+클릭 및 Ctrl+클릭", pl_PL = "Shift+klik i Ctrl+klik na ekranie umowy", pt_BR = "Shift+clique e Ctrl+clique na tela de acordo", ru_RU = "Shift+щелчок и Ctrl+щелчок на экране сделки", zh_Hans_CN = "交易界面的 Shift+单击和 Ctrl+单击" },
	LOC_BGD_OPT_UI_AVANCEMENT_AIDE = { en_US = "Next to the name of the current technology and civic, in the top-left panel, shows the science (culture) already put in, the total cost and, in brackets, the science (culture) kept in excess from a finished technology (civic), for example 120/260 (+15). Display only.", fr_FR = "À côté du nom de la technologie et du dogme en cours, dans le panneau en haut à gauche, affiche la science (la culture) déjà investie, le coût total et, entre parenthèses, la science (la culture) gardée en excédent d'une technologie (d'un dogme) terminée, par exemple 120/260 (+15). Affichage seulement.", de_DE = "Zeigt neben dem Namen der aktuellen Technologie und Ausrichtung im Panel oben links die bereits investierte Wissenschaft (Kultur) die Gesamtkosten und in Klammern die aus einer abgeschlossenen Technologie (Ausrichtung) übrig gebliebene Wissenschaft (Kultur) an, zum Beispiel 120/260 (+15). Nur Anzeige.", es_ES = "Junto al nombre de la tecnología y el principio en curso, en el panel superior izquierdo, muestra la ciencia (la cultura) ya invertida, el coste total y, entre paréntesis, la ciencia (la cultura) sobrante de una tecnología (un principio) terminada, por ejemplo 120/260 (+15). Solo visualización.", it_IT = "Accanto al nome della tecnologia e del civico in corso, nel pannello in alto a sinistra, mostra la scienza (la cultura) già investita, il costo totale e, tra parentesi, la scienza (la cultura) in eccesso da una tecnologia (un civico) completata, per esempio 120/260 (+15). Solo visualizzazione.", ja_JP = "左上のパネルで、研究中のテクノロジーと社会制度の名前の横に、投入済みの科学力 (文化力) 、総コスト、括弧内に完了したテクノロジー (社会制度) から繰り越された余剰の科学力 (文化力) を表示します (例: 120/260 (+15))。表示のみ。", ko_KR = "왼쪽 위 패널에서 진행 중인 기술과 사회 제도 이름 옆에 이미 투입한 과학(문화), 전체 비용, 괄호 안에 완료한 기술(사회 제도)에서 남아 이월된 과학(문화)을 표시합니다 (예: 120/260 (+15)). 표시만 바뀝니다.", pl_PL = "Obok nazwy bieżącej technologii i idei, w panelu w lewym górnym rogu, pokazuje już włożoną naukę (kulturę) , całkowity koszt oraz w nawiasie nadwyżkę nauki (kultury) z ukończonej technologii (idei), na przykład 120/260 (+15). Tylko wyświetlanie.", pt_BR = "Ao lado do nome da tecnologia e do princípio em andamento, no painel superior esquerdo, mostra a ciência (a cultura) já investida, o custo total e, entre parênteses, a ciência (a cultura) excedente de uma tecnologia (um princípio) concluída, por exemplo 120/260 (+15). Apenas exibição.", ru_RU = "Рядом с названием текущей технологии и цивика, на панели в левом верхнем углу, показывает уже вложенную науку (культуру) , полную стоимость и в скобках излишек науки (культуры) от завершённой технологии (цивика), например 120/260 (+15). Только отображение.", zh_Hans_CN = "在左上角面板中，当前科技和市政名称旁显示已投入的科技值（文化值）、总花费，以及括号内已完成科技（市政）溢出的科技值（文化值），例如 120/260 (+15)。仅影响显示。" },
	LOC_BGD_OPT_UI_AVANCEMENT_NOM = { en_US = "Research and civic progress", fr_FR = "Avancement de la recherche et du dogme", de_DE = "Fortschritt von Forschung und Ausrichtung", es_ES = "Progreso de investigación y principio", it_IT = "Avanzamento di ricerca e civico", ja_JP = "研究と社会制度の進捗", ko_KR = "연구 및 사회 제도 진행도", pl_PL = "Postęp badań i ustroju", pt_BR = "Progresso da pesquisa e do princípio", ru_RU = "Прогресс исследования и цивика", zh_Hans_CN = "科技与市政进度" },
	LOC_BGD_OPT_UI_BANDEAU_AIDE = { en_US = "Based on TopPanel Extension Pro (号码菌 / Azukii). Food, production, population, average amenities per city and luxury resources in the top panel, with per-city details; teammates' resources. Replaces the mod if it is active. Without the mod, Better Spectator Mod's top panel is kept.", fr_FR = "D'après TopPanel Extension Pro (号码菌 / Azukii). Nourriture, production, population, activités moyennes par ville et ressources de luxe dans le bandeau, avec le détail par ville ; ressources des coéquipiers. Remplace le mod s'il est actif. Sans le mod, le bandeau de Better Spectator Mod est gardé.", de_DE = "Nach TopPanel Extension Pro (号码菌 / Azukii). Nahrung, Produktion, Bevölkerung, durchschnittliche Annehmlichkeiten pro Stadt und Luxusressourcen in der oberen Leiste, mit Details pro Stadt; Ressourcen der Teamkameraden. Ersetzt den Mod, wenn er aktiv ist. Ohne den Mod bleibt die obere Leiste von Better Spectator Mod erhalten.", es_ES = "Basado en TopPanel Extension Pro (号码菌 / Azukii). Comida, producción, población, servicios medios por ciudad y recursos de lujo en la barra superior, con el detalle por ciudad; recursos de los compañeros de equipo. Sustituye al mod si está activo. Sin el mod, se conserva la barra superior de Better Spectator Mod.", it_IT = "Basato su TopPanel Extension Pro (号码菌 / Azukii). Cibo, produzione, popolazione, attrattiva media per città e risorse di lusso nella barra superiore, con il dettaglio per città; risorse dei compagni di squadra. Sostituisce la mod se è attiva. Senza la mod, la barra superiore di Better Spectator Mod viene mantenuta.", ja_JP = "TopPanel Extension Pro (号码菌 / Azukii) に基づきます。食料、生産力、人口、都市あたりの平均快適性、高級資源を都市ごとの詳細とともに上部バーに表示し、チームメイトの資源も表示します。MOD が有効な場合はそれに置き換わります。MOD がない場合は Better Spectator Mod の上部バーが維持されます。", ko_KR = "TopPanel Extension Pro(号码菌 / Azukii) 기반. 식량, 생산력, 인구, 도시당 평균 쾌적도, 사치 자원을 도시별 상세 정보와 함께 상단 바에 표시하고, 팀원의 자원도 보여 줍니다. 모드가 켜져 있으면 모드를 대체합니다. 모드가 없으면 Better Spectator Mod의 상단 바가 유지됩니다.", pl_PL = "Na podstawie TopPanel Extension Pro (号码菌 / Azukii). Żywność, produkcja, populacja, średnie udogodnienia na miasto i zasoby luksusowe w górnym pasku, ze szczegółami dla każdego miasta; zasoby sojuszników z drużyny. Zastępuje moda, jeśli jest aktywny. Bez moda zachowany jest górny pasek Better Spectator Mod.", pt_BR = "Baseado em TopPanel Extension Pro (号码菌 / Azukii). Comida, produção, população, média de serviços por cidade e recursos de luxo na barra superior, com o detalhe por cidade; recursos dos colegas de equipe. Substitui o mod se ele estiver ativo. Sem o mod, a barra superior do Better Spectator Mod é mantida.", ru_RU = "На основе TopPanel Extension Pro (号码菌 / Azukii). Пища, производство, население, среднее довольство на город и ресурсы роскоши на верхней панели, с подробностями по городам; ресурсы союзников по команде. Заменяет мод, если он включён. Без мода сохраняется верхняя панель Better Spectator Mod.", zh_Hans_CN = "基于 TopPanel Extension Pro（号码菌 / Azukii）。在顶部栏显示食物、生产力、人口、每座城市的平均宜居度和奢侈品资源，并附各城市详情；还显示队友的资源。如果该模组已启用，则取代它。没有该模组时，保留 Better Spectator Mod 的顶部栏。" },
	LOC_BGD_OPT_UI_BANDEAU_NOM = { en_US = "Extended top panel", fr_FR = "Bandeau du haut étendu", de_DE = "Erweiterte obere Leiste", es_ES = "Barra superior ampliada", it_IT = "Barra superiore estesa", ja_JP = "拡張された上部バー", ko_KR = "확장된 상단 바", pl_PL = "Rozszerzony górny pasek", pt_BR = "Barra superior ampliada", ru_RU = "Расширенная верхняя панель", zh_Hans_CN = "扩展顶部栏" },
	LOC_BGD_OPT_UI_BANNIERE_ANNULER_AIDE = { en_US = "A right-click on the production icon of one of your city banners removes the item being produced, like a right-click in the production panel. Normal game command: no desync.", fr_FR = "Un clic droit sur l'icône de production du bandeau d'une de vos villes retire l'élément en cours, comme un clic droit dans le panneau de production. Commande normale du jeu : pas de désynchronisation.", de_DE = "Ein Rechtsklick auf das Produktionssymbol im Banner einer eurer Städte entfernt das aktuelle Element, wie ein Rechtsklick im Produktionsfenster. Normaler Spielbefehl: keine Desynchronisation.", es_ES = "Un clic derecho en el icono de producción del estandarte de una de tus ciudades retira el elemento en curso, como un clic derecho en el panel de producción. Orden normal del juego: sin desincronización.", it_IT = "Un clic destro sull'icona di produzione dello stendardo di una delle tue città rimuove l'elemento in corso, come un clic destro nel pannello di produzione. Comando normale del gioco: nessuna desincronizzazione.", ja_JP = "自分の都市バナーの生産アイコンを右クリックすると、生産パネルでの右クリックと同じく、生産中の項目を取り除きます。通常のゲームコマンドなので同期ずれは起きません。", ko_KR = "내 도시 배너의 생산 아이콘을 우클릭하면 생산 패널에서 우클릭할 때처럼 생산 중인 항목을 제거합니다. 일반 게임 명령이므로 동기화 오류가 생기지 않습니다.", pl_PL = "Prawy klik na ikonę produkcji w banerze jednego z twoich miast usuwa bieżący element, tak jak prawy klik w panelu produkcji. Zwykłe polecenie gry: bez desynchronizacji.", pt_BR = "Um clique direito no ícone de produção do estandarte de uma de suas cidades remove o item em andamento, como um clique direito no painel de produção. Comando normal do jogo: sem dessincronização.", ru_RU = "Правый щелчок по значку производства на баннере вашего города убирает текущий элемент, как правый щелчок в панели производства. Обычная команда игры: без рассинхронизации.", zh_Hans_CN = "右键单击你的城市横幅上的生产图标，会像在生产面板中右键单击一样移除正在生产的项目。正常的游戏指令：不会不同步。" },
	LOC_BGD_OPT_UI_BANNIERE_ANNULER_NOM = { en_US = "Right-click the city banner production to cancel it", fr_FR = "Clic droit sur la production du bandeau de ville pour l'annuler", de_DE = "Rechtsklick auf die Produktion im Stadtbanner bricht sie ab", es_ES = "Clic derecho en la producción del estandarte de la ciudad para cancelarla", it_IT = "Clic destro sulla produzione dello stendardo della città per annullarla", ja_JP = "都市バナーの生産を右クリックで取り消す", ko_KR = "도시 배너의 생산을 우클릭해 취소", pl_PL = "Prawy klik na produkcję w banerze miasta, aby ją anulować", pt_BR = "Clique direito na produção do estandarte da cidade para cancelá-la", ru_RU = "Правый щелчок по производству на баннере города отменяет его", zh_Hans_CN = "右键单击城市横幅上的生产以取消" },
	LOC_BGD_OPT_UI_BOUTONS_AIDE = { en_US = "City and encampment attack buttons, and silo nuclear strike buttons, are drawn above unit flags, where they stay clickable.", fr_FR = "Les boutons d'attaque des villes et des campements, et ceux de frappe nucléaire des silos, passent au-dessus des drapeaux d'unités, où ils restent cliquables.", de_DE = "Die Angriffsschaltflächen von Städten und Lagern sowie die Atomschlag-Schaltflächen der Silos werden über den Einheitenflaggen gezeichnet, wo sie anklickbar bleiben.", es_ES = "Los botones de ataque de ciudades y campamentos, y los de ataque nuclear de los silos, se dibujan sobre las banderas de unidades, donde se pueden pulsar.", it_IT = "I pulsanti di attacco delle città e degli accampamenti, e quelli di attacco nucleare dei silos, vengono disegnati sopra le bandiere delle unità, dove restano cliccabili.", ja_JP = "都市と兵営の攻撃ボタン、およびサイロの核攻撃ボタンをユニットの旗より手前に表示し、クリックできるようにします。", ko_KR = "도시와 주둔지의 공격 버튼, 사일로의 핵 공격 버튼을 유닛 깃발 위에 그려 클릭할 수 있게 합니다.", pl_PL = "Przyciski ataku miast i dzielnic wojskowych oraz przyciski ataku jądrowego silosów są rysowane nad flagami jednostek, gdzie można je kliknąć.", pt_BR = "Os botões de ataque das cidades e dos acampamentos, e os de ataque nuclear dos silos, são desenhados acima das bandeiras das unidades, onde continuam clicáveis.", ru_RU = "Кнопки атаки городов и военных лагерей, а также кнопки ядерного удара из шахт рисуются поверх флагов отрядов, где на них можно нажать.", zh_Hans_CN = "城市和军营的攻击按钮，以及发射井的核打击按钮，绘制在单位旗帜上方，保持可点击。" },
	LOC_BGD_OPT_UI_BOUTONS_NOM = { en_US = "Attack buttons above unit flags", fr_FR = "Boutons d'attaque au-dessus des drapeaux d'unités", de_DE = "Angriffsschaltflächen über den Einheitenflaggen", es_ES = "Botones de ataque sobre las banderas de unidades", it_IT = "Pulsanti di attacco sopra le bandiere delle unità", ja_JP = "ユニットの旗より手前に攻撃ボタン", ko_KR = "유닛 깃발 위의 공격 버튼", pl_PL = "Przyciski ataku nad flagami jednostek", pt_BR = "Botões de ataque acima das bandeiras das unidades", ru_RU = "Кнопки атаки поверх флагов отрядов", zh_Hans_CN = "攻击按钮显示在单位旗帜上方" },
	LOC_BGD_OPT_UI_CARTE_ENTIERE_AIDE = { en_US = "The minimap and the camera cover the whole map from the first turn, without placing map pins at the edges. Unexplored areas stay hidden. Purely local: no effect on other players in multiplayer.", fr_FR = "La minimap et la caméra couvrent toute la carte dès le premier tour, sans poser d'épingles aux bords. Les zones inexplorées restent cachées. Purement local : sans effet sur les autres joueurs en multijoueur.", de_DE = "Minikarte und Kamera umfassen ab der ersten Runde die ganze Karte, ohne Kartenmarkierungen an den Rändern. Unerforschte Gebiete bleiben verborgen. Rein lokal: keine Auswirkung auf andere Spieler im Mehrspielermodus.", es_ES = "El minimapa y la cámara abarcan todo el mapa desde el primer turno, sin colocar marcadores en los bordes. Las zonas inexploradas siguen ocultas. Solo local: sin efecto sobre los demás jugadores en multijugador.", it_IT = "La minimappa e la telecamera coprono l'intera mappa dal primo turno, senza piazzare segnalini ai bordi. Le zone inesplorate restano nascoste. Solo locale: nessun effetto sugli altri giocatori in multigiocatore.", ja_JP = "ミニマップとカメラが最初のターンからマップ全体を範囲にします。端にマップピンを置く必要はありません。未探索の地域は隠れたままです。ローカルのみ：マルチプレイで他のプレイヤーには影響しません。", ko_KR = "미니맵과 카메라가 첫 턴부터 지도 전체를 다룹니다. 가장자리에 지도 핀을 놓을 필요가 없습니다. 탐험하지 않은 지역은 계속 가려집니다. 로컬 전용: 멀티플레이에서 다른 플레이어에게 영향이 없습니다.", pl_PL = "Minimapa i kamera obejmują całą mapę od pierwszej tury, bez stawiania znaczników na krawędziach. Niezbadane obszary pozostają ukryte. Działa tylko lokalnie: bez wpływu na innych graczy w trybie wieloosobowym.", pt_BR = "O minimapa e a câmera cobrem o mapa inteiro desde o primeiro turno, sem colocar marcadores nas bordas. As áreas inexploradas continuam ocultas. Apenas local: sem efeito sobre os outros jogadores no multijogador.", ru_RU = "Миникарта и камера охватывают всю карту с первого хода, без меток по краям. Неисследованные области остаются скрытыми. Только локально: не влияет на других игроков в сетевой игре.", zh_Hans_CN = "小地图和镜头从第一回合起就覆盖整张地图，无需在边缘放置地图标记。未探索的区域仍然隐藏。仅限本地：在多人游戏中不影响其他玩家。" },
	LOC_BGD_OPT_UI_CARTE_ENTIERE_NOM = { en_US = "Whole map from the start", fr_FR = "Carte entière dès le début", de_DE = "Ganze Karte von Anfang an", es_ES = "Mapa completo desde el inicio", it_IT = "Mappa intera fin dall'inizio", ja_JP = "最初からマップ全体", ko_KR = "처음부터 지도 전체", pl_PL = "Cała mapa od początku", pt_BR = "Mapa inteiro desde o início", ru_RU = "Вся карта с самого начала", zh_Hans_CN = "从一开始显示整张地图" },
	LOC_BGD_OPT_UI_CHARGES_AIDE = { en_US = "Based on Better Builder Charges Tracking (wltk). The flag of a unit with charges (builder, military engineer…) shows them instead of promotions, except combat units (land, naval or air: Roman legion, nau…), which keep their promotions. Replaces the mod if it is active.", fr_FR = "D'après Better Builder Charges Tracking (wltk). Le drapeau d'une unité qui a des charges (bâtisseur, ingénieur militaire…) les montre à la place des promotions, sauf les unités de combat (terrestres, navales ou aériennes : légion romaine, nau…), qui gardent leurs promotions. Remplace le mod s'il est actif.", de_DE = "Nach Better Builder Charges Tracking (wltk). Die Flagge einer Einheit mit Ladungen (Handwerker, Militärpionier …) zeigt diese statt der Beförderungen, außer bei Kampfeinheiten (zu Land, zur See oder in der Luft: Legion, Nau …): Sie behalten ihre Beförderungen. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Better Builder Charges Tracking (wltk). La bandera de una unidad con cargas (constructor, ingeniero militar…) las muestra en lugar de los ascensos, salvo las unidades de combate (terrestres, navales o aéreas: legión, nao…), que conservan sus ascensos. Sustituye al mod si está activo.", it_IT = "Basato su Better Builder Charges Tracking (wltk). La bandiera di un'unità con cariche (costruttore, ingegnere militare…) le mostra al posto delle promozioni, tranne le unità da combattimento (terrestri, navali o aeree: legione, nau…), che mantengono le loro promozioni. Sostituisce la mod se è attiva.", ja_JP = "Better Builder Charges Tracking (wltk) に基づきます。残り回数を持つユニット (労働者、工兵など) の旗に、昇進の代わりにそれを表示します。戦闘ユニット (陸上・海上・航空: レギオン、ナウなど) は昇進の表示のままです。MOD が有効な場合はそれに置き換わります。", ko_KR = "Better Builder Charges Tracking(wltk) 기반. 건설력이 있는 유닛(건설자, 공병 등)의 깃발에 진급 대신 건설력을 표시합니다. 전투 유닛(지상, 해상, 공중: 군단병, 나우 등)은 진급 표시를 유지합니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Better Builder Charges Tracking (wltk). Flaga jednostki z ładunkami (budowniczy, inżynier wojskowy…) pokazuje je zamiast awansów, z wyjątkiem jednostek bojowych (lądowych, morskich i powietrznych: legion, nau…) – te zachowują awanse. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Better Builder Charges Tracking (wltk). A bandeira de uma unidade com cargas (construtor, engenheiro militar…) as mostra no lugar das promoções, exceto as unidades de combate (terrestres, navais ou aéreas: legião, nau…), que mantêm suas promoções. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Better Builder Charges Tracking (wltk). Флаг отряда с зарядами (строитель, военный инженер…) показывает их вместо повышений, кроме боевых отрядов (сухопутных, морских и воздушных: легион, нау…): у них остаются повышения. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Better Builder Charges Tracking（wltk）。有可用次数的单位（建造者、军事工程师……）的旗帜上显示次数，代替晋升；作战单位（陆地、海上、空中：罗马军团、纳乌战舰……）仍显示晋升。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_CHARGES_NOM = { en_US = "Builder charges on their flag", fr_FR = "Charges des bâtisseurs sur leur drapeau", de_DE = "Ladungen der Handwerker auf ihrer Flagge", es_ES = "Cargas de los constructores en su bandera", it_IT = "Cariche dei costruttori sulla loro bandiera", ja_JP = "労働者の残り回数を旗に表示", ko_KR = "깃발에 건설자 건설력 표시", pl_PL = "Ładunki budowniczych na ich fladze", pt_BR = "Cargas dos construtores na bandeira", ru_RU = "Заряды строителей на их флаге", zh_Hans_CN = "在旗帜上显示建造者次数" },
	LOC_BGD_OPT_UI_DEBORDEMENT_AIDE = { en_US = "Shows the production a city keeps in reserve (overflow, at most one turn), which is added to its production next turn: on the city banner, in the city panel and in the production panel. Display only.", fr_FR = "Affiche la production qu'une ville garde en réserve (débordement, au plus un tour), ajoutée à sa production du tour suivant : sur le bandeau de ville, dans le panneau de la ville et dans le panneau de production. Affichage seulement.", de_DE = "Zeigt die Produktion, die eine Stadt in Reserve hält (Überschuss, höchstens eine Runde) und die in der nächsten Runde zu ihrer Produktion hinzukommt: im Stadtbanner, im Stadtfenster und im Produktionsfenster. Nur Anzeige.", es_ES = "Muestra la producción que una ciudad guarda en reserva (excedente, como máximo un turno), que se suma a su producción del turno siguiente: en el estandarte de la ciudad, en el panel de la ciudad y en el panel de producción. Solo visualización.", it_IT = "Mostra la produzione che una città tiene in riserva (eccedenza, al massimo un turno), aggiunta alla sua produzione del turno successivo: sullo stendardo della città, nel pannello della città e nel pannello di produzione. Solo visualizzazione.", ja_JP = "都市が蓄えている生産力 (余剰分、最大 1 ターン分) を、都市バナー、都市パネル、生産パネルに表示します。これは次のターンの生産力に加算されます。表示のみ。", ko_KR = "도시가 비축한 생산력(초과분, 최대 1턴)을 도시 배너, 도시 패널, 생산 패널에 표시합니다. 이 생산력은 다음 턴 생산에 더해집니다. 표시만 바뀝니다.", pl_PL = "Pokazuje produkcję, którą miasto trzyma w zapasie (nadwyżka, najwyżej jedna tura) i która dochodzi do jego produkcji w następnej turze: w banerze miasta, w panelu miasta i w panelu produkcji. Tylko wyświetlanie.", pt_BR = "Mostra a produção que uma cidade guarda em reserva (excedente, no máximo um turno), somada à sua produção do turno seguinte: no estandarte da cidade, no painel da cidade e no painel de produção. Apenas exibição.", ru_RU = "Показывает производство, которое город держит в запасе (излишек, не больше одного хода) и которое добавится к его производству на следующем ходу: на баннере города, в панели города и в панели производства. Только отображение.", zh_Hans_CN = "在城市横幅、城市面板和生产面板中显示城市储备的生产力（溢出部分，最多一回合），它会加到下一回合的生产中。仅影响显示。" },
	LOC_BGD_OPT_UI_DEBORDEMENT_NOM = { en_US = "Stored production", fr_FR = "Production en réserve", de_DE = "Gespeicherte Produktion", es_ES = "Producción en reserva", it_IT = "Produzione in riserva", ja_JP = "蓄えられた生産力", ko_KR = "비축된 생산력", pl_PL = "Zachowana produkcja", pt_BR = "Produção em reserva", ru_RU = "Запасённое производство", zh_Hans_CN = "储备的生产力" },
	LOC_BGD_OPT_UI_DIAG_ACCORDS_AIDE = { en_US = "Writes to Lua.log the deal proposals sent and received, and what the deal screen shows, to understand crossed deals between humans.", fr_FR = "Écrit dans Lua.log les propositions d'accord reçues et envoyées, et ce que montre l'écran d'accord, pour comprendre les accords croisés entre humains.", de_DE = "Schreibt in Lua.log die gesendeten und empfangenen Abkommensvorschläge und was der Abkommensbildschirm zeigt, um gekreuzte Abkommen zwischen Menschen zu verstehen.", es_ES = "Escribe en Lua.log las propuestas de acuerdo enviadas y recibidas, y lo que muestra la pantalla de acuerdo, para entender los acuerdos cruzados entre humanos.", it_IT = "Scrive in Lua.log le proposte di accordo inviate e ricevute, e ciò che mostra la schermata degli accordi, per capire gli accordi incrociati tra umani.", ja_JP = "送受信した取引の提案と取引画面の表示内容を Lua.log に書き込み、人間同士の取引の行き違いを調べます。", ko_KR = "보내고 받은 거래 제안과 거래 화면의 내용을 Lua.log에 기록해, 사람 사이의 엇갈린 거래를 분석합니다.", pl_PL = "Zapisuje w Lua.log wysłane i otrzymane propozycje umów oraz to, co pokazuje ekran umowy, aby zrozumieć krzyżujące się umowy między ludźmi.", pt_BR = "Escreve no Lua.log as propostas de acordo enviadas e recebidas, e o que a tela de acordo mostra, para entender os acordos cruzados entre humanos.", ru_RU = "Записывает в Lua.log отправленные и полученные предложения сделок и то, что показывает экран сделки, чтобы разобраться в перекрёстных сделках между людьми.", zh_Hans_CN = "将发送和收到的交易提议以及交易界面显示的内容写入 Lua.log，用于分析人类玩家之间交错的交易。" },
	LOC_BGD_OPT_UI_DIAG_ACCORDS_NOM = { en_US = "Diagnose deals between players", fr_FR = "Diagnostic des accords entre joueurs", de_DE = "Diagnose der Abkommen zwischen Spielern", es_ES = "Diagnóstico de los acuerdos entre jugadores", it_IT = "Diagnostica degli accordi tra giocatori", ja_JP = "プレイヤー間の取引の診断", ko_KR = "플레이어 간 거래 진단", pl_PL = "Diagnostyka umów między graczami", pt_BR = "Diagnóstico dos acordos entre jogadores", ru_RU = "Диагностика сделок между игроками", zh_Hans_CN = "玩家间交易诊断" },
	LOC_BGD_OPT_UI_EPINGLES_AIDE = { en_US = "Map pins and their list are no longer rebuilt when nothing changed: fewer slowdowns in multiplayer.", fr_FR = "Les épingles et leur liste ne sont plus reconstruites quand rien n'a changé : moins de ralentissements en multijoueur.", de_DE = "Kartenmarkierungen und ihre Liste werden nicht mehr neu aufgebaut, wenn sich nichts geändert hat: weniger Ruckler im Mehrspielermodus.", es_ES = "Los marcadores y su lista ya no se reconstruyen cuando nada ha cambiado: menos ralentizaciones en multijugador.", it_IT = "I segnalini e il loro elenco non vengono più ricostruiti quando nulla è cambiato: meno rallentamenti in multigiocatore.", ja_JP = "変化がないときはマップピンとその一覧を再構築しません。マルチプレイでの引っかかりが減ります。", ko_KR = "바뀐 것이 없으면 지도 핀과 그 목록을 다시 만들지 않습니다. 멀티플레이에서 끊김이 줄어듭니다.", pl_PL = "Znaczniki i ich lista nie są już przebudowywane, gdy nic się nie zmieniło: mniej spowolnień w trybie wieloosobowym.", pt_BR = "Os marcadores e sua lista não são mais reconstruídos quando nada mudou: menos travamentos no multijogador.", ru_RU = "Метки и их список больше не перестраиваются, если ничего не изменилось: меньше подтормаживаний в сетевой игре.", zh_Hans_CN = "没有变化时不再重建地图标记及其列表：减少多人游戏中的卡顿。" },
	LOC_BGD_OPT_UI_EPINGLES_NOM = { en_US = "Lighter map pins", fr_FR = "Épingles de carte allégées", de_DE = "Leichtere Kartenmarkierungen", es_ES = "Marcadores de mapa más ligeros", it_IT = "Segnalini della mappa più leggeri", ja_JP = "マップピンの軽量化", ko_KR = "가벼운 지도 핀", pl_PL = "Lżejsze znaczniki mapy", pt_BR = "Marcadores do mapa mais leves", ru_RU = "Облегчённые метки карты", zh_Hans_CN = "更轻量的地图标记" },
	LOC_BGD_OPT_UI_ESPIONS_AIDE = { en_US = "The success chance shown for a spy mission also counts the escape: a success where the spy must escape only counts if the spy gets away, since the loot is only delivered then. Assumes the best escape route and does not count an enemy counterspy. Display only.", fr_FR = "La chance de succès affichée pour une mission d'espionnage tient compte de l'évasion : un succès où l'espion doit s'échapper ne compte que s'il s'en sort, car le butin n'est versé qu'à ce moment. Suppose le meilleur itinéraire de fuite et ne compte pas un contre-espion ennemi. Affichage seulement.", de_DE = "Die angezeigte Erfolgschance einer Spionagemission berücksichtigt auch die Flucht: Ein Erfolg, bei dem der Spion fliehen muss, zählt nur, wenn er entkommt, denn erst dann wird die Beute ausgezahlt. Geht vom besten Fluchtweg aus und berücksichtigt keinen feindlichen Gegenspion. Nur Anzeige.", es_ES = "La probabilidad de éxito que se muestra en una misión de espionaje tiene en cuenta la huida: un éxito en el que el espía debe escapar solo cuenta si logra huir, porque el botín solo se entrega entonces. Supone la mejor ruta de huida y no tiene en cuenta un contraespía enemigo. Solo visualización.", it_IT = "La probabilità di successo mostrata per una missione di spionaggio tiene conto della fuga: un successo in cui la spia deve fuggire conta solo se la spia riesce a scappare, perché il bottino viene consegnato solo allora. Presuppone la via di fuga migliore e non considera un controspionaggio nemico. Solo visualizzazione.", ja_JP = "スパイ任務に表示される成功率に脱出も含めます。脱出が必要な成功は、スパイが逃げ切った場合にのみ成功とみなします (戦利品はその時点でのみ得られるため)。最適な脱出ルートを前提とし、敵の防諜は考慮しません。表示のみ。", ko_KR = "스파이 작전에 표시되는 성공 확률에 탈출을 반영합니다. 탈출해야 하는 성공은 스파이가 빠져나왔을 때만 성공으로 칩니다(전리품은 그때만 지급되기 때문). 가장 좋은 탈출 경로를 가정하며, 적의 방첩은 고려하지 않습니다. 표시만 바뀝니다.", pl_PL = "Szansa powodzenia wyświetlana dla misji szpiegowskiej uwzględnia ucieczkę: sukces, po którym szpieg musi uciekać, liczy się tylko wtedy, gdy szpiegowi uda się uciec, bo dopiero wtedy łup zostaje przekazany. Zakłada najlepszą drogę ucieczki i nie uwzględnia wrogiego kontrwywiadu. Tylko wyświetlanie.", pt_BR = "A chance de sucesso exibida para uma missão de espionagem leva em conta a fuga: um sucesso em que o espião precisa fugir só conta se ele escapar, pois o espólio só é entregue nesse momento. Supõe a melhor rota de fuga e não considera um contraespião inimigo. Apenas exibição.", ru_RU = "Шанс успеха, показываемый для шпионской операции, учитывает побег: успех, после которого шпион должен бежать, засчитывается, только если шпиону удалось уйти, ведь добыча выдаётся только тогда. Предполагается лучший путь отхода, вражеская контрразведка не учитывается. Только отображение.", zh_Hans_CN = "间谍任务显示的成功率会计入撤离：需要撤离的成功只有在间谍成功逃脱时才算成功，因为战利品只在那时发放。假定选择最佳撤离路线，不计算敌方反间谍。仅影响显示。" },
	LOC_BGD_OPT_UI_ESPIONS_NOM = { en_US = "Spy success chance that counts the escape", fr_FR = "Chance de succès des espions avec l'évasion", de_DE = "Spion-Erfolgschance mit Flucht", es_ES = "Probabilidad de éxito de los espías con la huida", it_IT = "Probabilità di successo delle spie con la fuga", ja_JP = "脱出を考慮したスパイの成功率", ko_KR = "탈출을 반영한 스파이 성공 확률", pl_PL = "Szansa powodzenia szpiegów z ucieczką", pt_BR = "Chance de sucesso dos espiões com a fuga", ru_RU = "Шанс успеха шпионов с учётом побега", zh_Hans_CN = "计入撤离的间谍成功率" },
	LOC_BGD_OPT_UI_FORMATIONS_AIDE = { en_US = "In the production list, a unit's main button trains the highest formation the city can train (Army, otherwise Corps), and the single unit moves to the drop-down under it. The game does the reverse. Gold and Faith purchases are unchanged.", fr_FR = "Dans la liste de production, le bouton principal d'une unité forme la plus haute formation que la ville peut former (armée, sinon régiment), et l'unité seule passe dans le menu déroulant en dessous. Le jeu fait l'inverse. Les achats en or et en foi ne changent pas.", de_DE = "In der Produktionsliste bildet die Hauptschaltfläche einer Einheit die höchste Formation aus, die die Stadt ausbilden kann (Armee, sonst Korps); die einzelne Einheit wandert in das Aufklappmenü darunter. Das Spiel macht es umgekehrt. Käufe mit Gold und Glauben bleiben unverändert.", es_ES = "En la lista de producción, el botón principal de una unidad entrena la formación más alta que la ciudad puede entrenar (Ejército; si no, Corps), y la unidad individual pasa al desplegable de debajo. El juego hace lo contrario. Las compras con oro y fe no cambian.", it_IT = "Nell'elenco di produzione, il pulsante principale di un'unità addestra la formazione più alta che la città può addestrare (Esercito, altrimenti Corpo), e l'unità singola passa nel menu a discesa sottostante. Il gioco fa il contrario. Gli acquisti con oro e fede non cambiano.", ja_JP = "生産リストで、ユニットのメインボタンが都市で訓練できる最上位の編成 (大軍団、なければ軍団) を訓練するようになり、単独ユニットはその下のドロップダウンに移ります。ゲーム本来の並びとは逆です。ゴールドと信仰力による購入は変わりません。", ko_KR = "생산 목록에서 유닛의 기본 버튼이 도시가 훈련할 수 있는 최상위 편제(군대, 없으면 군단)를 훈련하고, 단일 유닛은 그 아래 드롭다운으로 옮겨집니다. 게임의 기본 순서와 반대입니다. 금과 신앙 구매는 그대로입니다.", pl_PL = "Na liście produkcji główny przycisk jednostki szkoli najwyższą formację, jaką miasto może wyszkolić (armia, w przeciwnym razie korpus), a pojedyncza jednostka trafia do rozwijanej listy poniżej. Gra robi odwrotnie. Zakupy za złoto i wiarę pozostają bez zmian.", pt_BR = "Na lista de produção, o botão principal de uma unidade treina a formação mais alta que a cidade pode treinar (Exército; senão, Corporação), e a unidade individual passa para o menu suspenso abaixo. O jogo faz o contrário. As compras com ouro e fé não mudam.", ru_RU = "В списке производства основная кнопка юнита обучает высшее формирование, доступное городу (армия, иначе корпус), а одиночный юнит переходит в раскрывающийся список под ней. В игре порядок обратный. Покупки за золото и веру не меняются.", zh_Hans_CN = "在生产列表中，单位的主按钮会训练城市可训练的最高编制（军队，否则为军团），单个单位则移到下方的下拉菜单中。游戏原本的顺序与此相反。金币和信仰值购买不受影响。" },
	LOC_BGD_OPT_UI_FORMATIONS_NOM = { en_US = "Highest unit formation first", fr_FR = "Formation la plus haute en premier", de_DE = "Höchste Formation zuerst", es_ES = "Formación más alta primero", it_IT = "Formazione più alta per prima", ja_JP = "最上位の編成を優先表示", ko_KR = "최상위 편제 우선 표시", pl_PL = "Najwyższa formacja jako pierwsza", pt_BR = "Formação mais alta primeiro", ru_RU = "Сначала высшее формирование", zh_Hans_CN = "优先显示最高编制" },
	LOC_BGD_OPT_UI_JOURNAL_AIDE = { en_US = "Writes each interface file read to the proxy log.", fr_FR = "Note chaque fichier d'interface lu dans le journal du proxy.", de_DE = "Schreibt jede gelesene Oberflächendatei in das Proxy-Protokoll.", es_ES = "Anota cada archivo de interfaz leído en el registro del proxy.", it_IT = "Annota ogni file d'interfaccia letto nel registro del proxy.", ja_JP = "読み込まれた各インターフェースファイルをプロキシのログに記録します。", ko_KR = "읽어 들인 각 인터페이스 파일을 프록시 로그에 기록합니다.", pl_PL = "Zapisuje każdy wczytany plik interfejsu w dzienniku proxy.", pt_BR = "Anota cada arquivo de interface lido no registro do proxy.", ru_RU = "Записывает в журнал прокси каждый прочитанный файл интерфейса.", zh_Hans_CN = "将读取的每个界面文件记入代理日志。" },
	LOC_BGD_OPT_UI_JOURNAL_NOM = { en_US = "Log loaded scripts and XML", fr_FR = "Journal des scripts et XML chargés", de_DE = "Geladene Skripte und XML protokollieren", es_ES = "Registrar los scripts y XML cargados", it_IT = "Registra script e XML caricati", ja_JP = "読み込んだスクリプトと XML を記録", ko_KR = "불러온 스크립트와 XML 기록", pl_PL = "Zapisuj wczytane skrypty i XML", pt_BR = "Registrar os scripts e XML carregados", ru_RU = "Журнал загруженных скриптов и XML", zh_Hans_CN = "记录已加载的脚本和 XML" },
	LOC_BGD_OPT_UI_LOGEMENT_AIDE = { en_US = "On your city banners, an orange house appears when a city is one Housing below its cap (growth slowed by 50%), and the red house as soon as it is at the cap (75%). Without this option, the game only shows the red house once the city is over the cap. Display only.", fr_FR = "Sur le bandeau de vos villes, une maison orange apparaît quand il ne reste qu'une habitation avant la limite (croissance ralentie de 50 %), et la maison rouge dès que la limite est atteinte (75 %). Sans cette option, le jeu n'affiche la maison rouge qu'une fois la limite dépassée. Affichage seulement.", de_DE = "Im Banner eurer Städte erscheint ein orangefarbenes Haus, wenn nur noch 1 Wohnraum bis zur Obergrenze frei ist (Wachstum um 50 % gesenkt), und das rote Haus, sobald die Obergrenze erreicht ist (75 %). Ohne diese Option zeigt das Spiel das rote Haus erst, wenn die Obergrenze überschritten ist. Nur Anzeige.", es_ES = "En el estandarte de tus ciudades aparece una casa naranja cuando a la ciudad solo le queda 1 alojamiento para llegar al límite (crecimiento ralentizado un 50 %), y la casa roja en cuanto está en el límite (75 %). Sin esta opción, el juego solo muestra la casa roja cuando la ciudad supera el límite. Solo visualización.", it_IT = "Sullo stendardo delle tue città compare una casa arancione quando alla città manca 1 sola abitazione al limite (crescita rallentata del 50%), e la casa rossa non appena è al limite (75%). Senza questa opzione, il gioco mostra la casa rossa solo quando la città supera il limite. Solo visualizzazione.", ja_JP = "自分の都市バナーに、住宅の上限まであと 1 になるとオレンジ色の家 (人口増加率 50% 鈍化)、上限に達した時点で赤い家 (75% 鈍化) を表示します。このオプションがない場合、ゲームは上限を超えてからしか赤い家を表示しません。表示のみ。", ko_KR = "내 도시 배너에, 주거공간 한도까지 1 남으면 주황색 집(인구 증가 속도 50% 감소), 한도에 도달하는 즉시 빨간색 집(75% 감소)을 표시합니다. 이 옵션이 없으면 게임은 한도를 넘은 뒤에만 빨간색 집을 표시합니다. 표시만 바뀝니다.", pl_PL = "W banerze twoich miast pojawia się pomarańczowy dom, gdy miastu brakuje 1 obszaru mieszkalnego do limitu (przyrost spowolniony o 50%), a czerwony dom, gdy tylko miasto osiągnie limit (75%). Bez tej opcji gra pokazuje czerwony dom dopiero po przekroczeniu limitu. Tylko wyświetlanie.", pt_BR = "No estandarte de suas cidades, uma casa laranja aparece quando falta só 1 habitação para o limite (crescimento diminuído em 50%), e a casa vermelha assim que a cidade está no limite (75%). Sem esta opção, o jogo só mostra a casa vermelha depois que a cidade passa do limite. Apenas exibição.", ru_RU = "На баннере ваших городов появляется оранжевый дом, когда до предела жилья остаётся 1 (рост замедлен на 50%), и красный дом, как только предел достигнут (75%). Без этой настройки игра показывает красный дом только после превышения предела. Только отображение.", zh_Hans_CN = "在你的城市横幅上，距住房上限只差 1 时显示橙色房屋（人口增速减缓 50%），一达到上限就显示红色房屋（减缓 75%）。不启用此选项时，游戏要到超出上限后才会显示红色房屋。仅影响显示。" },
	LOC_BGD_OPT_UI_LOGEMENT_NOM = { en_US = "Early housing warning on the city banner", fr_FR = "Alerte d'habitations sur le bandeau de ville", de_DE = "Frühe Wohnraum-Warnung im Stadtbanner", es_ES = "Aviso anticipado de alojamiento en el estandarte de ciudad", it_IT = "Avviso anticipato sulle abitazioni nello stendardo della città", ja_JP = "都市バナーの住宅の早期警告", ko_KR = "도시 배너의 주거공간 조기 경고", pl_PL = "Wczesne ostrzeżenie o obszarach mieszkalnych w banerze miasta", pt_BR = "Aviso antecipado de habitações no estandarte da cidade", ru_RU = "Раннее предупреждение о жилье на баннере города", zh_Hans_CN = "城市横幅上的住房预警" },
	LOC_BGD_OPT_UI_MERVEILLES_AIDE = { en_US = "A wonder removed from the production queue by a swap is put back, through normal game commands: no desync, even against players without the proxy.", fr_FR = "Une merveille retirée de la file de production par un échange y est remise, par des commandes normales du jeu : pas de désynchronisation, même face à des joueurs sans proxy.", de_DE = "Ein Weltwunder, das durch einen Tausch aus der Produktionswarteschlange entfernt wurde, wird mit normalen Spielbefehlen wieder eingereiht: keine Desynchronisation, auch gegen Spieler ohne Proxy.", es_ES = "Una maravilla retirada de la cola de producción por un intercambio se vuelve a poner, mediante órdenes normales del juego: sin desincronización, incluso contra jugadores sin el proxy.", it_IT = "Una meraviglia tolta dalla coda di produzione da uno scambio viene rimessa, tramite normali comandi del gioco: nessuna desincronizzazione, anche contro giocatori senza il proxy.", ja_JP = "入れ替えによって生産キューから外れた遺産を、通常のゲームコマンドで戻します。プロキシを持たないプレイヤーとも同期ずれは起きません。", ko_KR = "교체로 생산 대기열에서 빠진 불가사의를 일반 게임 명령으로 되돌립니다. 프록시가 없는 플레이어와도 동기화 오류가 생기지 않습니다.", pl_PL = "Cud usunięty z kolejki produkcji przez zamianę zostaje do niej przywrócony zwykłymi poleceniami gry: bez desynchronizacji, także z graczami bez proxy.", pt_BR = "Uma maravilha retirada da fila de produção por uma troca é recolocada, por meio de comandos normais do jogo: sem dessincronização, mesmo contra jogadores sem o proxy.", ru_RU = "Чудо, убранное из очереди производства перестановкой, возвращается в неё обычными командами игры: без рассинхронизации, даже с игроками без прокси.", zh_Hans_CN = "因交换而被移出生产队列的奇观，会通过正常的游戏指令放回：不会不同步，即使对方没有代理。" },
	LOC_BGD_OPT_UI_MERVEILLES_NOM = { en_US = "Wonder kept in the queue after a swap", fr_FR = "Merveille gardée dans la file après un échange", de_DE = "Weltwunder bleibt nach einem Tausch in der Warteschlange", es_ES = "Maravilla conservada en la cola tras un intercambio", it_IT = "Meraviglia mantenuta in coda dopo uno scambio", ja_JP = "入れ替え後も遺産をキューに残す", ko_KR = "교체 후에도 불가사의를 대기열에 유지", pl_PL = "Cud pozostaje w kolejce po zamianie", pt_BR = "Maravilha mantida na fila após uma troca", ru_RU = "Чудо остаётся в очереди после перестановки", zh_Hans_CN = "交换后奇观仍留在队列中" },
	LOC_BGD_OPT_UI_MESURE_EPINGLES_AIDE = { en_US = "Writes to Lua.log how long map pin and leader ribbon rebuilds take.", fr_FR = "Écrit dans Lua.log la durée des reconstructions d'épingles et du bandeau des dirigeants.", de_DE = "Schreibt in Lua.log, wie lange der Neuaufbau der Kartenmarkierungen und der Anführerleiste dauert.", es_ES = "Escribe en Lua.log cuánto tardan en reconstruirse los marcadores de mapa y la barra de líderes.", it_IT = "Scrive in Lua.log quanto durano le ricostruzioni dei segnalini della mappa e della barra dei leader.", ja_JP = "マップピンと指導者リボンの再構築にかかる時間を Lua.log に書き込みます。", ko_KR = "지도 핀과 지도자 리본을 다시 만드는 데 걸리는 시간을 Lua.log에 기록합니다.", pl_PL = "Zapisuje w Lua.log, ile trwa przebudowa znaczników mapy i paska przywódców.", pt_BR = "Escreve no Lua.log quanto tempo levam as reconstruções dos marcadores do mapa e da faixa de líderes.", ru_RU = "Записывает в Lua.log, сколько длится перестройка меток карты и ленты лидеров.", zh_Hans_CN = "将地图标记和领袖栏重建所需的时间写入 Lua.log。" },
	LOC_BGD_OPT_UI_MESURE_EPINGLES_NOM = { en_US = "Measure map pin cost", fr_FR = "Mesure du coût des épingles", de_DE = "Kosten der Kartenmarkierungen messen", es_ES = "Medir el coste de los marcadores", it_IT = "Misura il costo dei segnalini", ja_JP = "マップピンのコストを計測", ko_KR = "지도 핀 비용 측정", pl_PL = "Pomiar kosztu znaczników", pt_BR = "Medir o custo dos marcadores", ru_RU = "Измерение затрат на метки", zh_Hans_CN = "测量地图标记的开销" },
	LOC_BGD_OPT_UI_MESURE_MOUVEMENTS_AIDE = { en_US = "Writes to Lua.log how long the movement range of a unit standing on an enemy district takes to compute (BGD mouvements lines). Diagnostic only, on this machine.", fr_FR = "Écrit dans Lua.log le temps de calcul de la zone de déplacement d'une unité posée sur un quartier ennemi (lignes BGD mouvements). Diagnostic seulement, sur cette machine.", de_DE = "Schreibt in Lua.log, wie lange die Berechnung des Bewegungsbereichs einer Einheit auf einem feindlichen Bezirk dauert (Zeilen BGD mouvements). Nur zur Diagnose, auf diesem Rechner.", es_ES = "Escribe en Lua.log cuánto tarda en calcularse el área de movimiento de una unidad situada en un distrito enemigo (líneas BGD mouvements). Solo diagnóstico, en este equipo.", it_IT = "Scrive in Lua.log quanto tempo richiede il calcolo dell'area di movimento di un'unità su un distretto nemico (righe BGD mouvements). Solo diagnostica, su questo computer.", ja_JP = "敵の区域上にいるユニットの移動範囲の計算時間を Lua.log に書き込みます（BGD mouvements 行）。このマシンでの診断用のみ。", ko_KR = "적 특수지구 위에 있는 유닛의 이동 범위 계산 시간을 Lua.log에 기록합니다(BGD mouvements 줄). 이 컴퓨터에서의 진단 전용입니다.", pl_PL = "Zapisuje w Lua.log czas obliczania zasięgu ruchu jednostki stojącej na wrogiej dzielnicy (wiersze BGD mouvements). Tylko diagnostyka, na tym komputerze.", pt_BR = "Escreve no Lua.log quanto tempo leva para calcular a área de movimento de uma unidade sobre um distrito inimigo (linhas BGD mouvements). Apenas diagnóstico, nesta máquina.", ru_RU = "Записывает в Lua.log время расчёта зоны перемещения отряда, стоящего на вражеском районе (строки BGD mouvements). Только для диагностики, на этом компьютере.", zh_Hans_CN = "在 Lua.log 中记录位于敌方区域上的单位计算移动范围所需的时间（BGD mouvements 行）。仅用于诊断，仅限本机。" },
	LOC_BGD_OPT_UI_MESURE_MOUVEMENTS_NOM = { en_US = "Measure movement range cost", fr_FR = "Mesure du coût de la zone de déplacement", de_DE = "Kosten des Bewegungsbereichs messen", es_ES = "Medir el coste del área de movimiento", it_IT = "Misura il costo dell'area di movimento", ja_JP = "移動範囲の計算コストを計測", ko_KR = "이동 범위 계산 비용 측정", pl_PL = "Pomiar kosztu zasięgu ruchu", pt_BR = "Medir o custo da área de movimento", ru_RU = "Измерение затрат на зону перемещения", zh_Hans_CN = "测量移动范围的计算开销" },
	LOC_BGD_OPT_UI_NOTIFICATIONS_AIDE = { en_US = "Based on NotificationClear (336tarot). A button in the notification panel dismisses in one click those you can dismiss yourself. Replaces the mod if it is active.", fr_FR = "D'après NotificationClear (336tarot). Un bouton du panneau des notifications ferme d'un clic celles qu'on peut fermer soi-même. Remplace le mod s'il est actif.", de_DE = "Nach NotificationClear (336tarot). Eine Schaltfläche im Benachrichtigungsbereich schließt mit einem Klick alle, die Sie selbst schließen können. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en NotificationClear (336tarot). Un botón del panel de notificaciones cierra de un clic las que puedes cerrar tú mismo. Sustituye al mod si está activo.", it_IT = "Basato su NotificationClear (336tarot). Un pulsante del pannello delle notifiche chiude con un clic quelle che puoi chiudere da solo. Sostituisce la mod se è attiva.", ja_JP = "NotificationClear (336tarot) に基づきます。通知パネルのボタンで、自分で閉じられる通知をワンクリックで閉じます。MOD が有効な場合はそれに置き換わります。", ko_KR = "NotificationClear(336tarot) 기반. 알림 패널의 버튼으로 직접 닫을 수 있는 알림을 한 번에 닫습니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie NotificationClear (336tarot). Przycisk w panelu powiadomień zamyka jednym kliknięciem te, które możesz zamknąć sam. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em NotificationClear (336tarot). Um botão do painel de notificações fecha com um clique aquelas que você pode fechar sozinho. Substitui o mod se ele estiver ativo.", ru_RU = "На основе NotificationClear (336tarot). Кнопка на панели уведомлений одним щелчком закрывает те, которые вы можете закрыть сами. Заменяет мод, если он включён.", zh_Hans_CN = "基于 NotificationClear（336tarot）。通知面板中的按钮可一键关闭所有你能自行关闭的通知。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_NOTIFICATIONS_NOM = { en_US = "Clear notifications button", fr_FR = "Bouton d'effacement des notifications", de_DE = "Schaltfläche zum Löschen der Benachrichtigungen", es_ES = "Botón para borrar las notificaciones", it_IT = "Pulsante per cancellare le notifiche", ja_JP = "通知を消去するボタン", ko_KR = "알림 지우기 버튼", pl_PL = "Przycisk czyszczenia powiadomień", pt_BR = "Botão para limpar as notificações", ru_RU = "Кнопка очистки уведомлений", zh_Hans_CN = "清除通知按钮" },
	LOC_BGD_OPT_UI_NOUVEAUTES_AIDE = { en_US = "Disabled: interface additions from future BetterGameExperience updates arrive disabled, and you can turn them on here whenever you like. Your current interface options keep their values. Fixes are not affected. Enabled again: additions that arrived in the meantime and that you have not set yourself turn on. Local only: no effect on other players.", fr_FR = "Désactivé : les ajouts d'interface des prochaines mises à jour de BetterGameExperience arrivent désactivés, et vous les activez ici quand vous voulez. Les options d'interface actuelles gardent leur valeur. Les correctifs ne sont pas concernés. Réactivé : les ajouts arrivés entre-temps que vous n'avez pas réglés vous-même s'activent. Purement local : sans effet sur les autres joueurs.", de_DE = "Deaktiviert: Oberflächenfunktionen aus künftigen Updates von BetterGameExperience kommen deaktiviert an, und Sie können sie hier jederzeit einschalten. Ihre aktuellen Oberflächenoptionen behalten ihre Werte. Fehlerbehebungen sind nicht betroffen. Wieder aktiviert: Neuerungen, die inzwischen hinzugekommen sind und die Sie nicht selbst eingestellt haben, werden eingeschaltet. Nur lokal: keine Auswirkung auf andere Spieler.", es_ES = "Desactivado: las novedades de interfaz de las próximas actualizaciones de BetterGameExperience llegan desactivadas, y puedes activarlas aquí cuando quieras. Tus opciones de interfaz actuales conservan su valor. Las correcciones no se ven afectadas. Reactivado: las novedades llegadas entretanto que no hayas configurado tú se activan. Solo local: sin efecto sobre los demás jugadores.", it_IT = "Disattivato: le novità dell'interfaccia dei prossimi aggiornamenti di BetterGameExperience arrivano disattivate, e puoi attivarle qui quando vuoi. Le opzioni d'interfaccia attuali mantengono il loro valore. Le correzioni non sono interessate. Riattivato: le novità arrivate nel frattempo che non hai impostato tu si attivano. Solo locale: nessun effetto sugli altri giocatori.", ja_JP = "無効：今後のBetterGameExperienceのアップデートで追加されるインターフェース機能は無効の状態で届き、ここでいつでも有効にできます。現在のインターフェース設定はそのまま保たれます。修正には影響しません。再び有効にすると、その間に追加され、自分で設定していない機能が有効になります。ローカルのみ：他のプレイヤーには影響しません。", ko_KR = "비활성화: 앞으로의 BetterGameExperience 업데이트로 추가되는 인터페이스 기능은 비활성화된 상태로 도착하며, 원할 때 여기서 켤 수 있습니다. 현재 인터페이스 옵션은 그대로 유지됩니다. 수정 사항에는 영향이 없습니다. 다시 활성화하면: 그사이 추가되었고 직접 설정하지 않은 기능이 켜집니다. 로컬 전용: 다른 플레이어에게 영향이 없습니다.", pl_PL = "Wyłączone: nowości interfejsu z kolejnych aktualizacji BetterGameExperience przychodzą wyłączone i możesz je tu włączyć, kiedy chcesz. Obecne opcje interfejsu zachowują swoje wartości. Poprawki nie są objęte. Ponownie włączone: nowości dodane w międzyczasie, których nie ustawiłeś sam, zostają włączone. Tylko lokalnie: bez wpływu na innych graczy.", pt_BR = "Desativado: as novidades de interface das próximas atualizações do BetterGameExperience chegam desativadas, e você pode ativá-las aqui quando quiser. Suas opções de interface atuais mantêm o valor. As correções não são afetadas. Reativado: as novidades que chegaram nesse meio-tempo e que você não configurou são ativadas. Apenas local: sem efeito sobre os outros jogadores.", ru_RU = "Отключено: новые элементы интерфейса из следующих обновлений BetterGameExperience приходят отключёнными, и их можно включить здесь в любой момент. Текущие настройки интерфейса сохраняют свои значения. Исправления не затрагиваются. При повторном включении новые элементы, появившиеся за это время и не настроенные вами, включаются. Только локально: не влияет на других игроков.", zh_Hans_CN = "禁用：BetterGameExperience 今后更新加入的界面功能将以禁用状态到达，你可以随时在此启用。当前的界面选项保持不变。修复不受影响。重新启用：期间加入且你未自行设置的功能将被启用。仅限本地：不影响其他玩家。" },
	LOC_BGD_OPT_UI_NOUVEAUTES_NOM = { en_US = "New interface additions from updates", fr_FR = "Nouveautés d'interface des mises à jour", de_DE = "Neue Oberflächenfunktionen aus Updates", es_ES = "Novedades de interfaz de las actualizaciones", it_IT = "Novità dell'interfaccia dagli aggiornamenti", ja_JP = "アップデートによるインターフェースの新機能", ko_KR = "업데이트로 추가되는 인터페이스 기능", pl_PL = "Nowości interfejsu z aktualizacji", pt_BR = "Novidades de interface das atualizações", ru_RU = "Новые элементы интерфейса из обновлений", zh_Hans_CN = "更新带来的界面新功能" },
	LOC_BGD_OPT_UI_POLITIQUES_AIDE = { en_US = "Based on Extended Policy Cards (Aristos). Each card shows its numeric gain for your empire, computed by Real Modifier Analysis (Infixo), fixed (Raj, Medina Quarter, Monasticism, Civil Prestige, maintenance cards, food on great person cards). No longer needs Better Report Screen. Replaces the mod if it is active.", fr_FR = "D'après Extended Policy Cards (Aristos). Chaque carte montre son gain chiffré pour votre empire, calculé par Real Modifier Analysis (Infixo), corrigé (Raj, Médina, Monachisme, Prestige civil, cartes d'entretien, nourriture des cartes de personnages illustres). Ne demande plus Better Report Screen. Remplace le mod s'il est actif.", de_DE = "Nach Extended Policy Cards (Aristos). Jede Karte zeigt ihren bezifferten Gewinn für Ihr Reich, berechnet von Real Modifier Analysis (Infixo), korrigiert (Raj, Medina-Viertel, Mönchtum, Ziviles Prestige, Unterhaltskarten, Nahrung der Karten für Große Persönlichkeiten). Benötigt Better Report Screen nicht mehr. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Extended Policy Cards (Aristos). Cada carta muestra su ganancia numérica para tu imperio, calculada por Real Modifier Analysis (Infixo), corregida (Raj, Medina, Monacato, Prestigio civil, cartas de mantenimiento, comida de las cartas de grandes personajes). Ya no necesita Better Report Screen. Sustituye al mod si está activo.", it_IT = "Basato su Extended Policy Cards (Aristos). Ogni carta mostra il suo guadagno in cifre per il tuo impero, calcolato da Real Modifier Analysis (Infixo), corretto (Raj, Quartiere della Medina, Monachesimo, Prestigio civile, carte di mantenimento, cibo delle carte dei grandi personaggi). Non richiede più Better Report Screen. Sostituisce la mod se è attiva.", ja_JP = "Extended Policy Cards (Aristos) に基づきます。各カードに、帝国にとっての効果を数値で表示します。計算は Real Modifier Analysis (Infixo) を修正したもの (ラージ、メディナ地区、修道制、市民の威信、維持費カード、偉人カードの食料) です。Better Report Screen は不要になりました。MOD が有効な場合はそれに置き換わります。", ko_KR = "Extended Policy Cards(Aristos) 기반. 각 카드에 제국에 대한 효과를 수치로 표시하며, Real Modifier Analysis(Infixo)를 수정해 계산합니다(영국 식민 통치, 메디나 지구, 수도원주의, 시민의 위신, 유지비 카드, 위인 카드의 식량). 더 이상 Better Report Screen이 필요하지 않습니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Extended Policy Cards (Aristos). Każda karta pokazuje swój liczbowy zysk dla twojego imperium, obliczony przez Real Modifier Analysis (Infixo), poprawiony (Zwierzchnictwo, Medyna, Monastycyzm, Prestiż obywatelski, karty utrzymania, żywność z kart wielkich ludzi). Nie wymaga już Better Report Screen. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Extended Policy Cards (Aristos). Cada cartão mostra o seu ganho numérico para o seu império, calculado pelo Real Modifier Analysis (Infixo), corrigido (Raj, Almedina, Monasticismo, Prestígio civil, cartões de manutenção, comida dos cartões de grandes personalidades). Não precisa mais do Better Report Screen. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Extended Policy Cards (Aristos). Каждая карточка показывает свою выгоду для вашей империи в цифрах, рассчитанную Real Modifier Analysis (Infixo) с исправлениями (Британская Индия, Квартал Медины, Монашество, Гражданский престиж, карточки содержания, пища на карточках великих людей). Better Report Screen больше не нужен. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Extended Policy Cards（Aristos）。每张卡显示其对你帝国的数值收益，由修正后的 Real Modifier Analysis（Infixo）计算（统治、古老城区、修道主义、公民威望、维护费卡、伟人卡的食物）。不再需要 Better Report Screen。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_POLITIQUES_NOM = { en_US = "Policy card effects", fr_FR = "Effet des cartes de politique", de_DE = "Wirkung der Politikkarten", es_ES = "Efecto de las cartas de política", it_IT = "Effetto delle carte politica", ja_JP = "政策カードの効果", ko_KR = "정책 카드 효과", pl_PL = "Efekt kart doktryn", pt_BR = "Efeito dos cartões de política", ru_RU = "Эффект карточек политики", zh_Hans_CN = "政策卡效果" },
	LOC_BGD_OPT_UI_RAPPORTS_AIDE = { en_US = "Based on Better Report Screen (Infixo). Reworked report screen, with Deals, Units, Policies, City-States and Cities tabs, and the effect of each policy and city-state, fixed like the cards. Replaces the mod if it is active.", fr_FR = "D'après Better Report Screen (Infixo). Écran des rapports refait, avec les onglets Accords, Unités, Politiques, Cités-États et Villes, et l'effet de chaque politique et cité-État, corrigé comme les cartes. Remplace le mod s'il est actif.", de_DE = "Nach Better Report Screen (Infixo). Überarbeiteter Berichtsbildschirm mit den Reitern Abkommen, Einheiten, Politiken, Stadtstaaten und Städte sowie der Wirkung jeder Politik und jedes Stadtstaats, korrigiert wie die Karten. Ersetzt den Mod, wenn er aktiv ist.", es_ES = "Basado en Better Report Screen (Infixo). Pantalla de informes rehecha, con las pestañas Acuerdos, Unidades, Políticas, Ciudades-estado y Ciudades, y el efecto de cada política y ciudad-estado, corregido como las cartas. Sustituye al mod si está activo.", it_IT = "Basato su Better Report Screen (Infixo). Schermata dei rapporti rifatta, con le schede Accordi, Unità, Politiche, Città-stato e Città, e l'effetto di ogni politica e città-stato, corretto come le carte. Sostituisce la mod se è attiva.", ja_JP = "Better Report Screen (Infixo) に基づきます。取引、ユニット、政策、都市国家、都市のタブを持つ新しいレポート画面で、各政策と都市国家の効果をカードと同じく修正して表示します。MOD が有効な場合はそれに置き換わります。", ko_KR = "Better Report Screen(Infixo) 기반. 거래, 유닛, 정책, 도시국가, 도시 탭이 있는 새 보고서 화면으로, 각 정책과 도시국가의 효과를 카드와 같이 수정해 보여 줍니다. 모드가 켜져 있으면 모드를 대체합니다.", pl_PL = "Na podstawie Better Report Screen (Infixo). Przebudowany ekran raportów z kartami Umowy, Jednostki, Doktryny, Miasta-państwa i Miasta oraz efektem każdej doktryny i miasta-państwa, poprawionym jak w kartach. Zastępuje moda, jeśli jest aktywny.", pt_BR = "Baseado em Better Report Screen (Infixo). Tela de relatórios refeita, com as abas Acordos, Unidades, Políticas, Cidades-estado e Cidades, e o efeito de cada política e cidade-estado, corrigido como os cartões. Substitui o mod se ele estiver ativo.", ru_RU = "На основе Better Report Screen (Infixo). Переработанный экран отчётов с вкладками «Сделки», «Отряды», «Политика», «Города-государства» и «Города» и эффектом каждой политики и города-государства, исправленным, как на карточках. Заменяет мод, если он включён.", zh_Hans_CN = "基于 Better Report Screen（Infixo）。重做的报告界面，含交易、单位、政策、城邦和城市标签页，并显示每项政策和每个城邦的效果，与政策卡一样经过修正。如果该模组已启用，则取代它。" },
	LOC_BGD_OPT_UI_RAPPORTS_NOM = { en_US = "Better report screen", fr_FR = "Écran des rapports amélioré", de_DE = "Verbesserter Berichtsbildschirm", es_ES = "Pantalla de informes mejorada", it_IT = "Schermata dei rapporti migliorata", ja_JP = "改良されたレポート画面", ko_KR = "개선된 보고서 화면", pl_PL = "Ulepszony ekran raportów", pt_BR = "Tela de relatórios melhorada", ru_RU = "Улучшенный экран отчётов", zh_Hans_CN = "改进的报告界面" },
	LOC_BGD_OPT_UI_RECENTRAGE_AIDE = { en_US = "Original game behavior: the camera recenters on the city when an attack button is clicked.", fr_FR = "Comportement d'origine du jeu : la caméra se recentre sur la ville au clic sur un bouton d'attaque.", de_DE = "Ursprüngliches Verhalten des Spiels: Die Kamera zentriert sich beim Klick auf eine Angriffsschaltfläche auf die Stadt.", es_ES = "Comportamiento original del juego: la cámara se centra en la ciudad al pulsar un botón de ataque.", it_IT = "Comportamento originale del gioco: la visuale si centra sulla città al clic su un pulsante di attacco.", ja_JP = "ゲーム本来の動作: 攻撃ボタンをクリックするとカメラが都市に移動します。", ko_KR = "게임 원래 동작: 공격 버튼을 클릭하면 카메라가 도시로 이동합니다.", pl_PL = "Oryginalne zachowanie gry: po kliknięciu przycisku ataku kamera centruje się na mieście.", pt_BR = "Comportamento original do jogo: a câmera centraliza na cidade ao clicar num botão de ataque.", ru_RU = "Исходное поведение игры: при нажатии кнопки атаки камера центрируется на городе.", zh_Hans_CN = "游戏原本的行为：点击攻击按钮时镜头会移到城市。" },
	LOC_BGD_OPT_UI_RECENTRAGE_NOM = { en_US = "Recenter the camera when clicking these buttons", fr_FR = "Recentrer la caméra au clic sur ces boutons", de_DE = "Kamera beim Klick auf diese Schaltflächen zentrieren", es_ES = "Centrar la cámara al pulsar estos botones", it_IT = "Centra la visuale al clic su questi pulsanti", ja_JP = "これらのボタンのクリック時にカメラを移動", ko_KR = "이 버튼을 클릭하면 카메라 이동", pl_PL = "Centruj kamerę po kliknięciu tych przycisków", pt_BR = "Centralizar a câmera ao clicar nesses botões", ru_RU = "Центрировать камеру при нажатии этих кнопок", zh_Hans_CN = "点击这些按钮时移动镜头" },
	LOC_BGD_OPT_UI_REDUCTION_QUARTIERS_AIDE = { en_US = "In the production list, districts whose cost is currently reduced (fewer of that district than your average) show their discount, updated as soon as a district is placed. Display only.", fr_FR = "Dans la liste de production, les quartiers dont le coût est réduit (moins de quartiers de ce type que votre moyenne) affichent leur réduction, mise à jour dès qu'un quartier est posé. Affichage seulement.", de_DE = "In der Produktionsliste zeigen Bezirke mit gesenkten Kosten (weniger Bezirke dieses Typs als euer Durchschnitt) ihren Rabatt an, aktualisiert, sobald ein Bezirk platziert wird. Nur Anzeige.", es_ES = "En la lista de producción, los distritos cuyo coste está reducido (menos distritos de ese tipo que tu media) muestran su descuento, actualizado en cuanto se coloca un distrito. Solo visualización.", it_IT = "Nell'elenco di produzione, i distretti con costo ridotto (meno distretti di quel tipo della tua media) mostrano lo sconto, aggiornato non appena viene posizionato un distretto. Solo visualizzazione.", ja_JP = "生産リストで、コストが割引されている区域 (その種類の区域数が平均より少ない) に割引率を表示します。区域を配置するとすぐに更新されます。表示のみ。", ko_KR = "생산 목록에서 비용이 할인된 특수지구(해당 종류의 특수지구 수가 평균보다 적음)에 할인율을 표시하며, 특수지구를 배치하면 바로 갱신합니다. 표시만 바뀝니다.", pl_PL = "Na liście produkcji dzielnice o obniżonym koszcie (mniej dzielnic tego typu niż twoja średnia) pokazują zniżkę, odświeżaną od razu po umieszczeniu dzielnicy. Tylko wyświetlanie.", pt_BR = "Na lista de produção, os distritos com custo reduzido (menos distritos desse tipo que a sua média) mostram o desconto, atualizado assim que um distrito é posicionado. Apenas exibição.", ru_RU = "В списке производства районы со сниженной стоимостью (таких районов у вас меньше среднего) показывают скидку; она обновляется сразу после размещения района. Только отображение.", zh_Hans_CN = "在生产列表中，成本降低的区域（该类区域数量少于你的平均值）会显示折扣，放置区域后立即更新。仅影响显示。" },
	LOC_BGD_OPT_UI_REDUCTION_QUARTIERS_NOM = { en_US = "Discounted districts badge", fr_FR = "Badge des quartiers en réduction", de_DE = "Markierung vergünstigter Bezirke", es_ES = "Insignia de distritos con descuento", it_IT = "Indicatore dei distretti scontati", ja_JP = "割引中の区域を表示", ko_KR = "할인 중인 특수지구 표시", pl_PL = "Oznaczenie tańszych dzielnic", pt_BR = "Indicador de distritos com desconto", ru_RU = "Отметка районов со скидкой", zh_Hans_CN = "折扣区域标记" },
	LOC_BGD_OPT_UI_RENDEMENTS_AIDE = { en_US = "The top bar updates after a governor title, a governor move or a great person, without changing a citizen. Display only: no desync.", fr_FR = "Le bandeau du haut se met à jour après un titre de gouverneur, un déplacement de gouverneur ou un personnage illustre, sans changer un citoyen. Affichage seulement : pas de désynchronisation.", de_DE = "Die obere Leiste aktualisiert sich nach einem Gouverneurstitel, einer Gouverneursversetzung oder einer Großen Persönlichkeit, ohne einen Bürger zu verschieben. Nur Anzeige: keine Desynchronisation.", es_ES = "La barra superior se actualiza tras un título de gobernador, un traslado de gobernador o un gran personaje, sin mover a ningún ciudadano. Solo visualización: sin desincronización.", it_IT = "La barra superiore si aggiorna dopo un titolo di governatore, uno spostamento di governatore o un grande personaggio, senza spostare un cittadino. Solo visualizzazione: nessuna desincronizzazione.", ja_JP = "総督の称号、総督の移動、偉人の後に、市民を動かさなくても上部バーが更新されます。表示のみで、同期ずれは起きません。", ko_KR = "총독 칭호, 총독 이동, 위인 이후에 시민을 옮기지 않아도 상단 바가 갱신됩니다. 표시만 바뀌며 동기화 오류는 없습니다.", pl_PL = "Górny pasek odświeża się po tytule gubernatora, przeniesieniu gubernatora lub wielkim człowieku, bez przestawiania obywatela. Tylko wyświetlanie: bez desynchronizacji.", pt_BR = "A barra superior é atualizada após um título de governador, uma transferência de governador ou uma grande personalidade, sem mexer num cidadão. Apenas exibição: sem dessincronização.", ru_RU = "Верхняя панель обновляется после звания губернатора, перевода губернатора или великого человека, без перестановки жителя. Только отображение: без рассинхронизации.", zh_Hans_CN = "在总督头衔、总督调任或伟人之后，无需调整公民，顶部栏也会更新。仅影响显示：不会不同步。" },
	LOC_BGD_OPT_UI_RENDEMENTS_NOM = { en_US = "Empire yields updated after a governor or great person", fr_FR = "Rendements d'empire à jour après un gouverneur ou un personnage illustre", de_DE = "Reichserträge nach Gouverneur oder Großer Persönlichkeit aktuell", es_ES = "Rendimientos del imperio actualizados tras un gobernador o un gran personaje", it_IT = "Rese dell'impero aggiornate dopo un governatore o un grande personaggio", ja_JP = "総督や偉人の後に帝国の産出量を更新", ko_KR = "총독이나 위인 이후 제국 산출량 갱신", pl_PL = "Aktualne plony imperium po gubernatorze lub wielkim człowieku", pt_BR = "Rendimentos do império atualizados após um governador ou uma grande personalidade", ru_RU = "Доходы империи обновляются после губернатора или великого человека", zh_Hans_CN = "总督或伟人之后更新帝国产出" },
	LOC_BGD_OPT_UI_ROUTES_AIDE = { en_US = "The flag of each of your traders on a route shows the number of turns until its trade route ends. The trader then finishes it on returning to its origin city. Display only.", fr_FR = "Le drapeau de chacun de vos négociants en route montre le nombre de tours avant la fin de sa route commerciale. Le négociant la termine ensuite en rentrant à sa ville d'origine. Affichage seulement.", de_DE = "Die Flagge jedes Ihrer Händler auf einem Handelsweg zeigt die Runden bis zum Ende des Handelswegs. Der Händler beendet ihn dann bei der Rückkehr in seine Heimatstadt. Nur Anzeige.", es_ES = "La bandera de cada uno de tus comerciantes en ruta muestra los turnos que faltan para que termine su ruta comercial. Después, el comerciante la termina al volver a su ciudad de origen. Solo visualización.", it_IT = "La bandiera di ciascuno dei tuoi commercianti in viaggio mostra il numero di turni prima della fine della sua rotta commerciale. Il commerciante la conclude poi tornando alla sua città d'origine. Solo visualizzazione.", ja_JP = "交易中の各交易商の旗に、交易路が終わるまでのターン数を表示します。交易商はその後、出発都市に戻った時点で交易路を終えます。表示のみ。", ko_KR = "교역 중인 각 상인의 깃발에 교역로가 끝날 때까지 남은 턴 수를 표시합니다. 상인은 그 뒤 출발 도시로 돌아오면서 교역로를 마칩니다. 표시만 바뀝니다.", pl_PL = "Flaga każdego twojego kupca w drodze pokazuje liczbę tur do końca jego szlaku handlowego. Kupiec kończy go potem po powrocie do miasta pochodzenia. Tylko wyświetlanie.", pt_BR = "A bandeira de cada um dos seus comerciantes em rota mostra o número de turnos até o fim da rota comercial. O comerciante a termina depois, ao voltar para a cidade de origem. Apenas exibição.", ru_RU = "Флаг каждого вашего торговца в пути показывает число ходов до конца его торгового пути. Затем торговец завершает его, вернувшись в родной город. Только отображение.", zh_Hans_CN = "你每个正在运营路线的商人旗帜上，显示其贸易路线结束前的回合数。之后商人回到出发城市时结束该路线。仅影响显示。" },
	LOC_BGD_OPT_UI_ROUTES_NOM = { en_US = "Trade route turns remaining", fr_FR = "Tours restants des routes commerciales", de_DE = "Verbleibende Runden der Handelswege", es_ES = "Turnos restantes de las rutas comerciales", it_IT = "Turni rimanenti delle rotte commerciali", ja_JP = "交易路の残りターン", ko_KR = "교역로 남은 턴", pl_PL = "Pozostałe tury szlaków handlowych", pt_BR = "Turnos restantes das rotas comerciais", ru_RU = "Оставшиеся ходы торговых путей", zh_Hans_CN = "贸易路线剩余回合" },
	LOC_BGD_OPT_VALEUR_FICHIER = { en_US = "{1} (value from file)", fr_FR = "{1} (valeur du fichier)", de_DE = "{1} (Wert aus der Datei)", es_ES = "{1} (valor del archivo)", it_IT = "{1} (valore del file)", ja_JP = "{1} (ファイルの値)", ko_KR = "{1} (파일의 값)", pl_PL = "{1} (wartość z pliku)", pt_BR = "{1} (valor do arquivo)", ru_RU = "{1} (значение из файла)", zh_Hans_CN = "{1}（文件中的值）" },
	LOC_BGD_OPT_VERIF_MAJ_AIDE = { en_US = "When the game starts, looks on GitHub for a new version of BetterGameExperience, and offers it in the main menu. Takes effect the next time the game starts.", fr_FR = "Au lancement du jeu, cherche sur GitHub une nouvelle version de BetterGameExperience, et la propose au menu principal. Prend effet au prochain lancement du jeu.", de_DE = "Sucht beim Spielstart auf GitHub nach einer neuen Version von BetterGameExperience und bietet sie im Hauptmenü an. Wirkt beim nächsten Spielstart.", es_ES = "Al iniciar el juego, busca en GitHub una nueva versión de BetterGameExperience y la ofrece en el menú principal. Surte efecto la próxima vez que se inicie el juego.", it_IT = "All'avvio del gioco, cerca su GitHub una nuova versione di BetterGameExperience e la propone nel menu principale. Ha effetto al prossimo avvio del gioco.", ja_JP = "ゲーム起動時に GitHub で BetterGameExperience の新しいバージョンを探し、メインメニューで案内します。次回のゲーム起動時から有効です。", ko_KR = "게임을 시작할 때 GitHub에서 BetterGameExperience의 새 버전을 찾아 메인 메뉴에서 알려 줍니다. 다음에 게임을 시작할 때부터 적용됩니다.", pl_PL = "Przy uruchomieniu gry szuka w serwisie GitHub nowej wersji BetterGameExperience i proponuje ją w menu głównym. Działa od następnego uruchomienia gry.", pt_BR = "Ao iniciar o jogo, procura no GitHub uma nova versão do BetterGameExperience e a oferece no menu principal. Vale a partir da próxima vez que o jogo for iniciado.", ru_RU = "При запуске игры ищет на GitHub новую версию BetterGameExperience и предлагает её в главном меню. Действует со следующего запуска игры.", zh_Hans_CN = "游戏启动时在 GitHub 上查找 BetterGameExperience 的新版本，并在主菜单中提示。下次启动游戏时生效。" },
	LOC_BGD_OPT_VERIF_MAJ_NOM = { en_US = "Check for updates", fr_FR = "Recherche des mises à jour", de_DE = "Nach Updates suchen", es_ES = "Buscar actualizaciones", it_IT = "Cerca aggiornamenti", ja_JP = "アップデートを確認", ko_KR = "업데이트 확인", pl_PL = "Sprawdzaj aktualizacje", pt_BR = "Procurar atualizações", ru_RU = "Проверять обновления", zh_Hans_CN = "检查更新" },
	LOC_BGD_OPT_VSYNC_CHARGEMENT_AIDE = { en_US = "When VSync is on, the game waits for each screen refresh, and this also slows down the creation of the 3D terrain during a load. It is lifted during loading screens only, and stays as set in game (about 2 s per load). No effect when VSync is off. Takes effect at the next game launch.", fr_FR = "Quand la VSync est activée, le jeu attend chaque rafraîchissement de l'écran, ce qui ralentit aussi la création du terrain 3D pendant un chargement. Elle est levée pendant les écrans de chargement seulement, et reste telle que réglée en jeu (environ 2 s par chargement). Sans effet si la VSync est désactivée. Prend effet au prochain lancement du jeu.", de_DE = "Bei aktivierter VSync wartet das Spiel auf jede Bildschirmaktualisierung, was beim Laden auch den Aufbau des 3D-Geländes verlangsamt. Sie wird nur auf Ladebildschirmen aufgehoben und bleibt im Spiel wie eingestellt (etwa 2 s pro Ladevorgang). Ohne Wirkung, wenn VSync deaktiviert ist. Wirkt ab dem nächsten Spielstart.", es_ES = "Con la VSync activada, el juego espera cada refresco de la pantalla, lo que también ralentiza la creación del terreno 3D durante una carga. Se desactiva solo durante las pantallas de carga y en la partida sigue como esté configurada (unos 2 s por carga). Sin efecto si la VSync está desactivada. Se aplica en el próximo inicio del juego.", it_IT = "Con la VSync attiva, il gioco attende ogni aggiornamento dello schermo, il che rallenta anche la creazione del terreno 3D durante un caricamento. Viene sospesa solo durante le schermate di caricamento e in partita resta come impostata (circa 2 s per caricamento). Nessun effetto se la VSync è disattivata. Ha effetto al prossimo avvio del gioco.", ja_JP = "垂直同期が有効な場合、ゲームは画面の更新ごとに待機し、ロード中の3D地形の作成も遅くなります。ロード画面の間だけ解除され、ゲーム中は設定どおりのままです（ロード1回あたり約2秒）。垂直同期が無効なら影響はありません。次回のゲーム起動時に有効になります。", ko_KR = "수직 동기화가 켜져 있으면 게임이 화면 갱신마다 기다리며, 이 때문에 로딩 중 3D 지형 생성도 느려집니다. 로딩 화면에서만 해제되고 게임 중에는 설정대로 유지됩니다(로딩당 약 2초). 수직 동기화가 꺼져 있으면 영향이 없습니다. 다음 게임 실행 시 적용됩니다.", pl_PL = "Gdy VSync jest włączony, gra czeka na każde odświeżenie ekranu, co spowalnia też tworzenie terenu 3D podczas wczytywania. Jest wyłączany tylko na ekranach wczytywania, a w grze pozostaje zgodnie z ustawieniem (około 2 s na wczytanie). Bez efektu, gdy VSync jest wyłączony. Działa od następnego uruchomienia gry.", pt_BR = "Com o VSync ativado, o jogo espera cada atualização da tela, o que também atrasa a criação do terreno 3D durante um carregamento. Ele é suspenso apenas nas telas de carregamento e, na partida, continua como configurado (cerca de 2 s por carregamento). Sem efeito se o VSync estiver desativado. Entra em vigor no próximo início do jogo.", ru_RU = "Когда VSync включена, игра ждёт каждого обновления экрана, и это также замедляет создание 3D-ландшафта при загрузке. Она отключается только на экранах загрузки, а в партии остаётся как настроено (около 2 с на загрузку). Без эффекта, если VSync выключена. Вступает в силу при следующем запуске игры.", zh_Hans_CN = "开启垂直同步时，游戏会等待每次屏幕刷新，这也会拖慢加载时 3D 地形的创建。仅在加载画面期间解除，游戏中仍按设置保持（每次加载约 2 秒）。关闭垂直同步时无影响。下次启动游戏时生效。" },
	LOC_BGD_OPT_VSYNC_CHARGEMENT_NOM = { en_US = "No VSync on loading screens", fr_FR = "Pas de VSync sur les écrans de chargement", de_DE = "Keine VSync auf Ladebildschirmen", es_ES = "Sin VSync en las pantallas de carga", it_IT = "Niente VSync nelle schermate di caricamento", ja_JP = "ロード画面で垂直同期を無効化", ko_KR = "로딩 화면에서 수직 동기화 해제", pl_PL = "Bez VSync na ekranach wczytywania", pt_BR = "Sem VSync nas telas de carregamento", ru_RU = "Без VSync на экранах загрузки", zh_Hans_CN = "加载画面不使用垂直同步" },
	LOC_BGD_OPT_WMD_ACCEL_AIDE = { en_US = "Only with quick combat enabled (Game tab). Speeds up the display during the strike, with no effect on the game.", fr_FR = "Seulement si le combat rapide est activé (onglet Jeu). Accélère l'affichage pendant la frappe, sans effet sur la partie.", de_DE = "Nur mit aktiviertem Schnellkampf (Reiter Spiel). Beschleunigt die Anzeige während des Schlags, ohne Auswirkung auf das Spiel.", es_ES = "Solo con el combate rápido activado (pestaña Juego). Acelera la visualización durante el ataque, sin efecto en la partida.", it_IT = "Solo con il combattimento rapido attivato (scheda Gioco). Accelera la visualizzazione durante l'attacco, senza effetti sulla partita.", ja_JP = "クイック戦闘が有効な場合のみ (ゲームタブ)。攻撃中の表示を高速化します。ゲーム内容には影響しません。", ko_KR = "빠른 전투가 켜져 있을 때만 적용됩니다(게임 탭). 공격 중 화면 표시를 빠르게 하며, 게임에는 영향이 없습니다.", pl_PL = "Tylko przy włączonej szybkiej walce (karta Gra). Przyspiesza wyświetlanie podczas ataku, bez wpływu na rozgrywkę.", pt_BR = "Apenas com o combate rápido ativado (aba Jogo). Acelera a exibição durante o ataque, sem efeito na partida.", ru_RU = "Только при включённом быстром бое (вкладка «Игра»). Ускоряет показ во время удара, не влияя на партию.", zh_Hans_CN = "仅在开启快速战斗时有效（游戏标签页）。加速打击过程中的显示，不影响游戏。" },
	LOC_BGD_OPT_WMD_ACCEL_NOM = { en_US = "Nuclear strike animation speed-up", fr_FR = "Accélération de l'animation des armes nucléaires", de_DE = "Beschleunigte Animation von Atomschlägen", es_ES = "Animación acelerada de los ataques nucleares", it_IT = "Animazione accelerata degli attacchi nucleari", ja_JP = "核攻撃アニメーションの高速化", ko_KR = "핵 공격 애니메이션 가속", pl_PL = "Przyspieszona animacja ataków jądrowych", pt_BR = "Animação acelerada dos ataques nucleares", ru_RU = "Ускорение анимации ядерных ударов", zh_Hans_CN = "加速核打击动画" },
	LOC_BGD_PINGS_AMBIGUOUS = { en_US = "That name is shared. Use #seat.", fr_FR = "Plusieurs joueurs portent ce nom. Utilisez #numéro.", de_DE = "Mehrere Spieler haben diesen Namen. Verwende #Platznummer.", es_ES = "Varios jugadores tienen ese nombre. Usa #puesto.", it_IT = "Più giocatori hanno questo nome. Usa #posto.", ja_JP = "同じ名前のプレイヤーがいます。#席番号を指定してください。", ko_KR = "같은 이름이 여러 명입니다. #자리번호를 사용하세요.", pl_PL = "Kilku graczy ma tę nazwę. Użyj #numeru miejsca.", pt_BR = "Há mais de um jogador com esse nome. Use #posição.", ru_RU = "Это имя у нескольких игроков. Укажите #номер места.", zh_Hans_CN = "有多名玩家使用此名称，请使用 #席位号。" },
	LOC_BGD_PINGS_ASSIST = { en_US = "Assist me", fr_FR = "À l’aide", de_DE = "Brauche Hilfe", es_ES = "Necesito ayuda", it_IT = "Aiutatemi", ja_JP = "援護を要請", ko_KR = "지원 요청", pl_PL = "Potrzebuję pomocy", pt_BR = "Preciso de ajuda", ru_RU = "Нужна помощь", zh_Hans_CN = "请求支援" },
