	LOC_BGD_RAPPORT_DESCRIPTION = { en_US = "Describe the problem: what happened, when, and what you expected instead.", fr_FR = "Décrivez le problème : ce qui s'est passé, à quel moment, et ce que vous attendiez à la place.", de_DE = "Beschreiben Sie das Problem: was passiert ist, wann, und was Sie stattdessen erwartet haben.", es_ES = "Describe el problema: qué ha pasado, cuándo y qué esperabas en su lugar.", it_IT = "Descrivi il problema: cosa è successo, quando e cosa ti aspettavi invece.", ja_JP = "問題を説明してください：何が起きたか、いつ起きたか、本来どうなるはずだったか。", ko_KR = "문제를 설명해 주세요: 무슨 일이 언제 일어났는지, 원래 어떻게 될 것으로 예상했는지.", pl_PL = "Opisz problem: co się stało, kiedy i czego oczekiwałeś zamiast tego.", pt_BR = "Descreva o problema: o que aconteceu, quando e o que você esperava em vez disso.", ru_RU = "Опишите проблему: что произошло, когда и чего вы ожидали вместо этого.", zh_Hans_CN = "请描述问题：发生了什么、在什么时候，以及你原本期望的结果。" },
	LOC_BGD_RAPPORT_EN_COURS = { en_US = "Sending the report...[NEWLINE]You can close this window: the sending continues.", fr_FR = "Envoi du rapport en cours...[NEWLINE]Vous pouvez fermer cette fenêtre : l'envoi continue.", de_DE = "Bericht wird gesendet ...[NEWLINE]Sie können dieses Fenster schließen: Das Senden läuft weiter.", es_ES = "Enviando el informe...[NEWLINE]Puedes cerrar esta ventana: el envío continúa.", it_IT = "Invio della segnalazione in corso...[NEWLINE]Puoi chiudere questa finestra: l'invio continua.", ja_JP = "レポートを送信中...[NEWLINE]このウィンドウを閉じても送信は続きます。", ko_KR = "보고서를 보내는 중...[NEWLINE]이 창을 닫아도 전송은 계속됩니다.", pl_PL = "Wysyłanie zgłoszenia...[NEWLINE]Możesz zamknąć to okno: wysyłanie będzie kontynuowane.", pt_BR = "Enviando o relatório...[NEWLINE]Você pode fechar esta janela: o envio continua.", ru_RU = "Отправка отчёта...[NEWLINE]Это окно можно закрыть: отправка продолжится.", zh_Hans_CN = "正在发送报告...[NEWLINE]你可以关闭此窗口：发送会继续进行。" },
	LOC_BGD_RAPPORT_FERMER = { en_US = "Close", fr_FR = "Fermer", de_DE = "Schließen", es_ES = "Cerrar", it_IT = "Chiudi", ja_JP = "閉じる", ko_KR = "닫기", pl_PL = "Zamknij", pt_BR = "Fechar", ru_RU = "Закрыть", zh_Hans_CN = "关闭" },
	LOC_BGD_RAPPORT_INFOBULLE = { en_US = "Sends a save, the last autosaves and the game logs to the BetterGameExperience team. In multiplayer, the other players are told in the chat.", fr_FR = "Envoie une sauvegarde, les derniers autosaves et les journaux du jeu à l'équipe de BetterGameExperience. En multijoueur, les autres joueurs sont prévenus dans le chat.", de_DE = "Sendet einen Spielstand, die letzten automatischen Spielstände und die Spielprotokolle an das Team von BetterGameExperience. Im Mehrspielermodus werden die anderen Spieler im Chat informiert.", es_ES = "Envía una partida guardada, los últimos autoguardados y los registros del juego al equipo de BetterGameExperience. En multijugador, se avisa a los demás jugadores en el chat.", it_IT = "Invia un salvataggio, gli ultimi salvataggi automatici e i registri del gioco al team di BetterGameExperience. In multigiocatore, gli altri giocatori vengono avvisati nella chat.", ja_JP = "セーブデータ、最新のオートセーブ、ゲームのログを BetterGameExperience チームに送信します。マルチプレイでは、他のプレイヤーにチャットで知らせます。", ko_KR = "저장 파일, 최근 자동 저장 파일, 게임 로그를 BetterGameExperience 팀에 보냅니다. 멀티플레이에서는 다른 플레이어에게 채팅으로 알립니다.", pl_PL = "Wysyła zapis gry, ostatnie autozapisy i dzienniki gry do zespołu BetterGameExperience. W grze wieloosobowej pozostali gracze są powiadamiani na czacie.", pt_BR = "Envia um jogo salvo, os últimos salvamentos automáticos e os registros do jogo para a equipe do BetterGameExperience. No multijogador, os outros jogadores são avisados no chat.", ru_RU = "Отправляет сохранение, последние автосохранения и журналы игры команде BetterGameExperience. В сетевой игре остальные игроки получают сообщение в чате.", zh_Hans_CN = "向 BetterGameExperience 团队发送一个存档、最近的自动存档和游戏日志。在多人游戏中，会在聊天中通知其他玩家。" },
	LOC_BGD_RAPPORT_LOCAL_ECHEC = { en_US = "The bug report could not be sent. The archive was saved here: {1}. Send it to @goaterino in a private message on Discord.", fr_FR = "Le rapport de bug n'a pas pu être envoyé. L'archive est enregistrée ici : {1}. Envoyez-la à @goaterino en message privé sur Discord.", de_DE = "Der Fehlerbericht konnte nicht gesendet werden. Das Archiv wurde hier gespeichert: {1}. Senden Sie es per Privatnachricht auf Discord an @goaterino.", es_ES = "No se ha podido enviar el informe de error. El archivo se ha guardado aquí: {1}. Envíalo a @goaterino por mensaje privado en Discord.", it_IT = "Non è stato possibile inviare la segnalazione del bug. L'archivio è stato salvato qui: {1}. Invialo a @goaterino in un messaggio privato su Discord.", ja_JP = "バグレポートを送信できませんでした。アーカイブの保存先: {1}。Discord の個人メッセージで @goaterino に送ってください。", ko_KR = "버그 보고서를 보내지 못했습니다. 압축 파일 저장 위치: {1}. Discord 개인 메시지로 @goaterino 님에게 보내 주세요.", pl_PL = "Nie udało się wysłać zgłoszenia błędu. Archiwum zapisano tutaj: {1}. Wyślij je do @goaterino w prywatnej wiadomości na Discordzie.", pt_BR = "Não foi possível enviar o relatório de bug. O arquivo foi salvo aqui: {1}. Envie-o para @goaterino por mensagem privada no Discord.", ru_RU = "Не удалось отправить отчёт об ошибке. Архив сохранён здесь: {1}. Отправьте его @goaterino в личном сообщении в Discord.", zh_Hans_CN = "错误报告未能发送。压缩包已保存到：{1}。请通过 Discord 私信将其发送给 @goaterino。" },
	LOC_BGD_RAPPORT_LOCAL_OK = { en_US = "Bug report sent, number {1}. To add details, send this number to @goaterino in a private message on Discord.", fr_FR = "Rapport de bug envoyé, numéro {1}. Pour ajouter des détails, envoyez ce numéro à @goaterino en message privé sur Discord.", de_DE = "Fehlerbericht gesendet, Nummer {1}. Um Details zu ergänzen, senden Sie diese Nummer per Privatnachricht auf Discord an @goaterino.", es_ES = "Informe de error enviado, número {1}. Para añadir detalles, envía este número a @goaterino por mensaje privado en Discord.", it_IT = "Segnalazione del bug inviata, numero {1}. Per aggiungere dettagli, invia questo numero a @goaterino in un messaggio privato su Discord.", ja_JP = "バグレポートを送信しました（番号 {1}）。詳細を追加するには、この番号を Discord の個人メッセージで @goaterino に送ってください。", ko_KR = "버그 보고서를 보냈습니다(번호 {1}). 자세한 내용을 추가하려면 이 번호를 Discord 개인 메시지로 @goaterino 님에게 보내 주세요.", pl_PL = "Zgłoszenie błędu wysłane, numer {1}. Aby dodać szczegóły, wyślij ten numer do @goaterino w prywatnej wiadomości na Discordzie.", pt_BR = "Relatório de bug enviado, número {1}. Para adicionar detalhes, envie este número para @goaterino por mensagem privada no Discord.", ru_RU = "Отчёт об ошибке отправлен, номер {1}. Чтобы добавить подробности, отправьте этот номер @goaterino в личном сообщении в Discord.", zh_Hans_CN = "错误报告已发送，编号 {1}。如需补充细节，请通过 Discord 私信将此编号发送给 @goaterino。" },
	LOC_BGD_RAPPORT_TEXTE = { en_US = "BetterGameExperience will send its team a save of this moment, the last autosaves and the game logs. Your Windows user name is removed from the logs.", fr_FR = "BetterGameExperience va envoyer à son équipe une sauvegarde de ce moment, les derniers autosaves et les journaux du jeu. Votre nom d'utilisateur Windows est retiré des journaux.", de_DE = "BetterGameExperience sendet seinem Team einen Spielstand dieses Moments, die letzten automatischen Spielstände und die Spielprotokolle. Ihr Windows-Benutzername wird aus den Protokollen entfernt.", es_ES = "BetterGameExperience enviará a su equipo una partida guardada de este momento, los últimos autoguardados y los registros del juego. Tu nombre de usuario de Windows se elimina de los registros.", it_IT = "BetterGameExperience invierà al suo team un salvataggio di questo momento, gli ultimi salvataggi automatici e i registri del gioco. Il tuo nome utente di Windows viene rimosso dai registri.", ja_JP = "BetterGameExperience は、この時点のセーブデータ、最新のオートセーブ、ゲームのログをチームに送信します。Windows のユーザー名はログから削除されます。", ko_KR = "BetterGameExperience가 현재 시점의 저장 파일, 최근 자동 저장 파일, 게임 로그를 팀에 보냅니다. Windows 사용자 이름은 로그에서 제거됩니다.", pl_PL = "BetterGameExperience wyśle swojemu zespołowi zapis z tej chwili, ostatnie autozapisy i dzienniki gry. Twoja nazwa użytkownika Windows zostaje usunięta z dzienników.", pt_BR = "O BetterGameExperience vai enviar à sua equipe um jogo salvo deste momento, os últimos salvamentos automáticos e os registros do jogo. Seu nome de usuário do Windows é removido dos registros.", ru_RU = "BetterGameExperience отправит своей команде сохранение этого момента, последние автосохранения и журналы игры. Ваше имя пользователя Windows удаляется из журналов.", zh_Hans_CN = "BetterGameExperience 将向其团队发送此刻的存档、最近的自动存档和游戏日志。你的 Windows 用户名会从日志中删除。" },
	LOC_BGD_RAPPORT_TITRE = { en_US = "Report a bug", fr_FR = "Signaler un bug", de_DE = "Fehler melden", es_ES = "Informar de un error", it_IT = "Segnala un bug", ja_JP = "バグを報告", ko_KR = "버그 신고", pl_PL = "Zgłoś błąd", pt_BR = "Relatar um bug", ru_RU = "Сообщить об ошибке", zh_Hans_CN = "报告错误" },
	LOC_BGD_RAPPORT_VERSION_NON_SUPPORTEE = { en_US = "Bug reports are turned off: BetterGameExperience does not support version {1} of the game, and none of its fixes are active. Update the game on Steam to its current version.", fr_FR = "Les rapports de bug sont désactivés : BetterGameExperience ne prend pas en charge la version {1} du jeu, et aucun de ses correctifs n'est actif. Mettez le jeu à jour sur Steam, à sa version actuelle.", de_DE = "Fehlerberichte sind deaktiviert: BetterGameExperience unterstützt die Spielversion {1} nicht, und keine seiner Korrekturen ist aktiv. Aktualisiere das Spiel über Steam auf die aktuelle Version.", es_ES = "Los informes de errores están desactivados: BetterGameExperience no es compatible con la versión {1} del juego y ninguna de sus correcciones está activa. Actualiza el juego en Steam a su versión actual.", it_IT = "Le segnalazioni di bug sono disattivate: BetterGameExperience non supporta la versione {1} del gioco e nessuna delle sue correzioni è attiva. Aggiorna il gioco su Steam alla versione attuale.", ja_JP = "バグ報告は無効です。BetterGameExperience はゲームのバージョン {1} に対応しておらず、修正はどれも有効になっていません。Steam でゲームを最新バージョンに更新してください。", ko_KR = "버그 신고가 꺼져 있습니다. BetterGameExperience는 게임 버전 {1}을(를) 지원하지 않으며, 어떤 수정도 활성화되지 않았습니다. Steam에서 게임을 최신 버전으로 업데이트하세요.", pl_PL = "Zgłaszanie błędów jest wyłączone: BetterGameExperience nie obsługuje wersji gry {1} i żadna z jego poprawek nie jest aktywna. Zaktualizuj grę na Steamie do aktualnej wersji.", pt_BR = "Os relatórios de bug estão desativados: o BetterGameExperience não é compatível com a versão {1} do jogo, e nenhuma das suas correções está ativa. Atualize o jogo na Steam para a versão atual.", ru_RU = "Отчёты об ошибках отключены: BetterGameExperience не поддерживает версию игры {1}, и ни одно из его исправлений не работает. Обновите игру в Steam до текущей версии.", zh_Hans_CN = "错误报告已关闭：BetterGameExperience 不支持游戏版本 {1}，它的修复均未启用。请在 Steam 上将游戏更新到当前版本。" },
	LOC_BGD_ROUTE_AIDE = { en_US = "Trade route: ends in {1} turn(s), when the trader returns to its origin city.", fr_FR = "Route commerciale : fin dans {1} tour(s), au retour du négociant dans sa ville d'origine.", de_DE = "Handelsweg: endet in {1} Runde(n), wenn der Händler in seine Heimatstadt zurückkehrt.", es_ES = "Ruta comercial: termina en {1} turno(s), cuando el comerciante vuelva a su ciudad de origen.", it_IT = "Rotta commerciale: termina tra {1} turno/i, quando il commerciante torna alla sua città d'origine.", ja_JP = "交易路: あと {1} ターンで、交易商が出発都市に戻ったときに終わります。", ko_KR = "교역로: {1}턴 뒤, 상인이 출발 도시로 돌아오면 끝납니다.", pl_PL = "Szlak handlowy: kończy się za {1} tur(y), gdy kupiec wróci do miasta pochodzenia.", pt_BR = "Rota comercial: termina em {1} turno(s), quando o comerciante voltar à cidade de origem.", ru_RU = "Торговый путь: закончится через {1} ход(а), когда торговец вернётся в родной город.", zh_Hans_CN = "贸易路线：{1} 回合后，在商人回到出发城市时结束。" },
	LOC_BGD_ROUTE_OR_DESTINATION = { en_US = "+{1} {2} {3} from {4}, received by {5}", fr_FR = "+{1} {2} {3} grâce à {4}, reçus par {5}", de_DE = "+{1} {2} {3} durch {4}, erhalten von {5}", es_ES = "+{1} {2} {3} por {4}, recibido por {5}", it_IT = "+{1} {2} {3} da {4}, ricevuto da {5}", ja_JP = "{4}により+{1} {2} {3}（{5}が受け取る）", ko_KR = "{4}(으)로 +{1} {2} {3}, {5}에서 받음", pl_PL = "+{1} {2} {3} dzięki {4}, otrzymuje {5}", pt_BR = "+{1} {2} {3} por {4}, recebido por {5}", ru_RU = "+{1} {2} {3} от «{4}», получает {5}", zh_Hans_CN = "{4}：+{1} {2} {3}，由{5}获得" },
	LOC_BGD_SALON_CHECK_AIDE = { en_US = "Asks every player which BetterGameExperience version they have, then posts the result in the chat for everyone.", fr_FR = "Demande à chaque joueur sa version de BetterGameExperience, puis écrit le bilan dans le chat pour tous.", de_DE = "Fragt jeden Spieler nach seiner BetterGameExperience-Version und schreibt das Ergebnis für alle in den Chat.", es_ES = "Pregunta a cada jugador su versión de BetterGameExperience y luego publica el resultado en el chat para todos.", it_IT = "Chiede a ogni giocatore la sua versione di BetterGameExperience, poi scrive il risultato nella chat per tutti.", ja_JP = "各プレイヤーに BetterGameExperience のバージョンを問い合わせ、結果を全員のチャットに表示します。", ko_KR = "모든 플레이어에게 BetterGameExperience 버전을 묻고, 결과를 모두의 채팅에 표시합니다.", pl_PL = "Pyta każdego gracza o jego wersję BetterGameExperience, a następnie publikuje wynik na czacie dla wszystkich.", pt_BR = "Pergunta a cada jogador a sua versão do BetterGameExperience e depois publica o resultado no chat para todos.", ru_RU = "Запрашивает у каждого игрока его версию BetterGameExperience и публикует итог в чате для всех.", zh_Hans_CN = "询问每位玩家的 BetterGameExperience 版本，然后在聊天中向所有人公布结果。" },
	LOC_BGD_VERSION_NON_SUPPORTEE_COURT = { en_US = "BGE: game {1} not supported", fr_FR = "BGE : jeu {1} non pris en charge", de_DE = "BGE: Spiel {1} nicht unterstützt", es_ES = "BGE: juego {1} no compatible", it_IT = "BGE: gioco {1} non supportato", ja_JP = "BGE: ゲーム {1} は非対応", ko_KR = "BGE: 게임 {1} 미지원", pl_PL = "BGE: gra {1} nieobsługiwana", pt_BR = "BGE: jogo {1} não compatível", ru_RU = "BGE: игра {1} не поддерживается", zh_Hans_CN = "BGE：不支持游戏 {1}" },
	LOC_BGD_VERSION_NON_SUPPORTEE_TEXTE = { en_US = "BetterGameExperience does not support version {1} of the game: none of its fixes are active.[NEWLINE][NEWLINE]Update the game on Steam to its current version. Please do not report problems seen with this version: they do not come from BetterGameExperience.", fr_FR = "BetterGameExperience ne prend pas en charge la version {1} du jeu : aucun de ses correctifs n'est actif.[NEWLINE][NEWLINE]Mettez le jeu à jour sur Steam, à sa version actuelle. Merci de ne pas signaler les problèmes vus avec cette version : ils ne viennent pas de BetterGameExperience.", de_DE = "BetterGameExperience unterstützt die Spielversion {1} nicht: Keine seiner Korrekturen ist aktiv.[NEWLINE][NEWLINE]Aktualisiere das Spiel über Steam auf die aktuelle Version. Bitte melde keine Probleme mit dieser Version: Sie stammen nicht von BetterGameExperience.", es_ES = "BetterGameExperience no es compatible con la versión {1} del juego: ninguna de sus correcciones está activa.[NEWLINE][NEWLINE]Actualiza el juego en Steam a su versión actual. Por favor, no informes de problemas vistos con esta versión: no vienen de BetterGameExperience.", it_IT = "BetterGameExperience non supporta la versione {1} del gioco: nessuna delle sue correzioni è attiva.[NEWLINE][NEWLINE]Aggiorna il gioco su Steam alla versione attuale. Per favore, non segnalare problemi visti con questa versione: non dipendono da BetterGameExperience.", ja_JP = "BetterGameExperience はゲームのバージョン {1} に対応していません。修正はどれも有効になっていません。[NEWLINE][NEWLINE]Steam でゲームを最新バージョンに更新してください。このバージョンで起きた問題は BetterGameExperience によるものではないため、報告しないでください。", ko_KR = "BetterGameExperience는 게임 버전 {1}을(를) 지원하지 않습니다. 어떤 수정도 활성화되지 않았습니다.[NEWLINE][NEWLINE]Steam에서 게임을 최신 버전으로 업데이트하세요. 이 버전에서 생긴 문제는 BetterGameExperience 때문이 아니므로 신고하지 마세요.", pl_PL = "BetterGameExperience nie obsługuje wersji gry {1}: żadna z jego poprawek nie jest aktywna.[NEWLINE][NEWLINE]Zaktualizuj grę na Steamie do aktualnej wersji. Prosimy nie zgłaszać problemów z tą wersją: nie pochodzą one od BetterGameExperience.", pt_BR = "O BetterGameExperience não é compatível com a versão {1} do jogo: nenhuma das suas correções está ativa.[NEWLINE][NEWLINE]Atualize o jogo na Steam para a versão atual. Por favor, não relate problemas vistos com esta versão: eles não vêm do BetterGameExperience.", ru_RU = "BetterGameExperience не поддерживает версию игры {1}: ни одно из его исправлений не работает.[NEWLINE][NEWLINE]Обновите игру в Steam до текущей версии. Пожалуйста, не сообщайте о проблемах с этой версией: они не связаны с BetterGameExperience.", zh_Hans_CN = "BetterGameExperience 不支持游戏版本 {1}：它的修复均未启用。[NEWLINE][NEWLINE]请在 Steam 上将游戏更新到当前版本。请勿报告在此版本中遇到的问题：它们并非由 BetterGameExperience 引起。" },
	LOC_BGD_VERSION_NON_SUPPORTEE_TITRE = { en_US = "Game version not supported", fr_FR = "Version du jeu non prise en charge", de_DE = "Spielversion nicht unterstützt", es_ES = "Versión del juego no compatible", it_IT = "Versione del gioco non supportata", ja_JP = "非対応のゲームバージョン", ko_KR = "지원하지 않는 게임 버전", pl_PL = "Nieobsługiwana wersja gry", pt_BR = "Versão do jogo não compatível", ru_RU = "Версия игры не поддерживается", zh_Hans_CN = "不支持的游戏版本" },
